(function(root){'use strict';const reviewed={"34.1":[["En plan spegel bildar varje punkt lika långt bakom spegelytan som motsvarande punkt är framför.","Bilden ligger därför 39,2 cm bakom spegeln. Förstoringen är +1, så den virtuella upprätta bilden är 4,85 cm hög."],["A plane mirror places each image point as far behind its surface as the object point is in front.","The image is therefore 39.2 cm behind the mirror. Magnification is +1, so the virtual upright image is 4.85 cm tall."]],"34.2":[["Den virtuella trädbilden ligger 20,0 m bakom spegeln. Avståndet från ögat till bilden är därför 20,0+0,340 = 20,34 m.","Likformiga trianglar ger H/20,34 m = 0,0370 m/0,340 m. Trädets höjd är H ≈ 2,21 m i den paraxiella geometrin."],["The virtual tree image is 20.0 m behind the mirror. Its distance from the eye is therefore 20.0+0.340 = 20.34 m.","Similar triangles give H/20.34 m = 0.0370 m/0.340 m. Tree height is H ≈ 2.21 m in the paraxial geometry."]],"34.3":[["Varje bildpunkt ligger lika långt bakom spegeln som motsvarande föremålspunkt framför: spetsens bild ligger 12,0 cm bakom och suddgummits bild 21,0 cm bakom.","Bildens längd är 21,0−12,0 = 9,0 cm. Spetsens bild är närmast spegeln."],["Each image point is as far behind the mirror as the object point is in front: the tip image is 12.0 cm behind and the eraser image 21.0 cm behind.","Image length is 21.0−12.0 = 9.0 cm. The tip image is closest to the mirror."]],"34.4":[["För en paraxiell konkav sfärisk spegel är f = R/2 = 36,0/2 = +18,0 cm.","Reflektionslagen beror inte på det homogena omgivande mediets brytningsindex. Brännvidden är därför +18,0 cm både i luft och i vatten i denna modell."],["For a paraxial concave spherical mirror f = R/2 = 36.0/2 = +18.0 cm.","The law of reflection does not depend on the refractive index of a homogeneous surrounding medium. Focal length is therefore +18.0 cm in both air and water in this model."]],"34.5":[["Konkav spegel ger f = R/2 = +11,0 cm. Med s = 16,5 cm ger spegelekvationen 1/s′ = 1/f−1/s = 1/11,0−1/16,5, alltså s′ = +33,0 cm.","Förstoringen är m = −s′/s = −2,00 och bildhöjden h′ = mh = −1,20 cm. Positivt s′ och negativ höjd betyder reell, inverterad bild framför spegeln.","I stråldiagrammet reflekteras en axelparallell stråle genom fokus och en stråle genom fokus parallellt med axeln. Deras skärning ger bilden."],["The concave mirror has f = R/2 = +11.0 cm. With s = 16.5 cm, the mirror equation gives 1/s′ = 1/f−1/s = 1/11.0−1/16.5, hence s′ = +33.0 cm.","Magnification is m = −s′/s = −2.00 and image height h′ = mh = −1.20 cm. Positive s′ and negative height mean a real inverted image in front of the mirror.","In the ray diagram an axis-parallel ray reflects through focus and a ray through focus reflects parallel to the axis. Their intersection locates the image."]],"34.6":[["För en konvex spegel är f = −R/2 = −11,0 cm. Med s = 16,5 cm ger 1/s′ = 1/f−1/s bildavståndet s′ = −6,60 cm.","m = −s′/s = +0,400 och h′ = mh = +0,240 cm. Bilden är virtuell, upprätt och förminskad bakom spegeln.","De reflekterade strålarna divergerar; deras bakåtförlängningar skär varandra i den virtuella bilden."],["For a convex mirror f = −R/2 = −11.0 cm. With s = 16.5 cm, 1/s′ = 1/f−1/s gives image distance s′ = −6.60 cm.","m = −s′/s = +0.400 and h′ = mh = +0.240 cm. The image is virtual, upright and reduced behind the mirror.","The reflected rays diverge; their backward extensions intersect at the virtual image."]],"34.7":[["Den lilla vinkeldiametern är ungefär D/d = 6 794/(5,58·10⁷) rad. Ett avlägset objekt bildas nära spegelns fokus.","Bilddiametern blir ungefär fD/d = (1,85)(6 794)/(5,58·10⁷) ≈ 2,25·10⁻⁴ m = 0,225 mm."],["The small angular diameter is approximately D/d = 6,794/(5.58×10⁷) rad. A distant object forms an image near the mirror focus.","Image diameter is approximately fD/d = (1.85)(6,794)/(5.58×10⁷) ≈ 2.25×10⁻⁴ m = 0.225 mm."]],"34.8":[["Kulans radie är 5,80/2 = 2,90 cm. Avståndet från föremålet till närmaste spegelytan är s = 24,1−2,90 = 21,2 cm.","Den konvexa spegeln har f = −2,90/2 = −1,45 cm. Spegelekvationen ger s′ ≈ −1,36 cm.","m = −s′/s ≈ +0,0640. Bilden är virtuell och upprätt bakom ytan."],["The ornament radius is 5.80/2 = 2.90 cm. Object distance to the nearest mirror surface is s = 24.1−2.90 = 21.2 cm.","The convex mirror has f = −2.90/2 = −1.45 cm. The mirror equation gives s′ ≈ −1.36 cm.","m = −s′/s ≈ +0.0640. The image is virtual and upright behind the surface."]],"34.9":[["För den konvexa spegeln är f = −17,0/2 = −8,50 cm. Bilden bakom spegeln har s′ = −6,50 cm.","Spegelekvationen ger 1/s = 1/f−1/s′ och s ≈ 27,6 cm framför spegeln.","m = −s′/s ≈ +0,235, så h′ = mh ≈ +0,353 cm. Bilden är virtuell och upprätt."],["For the convex mirror f = −17.0/2 = −8.50 cm. The image behind the mirror has s′ = −6.50 cm.","The mirror equation gives 1/s = 1/f−1/s′ and s ≈ 27.6 cm in front of the mirror.","m = −s′/s ≈ +0.235, so h′ = mh ≈ +0.353 cm. The image is virtual and upright."]],"34.10":[["Den konvexa skålytan har f = −30/2 = −15 cm. Med s = 85 cm ger 1/s′ = 1/f−1/s s′ = −12,75 cm.","Förstoringen är m = −s′/s = +0,150. För en 2,0 cm hög näsa är h′ = +0,30 cm; bilden är virtuell och upprätt bakom ytan."],["The convex bowl surface has f = −30/2 = −15 cm. With s = 85 cm, 1/s′ = 1/f−1/s gives s′ = −12.75 cm.","Magnification is m = −s′/s = +0.150. For a 2.0 cm nose h′ = +0.30 cm; the image is virtual and upright behind the surface."]],"34.11":[["Den konkava spegelns brännvidd är f = R/2 = +16,05 cm. Ansiktet står innanför fokus eftersom s = 11,2 cm < f.","Spegelekvationen ger s′ = [1/f−1/s]⁻¹ ≈ −37,1 cm. Förstoringen m = −s′/s ≈ +3,31.","Bilden är virtuell, upprätt och förstorad bakom spegeln. I stråldiagrammet möts de reflekterade strålarnas bakåtförlängningar vid bilden."],["The concave mirror has focal length f = R/2 = +16.05 cm. The face is inside focus because s = 11.2 cm < f.","The mirror equation gives s′ = [1/f−1/s]⁻¹ ≈ −37.1 cm. Magnification m = −s′/s ≈ +3.31.","The image is virtual, upright and magnified behind the mirror. In the ray diagram the reflected rays’ backward extensions meet at the image."]],"34.12":[["En verklig bild med samma storleksbelopp som föremålet är inverterad, så m = −s′/s = −1 och s′ = s.","Spegelekvationen blir 2/s = 1/f. Därför s = 2f = 36,0 cm framför spegeln."],["A real image with the same size magnitude as the object is inverted, so m = −s′/s = −1 and s′ = s.","The mirror equation becomes 2/s = 1/f. Thus s = 2f = 36.0 cm in front of the mirror."]],"34.13":[["En upprätt förstorad bild av ett verkligt föremål kräver här en konkav spegel med föremålet innanför fokus.","m = −s′/s = +2,00 och s = 1,25 cm ger s′ = −2,50 cm, alltså en virtuell bild bakom spegeln.","1/f = 1/s+1/s′ = 1/1,25−1/2,50 ger f = +2,50 cm och R = 2f = +5,00 cm."],["An upright magnified image of a real object here requires a concave mirror with the object inside focus.","m = −s′/s = +2.00 and s = 1.25 cm give s′ = −2.50 cm, a virtual image behind the mirror.","1/f = 1/s+1/s′ = 1/1.25−1/2.50 gives f = +2.50 cm and R = 2f = +5.00 cm."]],"34.14":[["En konvex spegel ger en upprätt bild, så m = +1/2 och m = −s′/s ger s′ = −s/2.","Insatt i 1/s+1/s′ = 1/f fås −1/s = 1/(−12,0 cm). Föremålet ska stå s = 12,0 cm framför spegeln."],["A convex mirror forms an upright image, so m = +1/2 and m = −s′/s gives s′ = −s/2.","Substituting into 1/s+1/s′ = 1/f gives −1/s = 1/(−12.0 cm). The object should be s = 12.0 cm in front of the mirror."]],"34.15":[["Figurens måttpil anger s = 15,0 cm till spegelns vertex; textens ord ”center” kan annars förväxlas med krökningscentrum. Använd s = 15,0 cm för båda sidorna.","(a) För konkav sida är f = +6,00 cm. Spegelekvationen ger s′ = +10,0 cm och h′ = −(10,0/15,0)3,30 = −2,20 mm: en reell inverterad bild.","(b) För konvex sida är f = −6,00 cm. Då s′ ≈ −4,29 cm och h′ = −(s′/s)h ≈ +0,943 mm: en virtuell upprätt bild."],["The figure’s dimension arrow gives s = 15.0 cm to the mirror vertex; the text’s word “center” could otherwise be confused with the center of curvature. Use s = 15.0 cm for both sides.","(a) For the concave side f = +6.00 cm. The mirror equation gives s′ = +10.0 cm and h′ = −(10.0/15.0)3.30 = −2.20 mm: a real inverted image.","(b) For the convex side f = −6.00 cm. Then s′ ≈ −4.29 cm and h′ = −(s′/s)h ≈ +0.943 mm: a virtual upright image."]],"34.16":[["Den inverterade bilden har m = h′/h = −2,50/0,600. Eftersom m = −s′/s och s = 24,0 cm fås s′ = 100 cm.","1/f = 1/24,0+1/100 ger f ≈ 19,35 cm. Krökningsradien är R = 2f ≈ 38,7 cm."],["The inverted image has m = h′/h = −2.50/0.600. Since m = −s′/s and s = 24.0 cm, s′ = 100 cm.","1/f = 1/24.0+1/100 gives f ≈ 19.35 cm. Radius of curvature is R = 2f ≈ 38.7 cm."]]};const figures={'34.5':['concave-solution-5.svg','En konkav spegel med föremålet mellan fokus F och krökningscentrum C ger en reell inverterad bild där två huvudstrålar möts.','A concave mirror with the object between focus F and center of curvature C gives a real inverted image where two principal rays meet.'],'34.6':['convex-solution-6.svg','En konvex spegel ger divergerande reflekterade strålar; deras streckade bakåtförlängningar möts i en virtuell upprätt bild.','A convex mirror gives diverging reflected rays; dashed backward extensions meet at a virtual upright image.'],'34.11':['concave-solution-11.svg','Föremålet står innanför en konkav spegels fokus. De reflekterade strålarnas streckade förlängningar möts bakom spegeln i en förstorad virtuell bild.','The object is inside the focus of a concave mirror. Dashed extensions of reflected rays meet behind the mirror at an enlarged virtual image.']};for(const e of root.EmberChapter34DraftExercises){const r=reviewed[e.id];if(r){e.sv.steps=r[0];e.en.steps=r[1]}const f=figures[e.id];if(f){e.solutionFigure=f[0];e.solutionAlt={sv:f[1],en:f[2]}}}})(window);
(function(root){'use strict';const reviewed={"34.17":[["Resultatet beror på skedens form och avstånd. På en vanlig konkav skedsida kan ansiktet vid 25 cm ligga utanför fokus och bilden vara inverterad och reell; kontrollera den faktiska bilden. Den konvexa sidan ger en upprätt virtuell bild.","Som exempel: om huvudet uppskattas vara 20 cm högt och den inverterade bilden 2 cm hög är m ≈ −0,10. Med s ≈ 25 cm ger m = −s′/s bildavståndet s′ ≈ 2,5 cm.","Spegelekvationen ger f = [1/s+1/s′]⁻¹ ≈ 2,27 cm och R = 2f ≈ 4,5 cm. Uppskatta egna höjder och upprepa beräkningen för den aktuella skeden."],["Results depend on spoon shape and distance. On a typical concave side the face at 25 cm may lie beyond focus and the image be inverted and real; inspect the actual image. The convex side gives an upright virtual image.","For example, if head height is estimated as 20 cm and inverted image height as 2 cm, m ≈ −0.10. With s ≈ 25 cm, m = −s′/s gives s′ ≈ 2.5 cm.","The mirror equation gives f = [1/s+1/s′]⁻¹ ≈ 2.27 cm and R = 2f ≈ 4.5 cm. Estimate your own heights and repeat for the actual spoon."]],"34.18":[["För nästan normalt seende från luft är fiskens skenbara djup d_skenbar ≈ d/n = 7,5/1,333 ≈ 5,6 cm.","Den plana bottenspegeln ger en virtuell fiskbild lika långt bakom spegeln som fisken är framför. Dess geometriska djup under vattenytan är 2(20,2)−7,5 = 32,9 cm.","Brytningen vid vattenytan ger det skenbara djupet 32,9/1,333 ≈ 24,7 cm för spegelbilden."],["For near-normal viewing from air, apparent fish depth is d_apparent ≈ d/n = 7.5/1.333 ≈ 5.6 cm.","The plane bottom mirror forms a virtual fish image as far behind it as the fish is in front. Its geometric depth below the water surface is 2(20.2)−7.5 = 32.9 cm.","Refraction at the water surface gives apparent depth 32.9/1.333 ≈ 24.7 cm for the mirror image."]],"34.19":[["För nära normalt seende från luft genom en plan yta är skenbart djup ungefär verkligt djup dividerat med isens brytningsindex.","d_skenbar = 3,90/1,309 ≈ 2,98 cm under isytan."],["For near-normal viewing from air through a plane surface, apparent depth is approximately true depth divided by the ice refractive index.","d_apparent = 3.90/1.309 ≈ 2.98 cm below the ice surface."]],"34.20":[["Välj positivt R när krökningscentrum ligger på den utgående sidan. Den konkava ändens centrum ligger på luftsidan, så R = −15,0 cm; inkommande strålar är parallella och 1/s = 0.","Brytningsytans ekvation n₁/s+n₂/s′ = (n₂−n₁)/R ger 1,50/s′ = 0,50/(−15,0).","Alltså s′ = −45,0 cm: bilden är virtuell och ligger på luftsidan om vertex."],["Take R positive when the center of curvature lies on the outgoing side. The concave end’s center is on the air side, so R = −15.0 cm; incoming rays are parallel and 1/s = 0.","The refracting-surface equation n₁/s+n₂/s′ = (n₂−n₁)/R gives 1.50/s′ = 0.50/(−15.0).","Thus s′ = −45.0 cm: the image is virtual and lies on the air side of the vertex."]],"34.21":[["Bilden är 4,00 m ovanför simmaren, som befinner sig 1,00 m under ytan. Bildens skenbara höjd över ytan är därför 3,00 m.","För nästan normalt seende från vatten mot ett objekt i luft är h_skenbar = (n_vatten/n_luft)h_verklig. Med n_luft ≈ 1 blir h_verklig = 3,00/1,333 ≈ 2,25 m."],["The image is 4.00 m above the swimmer, who is 1.00 m below the surface. Apparent image height above the surface is thus 3.00 m.","For near-normal viewing from water toward an object in air, h_apparent = (n_water/n_air)h_actual. With n_air ≈ 1, h_actual = 3.00/1.333 ≈ 2.25 m."]],"34.22":[["Det skenbara avståndet under vattenytan är 7,00−3,00 = 4,00 m.","Vid nära normalt seende från luft är d_skenbar ≈ d_verklig/n. Därför är vattendjupet d_verklig ≈ 1,333·4,00 = 5,33 m."],["Apparent distance below the water surface is 7.00−3.00 = 4.00 m.","For near-normal viewing from air d_apparent ≈ d_actual/n. Therefore water depth is d_actual ≈ 1.333·4.00 = 5.33 m."]],"34.23":[["(a) För den utgående sfäriska vatten–luft-ytan är s = 14,0 cm, R = −14,0 cm, n₁ = 1,333 och n₂ = 1,00. Ytekvationen ger s′ = −14,0 cm: bildpunkten ligger i centrum.","Tvärförstoringen är m = −n₁s′/(n₂s) ≈ +1,333.","(b) För parallella solstrålar ger den första ytan en mellanbild cirka 56,0 cm från första vertex. Den ligger cirka 28,0 cm bortom den andra ytan och fungerar där som ett virtuellt föremål.","Den andra ytan ger paraxiellt fokus cirka 14,0 cm utanför skålen. Denna brännpunkt ligger alltså inte inuti vattnet."],["(a) For the outgoing spherical water–air surface s = 14.0 cm, R = −14.0 cm, n₁ = 1.333 and n₂ = 1.00. The surface equation gives s′ = −14.0 cm: the image point is at the center.","Transverse magnification is m = −n₁s′/(n₂s) ≈ +1.333.","(b) For parallel sunlight the first surface forms an intermediate image about 56.0 cm from its vertex. It lies about 28.0 cm beyond the second surface and acts there as a virtual object.","The second surface gives a paraxial focus about 14.0 cm outside the bowl. This focal point is not inside the water."]],"34.24":[["För den konvexa glasytan är n₁ = 1,00, n₂ = 1,60 och R = +3,00 cm. Ytekvationen blir 1/s+1,60/s′ = 0,60/3,00.","Insättning ger (a) s′ = +8,00 cm när s = ∞, (b) s′ ≈ +13,7 cm när s = 12,0 cm och (c) s′ ≈ −5,33 cm när s = 2,00 cm.","De två första bilderna är reella i glaset; den sista är virtuell på luftsidan."],["For the convex glass surface n₁ = 1.00, n₂ = 1.60 and R = +3.00 cm. The surface equation is 1/s+1.60/s′ = 0.60/3.00.","Substitution gives (a) s′ = +8.00 cm for s = ∞, (b) s′ ≈ +13.7 cm for s = 12.0 cm, and (c) s′ ≈ −5.33 cm for s = 2.00 cm.","The first two images are real in the glass; the last is virtual on the air side."]],"34.25":[["Använd centimeter genomgående: R = +3,00 cm och s′ = +1,20 m = 120 cm.","Ytekvationen ger 1,45/s+1,60/120 = (1,60−1,45)/3,00.","Lös s = 1,45/[0,0500−1,60/120] ≈ 39,5 cm framför vertex i oljan."],["Use centimeters throughout: R = +3.00 cm and s′ = +1.20 m = 120 cm.","The surface equation gives 1.45/s+1.60/120 = (1.60−1.45)/3.00.","Solve s = 1.45/[0.0500−1.60/120] ≈ 39.5 cm before the vertex in oil."]],"34.26":[["För en konvex luft–glas-yta med R = +4,00 cm ger ytekvationen 1/24,0+1,60/s′ = 0,60/4,00. Därmed s′ ≈ +14,8 cm i glaset.","Tvärförstoringen är m = −n₁s′/(n₂s) ≈ −0,385. Med h = 1,50 mm blir h′ ≈ −0,577 mm.","Positivt bildavstånd och negativ höjd anger en reell inverterad bild."],["For a convex air–glass surface with R = +4.00 cm, the surface equation gives 1/24.0+1.60/s′ = 0.60/4.00. Thus s′ ≈ +14.8 cm in the glass.","Transverse magnification is m = −n₁s′/(n₂s) ≈ −0.385. With h = 1.50 mm, h′ ≈ −0.577 mm.","Positive image distance and negative height indicate a real inverted image."]],"34.27":[["(a) En reell bild har s′ = +60,0 cm. Spegelekvationen ger f = [1/20,0+1/60,0]⁻¹ = +15,0 cm och R = +30,0 cm.","m = −s′/s = −3,00 ger h′ = −9,60 mm, en inverterad bild.","(b) En virtuell bild har s′ = −60,0 cm. Då f = [1/20,0−1/60,0]⁻¹ = +30,0 cm och R = +60,0 cm.","Nu m = +3,00 och h′ = +9,60 mm, en upprätt bild."],["(a) A real image has s′ = +60.0 cm. The mirror equation gives f = [1/20.0+1/60.0]⁻¹ = +15.0 cm and R = +30.0 cm.","m = −s′/s = −3.00 gives h′ = −9.60 mm, an inverted image.","(b) A virtual image has s′ = −60.0 cm. Then f = [1/20.0−1/60.0]⁻¹ = +30.0 cm and R = +60.0 cm.","Now m = +3.00 and h′ = +9.60 mm, an upright image."]]};for(const e of root.EmberChapter34DraftExercises){const r=reviewed[e.id];if(r){e.sv.steps=r[0];e.en.steps=r[1]}}})(window);

(function(root){'use strict';const reviewed={"34.28":[["För en reell bild är m = −s′/s och |h′| = h f/(s−f).","Därför är 1/|h′| = s/(hf)−1/h och grafens lutning 1/(hf).","Med h = 4,00 mm = 0,400 cm fås f = 1/(0,400·0,208) ≈ 12,0 cm. Den positiva lutningen förutsätter bildhöjdens belopp; tecknad inverterad höjd skulle ge negativ lutning."],["For a real image m = −s′/s and |h′| = h f/(s−f).","Thus 1/|h′| = s/(hf)−1/h and the graph slope is 1/(hf).","With h = 4.00 mm = 0.400 cm, f = 1/(0.400·0.208) ≈ 12.0 cm. The positive slope assumes image-height magnitude; signed inverted height would give a negative slope."]],"34.29":[["För en plankonvex tunn lins i luft ger linsmakarens ekvation f = R/(n−1) = 12,9/0,70 ≈ 18,43 cm.","Linsekvationen ger s′ = [1/f−1/25,0]⁻¹ ≈ +70,1 cm.","m = −s′/s ≈ −2,80 och h′ = mh ≈ −10,5 mm. Bilden är reell och inverterad.","När linsen vänds i samma medium är den tunna linsens brännvidd oförändrad, så samma bildläge och höjd gäller."],["For a plano-convex thin lens in air the lensmaker equation gives f = R/(n−1) = 12.9/0.70 ≈ 18.43 cm.","The lens equation gives s′ = [1/f−1/25.0]⁻¹ ≈ +70.1 cm.","m = −s′/s ≈ −2.80 and h′ = mh ≈ −10.5 mm. The image is real and inverted.","Reversing the thin lens in the same medium leaves its focal length unchanged, so the image position and height are the same."]],"34.30":[["Bilden ligger på föremålssidan: s = +16,0 cm och s′ = −12,0 cm.","1/f = 1/s+1/s′ = 1/16,0−1/12,0 = −1/48,0 cm⁻¹, så f = −48,0 cm och linsen är spridande.","m = −s′/s = +0,750 och h′ = mh = +6,38 mm. Bilden är virtuell, upprätt och förminskad.","I stråldiagrammet går den parallella strålen ut som om den kom från fokus. Dess bakåtförlängning och den centrala strålen möts vid bilden."],["The image is on the object side: s = +16.0 cm and s′ = −12.0 cm.","1/f = 1/s+1/s′ = 1/16.0−1/12.0 = −1/48.0 cm⁻¹, so f = −48.0 cm and the lens is diverging.","m = −s′/s = +0.750 and h′ = mh = +6.38 mm. The image is virtual, upright and reduced.","In the ray diagram the parallel ray emerges as if from the focal point. Its backward extension and the central ray meet at the image."]],"34.31":[["Menisklinsen är samlande. I linsmakarens formel används skillnaden mellan yteffekternas belopp: 1/f = (1,52−1)(1/4,00−1/7,00) cm⁻¹.","Därmed f ≈ +17,95 cm och s′ = [1/f−1/24,0]⁻¹ ≈ +71,2 cm.","m = −s′/s ≈ −2,97. Bilden är reell och inverterad."],["The meniscus lens is converging. In the lensmaker equation use the difference between the surface powers: 1/f = (1.52−1)(1/4.00−1/7.00) cm⁻¹.","Thus f ≈ +17.95 cm and s′ = [1/f−1/24.0]⁻¹ ≈ +71.2 cm.","m = −s′/s ≈ −2.97. The image is real and inverted."]],"34.32":[["Bildens höjd är negativ: m = −4,50/3,20 = −1,40625. För en reell bild är s′ = 1,40625s.","Insättning i 1/f = 1/s+1/s′ ger s = f(1+1/1,40625) ≈ 120 cm.","s′ ≈ +168 cm, på andra sidan linsen. Bilden är reell."],["The image height is negative: m = −4.50/3.20 = −1.40625. For a real image s′ = 1.40625s.","Substituting in 1/f = 1/s+1/s′ gives s = f(1+1/1.40625) ≈ 120 cm.","s′ ≈ +168 cm, on the opposite side of the lens. The image is real."]],"34.33":[["Omvandla 7,50 mm till 0,750 cm. Den upprätta bilden ger m = +3,30/0,750 = +4,40.","Bilden är på föremålssidan, s′ = −12,5 cm, och m = −s′/s ger s ≈ 2,84 cm.","Linsekvationen ger f = [1/2,84−1/12,5]⁻¹ ≈ +3,68 cm. Bilden är virtuell."],["Convert 7.50 mm to 0.750 cm. The upright image gives m = +3.30/0.750 = +4.40.","The image lies on the object side, s′ = −12.5 cm, and m = −s′/s gives s ≈ 2.84 cm.","The lens equation gives f = [1/2.84−1/12.5]⁻¹ ≈ +3.68 cm. The image is virtual."]],"34.34":[["Reell bild på väggen ger s+s′ = 610 cm och |m| = s′/s = 75,0.","Alltså s = 610/76,0 ≈ 8,03 cm och s′ ≈ 602 cm.","m = −75,0 så bilden är inverterad. f = ss′/(s+s′) ≈ +7,92 cm; linsen är samlande."],["A real image on the wall gives s+s′ = 610 cm and |m| = s′/s = 75.0.","Thus s = 610/76.0 ≈ 8.03 cm and s′ ≈ 602 cm.","m = −75.0 so the image is inverted. f = ss′/(s+s′) ≈ +7.92 cm; the lens is converging."]],"34.35":[["För ett mycket avlägset träd är bildavståndet ungefär brännvidden: f ≈ 1,89 cm.","Dubbelkonvex lins med lika radier har 1/f = (n−1)(2/R).","Därför n = 1+R/(2f) = 1+3,00/(2·1,89) ≈ 1,79."],["For a very distant tree the image distance is approximately the focal length: f ≈ 1.89 cm.","An equal-radius double-convex lens has 1/f = (n−1)(2/R).","Thus n = 1+R/(2f) = 1+3.00/(2·1.89) ≈ 1.79."]],"34.36":[["m = +17,0/3,20 = +5,3125 för den upprätta bilden, och s′ = −ms.","Då ger linsekvationen s = f(1−1/m) = 7,00(1−1/5,3125) ≈ 5,68 cm.","s′ = −ms ≈ −30,2 cm. Bilden är virtuell och ligger på föremålssidan."],["m = +17.0/3.20 = +5.3125 for the upright image, and s′ = −ms.","Then the lens equation gives s = f(1−1/m) = 7.00(1−1/5.3125) ≈ 5.68 cm.","s′ = −ms ≈ −30.2 cm. The image is virtual on the object side."]],"34.37":[["Linsmakarens ekvation ger f = R/(n−1) = 20,0/0,50 = +40,0 cm.","Med s = 20,0 cm ger linsekvationen s′ = [1/40,0−1/20,0]⁻¹ = −40,0 cm.","m = −s′/s = +2,00 och h′ = mh = +12,0 mm. Bilden är virtuell och upprätt."],["The lensmaker equation gives f = R/(n−1) = 20.0/0.50 = +40.0 cm.","With s = 20.0 cm the lens equation gives s′ = [1/40.0−1/20.0]⁻¹ = −40.0 cm.","m = −s′/s = +2.00 and h′ = mh = +12.0 mm. The image is virtual and upright."]],"34.38":[["För en dubbelkonvex tunn lins i luft med lika radier är 1/f = 2(n−1)/R.","Lös ut R = 2(n−1)f = 2(0,55)(20,0 cm) = 22,0 cm."],["For an equal-radius double-convex thin lens in air, 1/f = 2(n−1)/R.","Solve for R = 2(n−1)f = 2(0.55)(20.0 cm) = 22.0 cm."]],"34.39":[["Föremålet är reellt och bilden på samma sida är virtuell: s = +12,0 cm, s′ = −8,00 cm.","Linsekvationen ger f = [1/12,0−1/8,00]⁻¹ = −24,0 cm.","För en plankonkav lins är |f| = R/(n−1), så R = 0,50·24,0 = 12,0 cm."],["The object is real and the image on the same side virtual: s = +12.0 cm, s′ = −8.00 cm.","The lens equation gives f = [1/12.0−1/8.00]⁻¹ = −24.0 cm.","For a plano-concave lens |f| = R/(n−1), so R = 0.50·24.0 = 12.0 cm."]]};for(const e of root.EmberChapter34DraftExercises){const r=reviewed[e.id];if(r){e.sv.steps=r[0];e.en.steps=r[1]}}})(window);
(function(root){'use strict';const e=root.EmberChapter34DraftExercises.find(x=>x.id==='34.30');if(!/huvudstråldiagram/i.test(e.sv.prompt))e.sv.prompt+=' Rita ett huvudstråldiagram.';if(!/principal-ray diagram/i.test(e.en.prompt))e.en.prompt+=' Draw a principal-ray diagram.';e.solutionFigure='assets/physics/chapter34/diverging-solution-30.svg';e.sv.solutionAlt='En parallell stråle bryts utåt som om den kom från fokus. Strålens bakåtförlängning skär centralstrålen vid den upprätta virtuella bilden.';e.en.solutionAlt='A parallel ray emerges as if from the focal point. Its backward extension intersects the central ray at the upright virtual image.';})(window);

(function(root){'use strict';const reviewed={"34.40":[["Den virtuella bilden ligger på samma sida som det verkliga föremålet, alltså går ljuset här från höger mot vänster och s′ = −17,0 cm.","1/s = 1/f−1/s′ = 1/12,0+1/17,0 ger s ≈ 7,03 cm till höger om linsen.","m = −s′/s ≈ +2,42, så föremålets höjd är 8,00/2,42 ≈ 3,31 mm. Bilden är upprätt och på samma sida som föremålet."],["The virtual image lies on the same side as the real object, so light travels right to left and s′ = −17.0 cm.","1/s = 1/f−1/s′ = 1/12.0+1/17.0 gives s ≈ 7.03 cm to the right of the lens.","m = −s′/s ≈ +2.42, so the object height is 8.00/2.42 ≈ 3.31 mm. The image is upright and on the same side as the object."]],"34.41":[["Använd samma riktning och s′ = −17,0 cm men nu f = −48,0 cm.","1/s = −1/48,0+1/17,0 ger s ≈ 26,3 cm till höger om linsen.","m = −s′/s ≈ +0,646 och föremålets höjd är 8,00/0,646 ≈ 12,4 mm. Bilden är upprätt och på samma sida som föremålet."],["Use the same direction and s′ = −17.0 cm, but now f = −48.0 cm.","1/s = −1/48.0+1/17.0 gives s ≈ 26.3 cm to the right of the lens.","m = −s′/s ≈ +0.646 and object height is 8.00/0.646 ≈ 12.4 mm. The image is upright and on the same side as the object."]],"34.42":[["s = +16,0 cm och den reella bilden har s′ = +36,0 cm.","f = [1/16,0+1/36,0]⁻¹ ≈ +11,1 cm, alltså en samlingslins.","m = −36,0/16,0 = −2,25 och h′ = mh = −18,0 mm. Bilden är inverterad."],["s = +16.0 cm and the real image has s′ = +36.0 cm.","f = [1/16.0+1/36.0]⁻¹ ≈ +11.1 cm, so the lens converges.","m = −36.0/16.0 = −2.25 and h′ = mh = −18.0 mm. The image is inverted."]],"34.43":[["För första linsen ger s₁ = 50,0 cm och f₁ = 40,0 cm bildavståndet s₁′ = [1/40,0−1/50,0]⁻¹ = +200 cm.","m₁ = −200/50,0 = −4,00 och h₁′ = −4,80 cm. Mellanbilden ligger 100 cm framför lins 2.","Med s₂ = +100 cm och f₂ = +60,0 cm fås s₂′ = +150 cm och m₂ = −1,50.","Slutbilden ligger 300+150 = 450 cm till höger om första linsen och h₂′ = (−1,50)(−4,80) = +7,20 cm."],["For lens 1, s₁ = 50.0 cm and f₁ = 40.0 cm give s₁′ = [1/40.0−1/50.0]⁻¹ = +200 cm.","m₁ = −200/50.0 = −4.00 and h₁′ = −4.80 cm. The intermediate image lies 100 cm before lens 2.","With s₂ = +100 cm and f₂ = +60.0 cm, s₂′ = +150 cm and m₂ = −1.50.","The final image lies 300+150 = 450 cm right of lens 1, with h₂′ = (−1.50)(−4.80) = +7.20 cm."]],"34.44":[["Mät x från första linsen åt höger. För varje fall används s₂ = 300−x₁ och m₂ = −s₂′/s₂.","(a) f₁ = +40,0 cm ger x₁ = +200 cm och h₁′ = −4,80 cm. Med f₂ = −60,0 cm och s₂ = 100 cm fås s₂′ = −37,5 cm: x₂ = 262,5 cm och h₂′ = −1,80 cm.","(b) f₁ = −40,0 cm ger x₁ = −22,2 cm och h₁′ = +0,533 cm. Med f₂ = +60,0 cm och s₂ = 322,2 cm fås s₂′ ≈ +73,7 cm: x₂ ≈ 373,7 cm och h₂′ ≈ −0,122 cm.","(c) Samma mellanbild som i (b). Med f₂ = −60,0 cm fås s₂′ ≈ −50,6 cm: x₂ ≈ 249,4 cm och h₂′ ≈ +0,0837 cm."],["Measure x rightward from lens 1. In each case use s₂ = 300−x₁ and m₂ = −s₂′/s₂.","(a) f₁ = +40.0 cm gives x₁ = +200 cm and h₁′ = −4.80 cm. With f₂ = −60.0 cm and s₂ = 100 cm, s₂′ = −37.5 cm: x₂ = 262.5 cm and h₂′ = −1.80 cm.","(b) f₁ = −40.0 cm gives x₁ = −22.2 cm and h₁′ = +0.533 cm. With f₂ = +60.0 cm and s₂ = 322.2 cm, s₂′ ≈ +73.7 cm: x₂ ≈ 373.7 cm and h₂′ ≈ −0.122 cm.","(c) The intermediate image is the same as in (b). With f₂ = −60.0 cm, s₂′ ≈ −50.6 cm: x₂ ≈ 249.4 cm and h₂′ ≈ +0.0837 cm."]],"34.45":[["För lins 1 ger f₁ = −12,0 cm och s₁ = 20,0 cm s₁′ = −7,50 cm och m₁ = +0,375.","Mellanbilden ligger 9,00+7,50 = 16,5 cm framför lins 2. Med f₂ = +12,0 cm fås s₂′ = +44,0 cm och m₂ = −44,0/16,5.","Slutbilden ligger 9,00+44,0 = 53,0 cm till höger om lins 1. Den är reell och h′ = m₁m₂h = −2,50 mm, alltså inverterad."],["For lens 1, f₁ = −12.0 cm and s₁ = 20.0 cm give s₁′ = −7.50 cm and m₁ = +0.375.","The intermediate image is 9.00+7.50 = 16.5 cm before lens 2. With f₂ = +12.0 cm, s₂′ = +44.0 cm and m₂ = −44.0/16.5.","The final image is 9.00+44.0 = 53.0 cm right of lens 1. It is real and h′ = m₁m₂h = −2.50 mm, hence inverted."]],"34.46":[["En spridningslins med verkligt föremål ger en virtuell bild på föremålssidan, så f = −25,0 cm och s′ = −18,0 cm.","1/s = 1/f−1/s′ ger s ≈ 64,3 cm till vänster om linsen.","m = −s′/s ≈ +0,280: bilden är upprätt och mindre än föremålet."],["A diverging lens with a real object forms a virtual image on the object side, so f = −25.0 cm and s′ = −18.0 cm.","1/s = 1/f−1/s′ gives s ≈ 64.3 cm to the left of the lens.","m = −s′/s ≈ +0.280: the image is upright and smaller than the object."]],"34.47":[["Med s = 2f/3 ger linsekvationen 1/s′ = 1/f−3/(2f) = −1/(2f).","Alltså s′ = −2f: bilden är virtuell och ligger till vänster om linsen, på föremålssidan.","m = −s′/s = +3 och h′ = +3h. Bilden är upprätt och tre gånger så hög; detta stämmer med figurens strålkonstruktion."],["With s = 2f/3 the lens equation gives 1/s′ = 1/f−3/(2f) = −1/(2f).","Thus s′ = −2f: the image is virtual and lies left of the lens, on the object side.","m = −s′/s = +3 and h′ = +3h. The image is upright and three times as tall, consistent with the ray construction."]],"34.48":[["En reell skärmbild från ett verkligt föremål är inverterad. Därför |m| = s′/s = 2,50.","s+s′ = 2,60 m ger s = 2,60/3,50 ≈ 0,743 m och s′ ≈ 1,86 m.","f = ss′/(s+s′) ≈ +0,531 m. Den positiva brännvidden visar att linsen är samlande."],["A real screen image of a real object is inverted, so |m| = s′/s = 2.50.","s+s′ = 2.60 m gives s = 2.60/3.50 ≈ 0.743 m and s′ ≈ 1.86 m.","f = ss′/(s+s′) ≈ +0.531 m. The positive focal length means a converging lens."]],"34.49":[["Använd mm: f = 85 mm och s = 3 900 mm. Linsekvationen ger s′ = [1/85−1/3900]⁻¹ ≈ 86,9 mm.","Bildhöjdens belopp är |h′| = (s′/s)h = (86,9/3900)(1750 mm) ≈ 39,0 mm.","Det är större än sensorns största mått 36 mm; hela personen ryms därför inte i denna idealiserade inramning."],["Use mm: f = 85 mm and s = 3,900 mm. The lens equation gives s′ = [1/85−1/3900]⁻¹ ≈ 86.9 mm.","Image-height magnitude is |h′| = (s′/s)h = (86.9/3900)(1750 mm) ≈ 39.0 mm.","That exceeds the sensor’s largest dimension, 36 mm, so the whole person does not fit in this idealized framing."]],"34.50":[["Med s = 0,150 m och s′ = 9,00 m fås f = [1/0,150+1/9,00]⁻¹ ≈ 0,1475 m = 14,8 cm.","Förstoringsbeloppet är |m| = s′/s = 60,0.","Bilden har måtten 60,0·24 mm × 60,0·36 mm = 1,44 m × 2,16 m; detta är minsta skärmmåtten. Bilden är inverterad."],["With s = 0.150 m and s′ = 9.00 m, f = [1/0.150+1/9.00]⁻¹ ≈ 0.1475 m = 14.8 cm.","Magnification magnitude is |m| = s′/s = 60.0.","The image measures 60.0·24 mm × 60.0·36 mm = 1.44 m × 2.16 m; these are the minimum screen dimensions. The image is inverted."]],"34.51":[["För ett avlägset föremål skulle första linsen ensam bilda en bild 12 cm till höger om sig. Denna punkt är föremål för lins 2.","(a–c) Vid linsavståndet 4 cm ligger punkten 8 cm bortom lins 2, så s₂ = −8 cm. Med f₂ = −12 cm ger linsekvationen s₂′ = +24 cm och slutbilden ligger x = 4+24 = 28 cm från lins 1.","(d) Vid linsavståndet 8 cm är s₂ = −4 cm. Då s₂′ = +6 cm och slutbilden ligger x = 8+6 = 14 cm från lins 1."],["For a distant object lens 1 alone would form an image 12 cm to its right. That point is the object for lens 2.","(a–c) With 4 cm separation the point is 8 cm beyond lens 2, so s₂ = −8 cm. With f₂ = −12 cm, the lens equation gives s₂′ = +24 cm and final image position x = 4+24 = 28 cm from lens 1.","(d) With 8 cm separation s₂ = −4 cm. Then s₂′ = +6 cm and the final image is x = 8+6 = 14 cm from lens 1."]]};for(const e of root.EmberChapter34DraftExercises){const r=reviewed[e.id];if(r){e.sv.steps=r[0];e.en.steps=r[1]}}})(window);
(function(root){'use strict';for(const [id,figure,sv,en] of [['34.40','converging-solution-40.svg','Ljuset går från höger. Brutna strålars bakåtförlängningar möts vid den upprätta virtuella bilden.','Light travels from the right. Backward extensions of refracted rays meet at the upright virtual image.'],['34.41','diverging-solution-41.svg','Ljuset går från höger. Strålarnas bakåtförlängningar möts vid den förminskade virtuella bilden.','Light travels from the right. Backward extensions meet at the reduced virtual image.'],['34.42','converging-solution-42.svg','En parallell stråle bryts genom fokus och möter centralstrålen vid den inverterade reella bilden.','A parallel ray refracts through the focus and meets the central ray at the inverted real image.']]){const e=root.EmberChapter34DraftExercises.find(x=>x.id===id);e.solutionFigure='assets/physics/chapter34/'+figure;e.sv.solutionAlt=sv;e.en.solutionAlt=en;if(!/huvudstråldiagram/i.test(e.sv.prompt))e.sv.prompt+=' Rita ett huvudstråldiagram.';if(!/principal-ray diagram/i.test(e.en.prompt))e.en.prompt+=' Draw a principal-ray diagram.';}})(window);

(function(root){'use strict';const reviewed={"34.52":[["Brytning vid en sfärisk yta uppfyller n₁/s+n₂/s′ = (n₂−n₁)/R. Här är n₁ = 1,00, n₂ = 1,40, s = 40,0 cm och s′ = 2,60 cm.","R = 0,40/[1/40,0+1,40/2,60] ≈ +0,710 cm. Positivt R betyder att krökningscentrum ligger inne i ögat."],["Refraction at a spherical surface obeys n₁/s+n₂/s′ = (n₂−n₁)/R. Here n₁ = 1.00, n₂ = 1.40, s = 40.0 cm and s′ = 2.60 cm.","R = 0.40/[1/40.0+1.40/2.60] ≈ +0.710 cm. Positive R places the center of curvature inside the eye."]],"34.53":[["(a) Anta normal närpunkt 0,250 m med kontaktlinsen. Den virtuella bilden ligger vid ögats okorrigerade närpunkt N: P = 1/0,250−1/N.","Därför N = 1/(4,00−2,95) ≈ 0,952 m.","(b) För ett avlägset föremål är s′ = f = 1/P = −0,625 m. Fjärrpunkten ligger 0,625 m framför ögat."],["(a) Assume a normal near point of 0.250 m with the contact lens. Its virtual image lies at the uncorrected near point N: P = 1/0.250−1/N.","Thus N = 1/(4.00−2.95) ≈ 0.952 m.","(b) For a distant object s′ = f = 1/P = −0.625 m. The far point is 0.625 m in front of the eye."]],"34.54":[["En närpunkt längre bort än normalt medan avlägsna föremål syns tydligt motsvarar översynthet i modellen.","Kontaktlinsen ska avbilda ett föremål vid s = +0,250 m virtuellt vid s′ = −0,450 m.","P = 1/s+1/s′ = 4,00−2,22 ≈ +1,78 D och f = 1/P ≈ +0,563 m. En samlingslins behövs."],["A near point farther away than normal while distant objects are clear corresponds to farsightedness in this model.","The contact lens must image an object at s = +0.250 m virtually at s′ = −0.450 m.","P = 1/s+1/s′ = 4.00−2.22 ≈ +1.78 D and f = 1/P ≈ +0.563 m. A converging lens is required."]],"34.55":[["Glasögonen är 0,020 m framför ögat. Föremålet 0,250 m från ögat ligger därför s = +0,230 m från linsen.","Den virtuella bilden ska ligga i närpunkten 0,450 m från ögat, alltså s′ = −0,430 m från linsen.","P = 1/0,230−1/0,430 ≈ +2,02 D och f = 1/P ≈ +0,495 m."],["The glasses are 0.020 m in front of the eye. The object 0.250 m from the eye is therefore s = +0.230 m from the lens.","The virtual image must be at the near point 0.450 m from the eye, or s′ = −0.430 m from the lens.","P = 1/0.230−1/0.430 ≈ +2.02 D and f = 1/P ≈ +0.495 m."]],"34.56":[["Personen är närsynt eftersom fjärrpunkten är 0,750 m.","En kontaktlins ska avbilda ett avlägset föremål virtuellt vid fjärrpunkten, så f = s′ = −0,750 m.","P = 1/f ≈ −1,33 D; den negativa styrkan innebär en spridningslins."],["The person is nearsighted because the far point is 0.750 m away.","A contact lens must image a distant object virtually at the far point, so f = s′ = −0.750 m.","P = 1/f ≈ −1.33 D; the negative power means a diverging lens."]],"34.57":[["För överdelen ger P = −0,500 D fokus f = −2,00 m. Ett avlägset föremål avbildas i ögats fjärrpunkt: 2,00+0,020 = 2,02 m framför ögat.","För underdelen är s = 0,250−0,020 = 0,230 m. 1/s′ = 2,00−1/0,230 ger s′ ≈ −0,426 m. Närpunkten är 0,426+0,020 ≈ 0,446 m framför ögat.","Genom överdelen måste närmaste skarpa föremål ge samma virtuella bild: 1/s = −0,500+1/0,426, så s ≈ 0,541 m från linsen eller 0,561 m från ögat."],["For the upper section P = −0.500 D gives f = −2.00 m. A distant object images at the eye’s far point: 2.00+0.020 = 2.02 m in front of the eye.","For the lower section s = 0.250−0.020 = 0.230 m. 1/s′ = 2.00−1/0.230 gives s′ ≈ −0.426 m. The near point is 0.426+0.020 ≈ 0.446 m in front of the eye.","Through the upper section the closest clear object must form the same virtual image: 1/s = −0.500+1/0.426, so s ≈ 0.541 m from the lens or 0.561 m from the eye."]],"34.58":[["Med bilden vid oändligheten och luppen nära ögat ger småvinkelmodellen M = N/f = 25,0/6,00 ≈ 4,17.","För bilden i närpunkten är s′ = −25,0 cm. Då 1/s = 1/6,00+1/25,0, vilket ger s ≈ 4,84 cm."],["With the image at infinity and the magnifier near the eye, the small-angle model gives M = N/f = 25.0/6.00 ≈ 4.17.","For an image at the near point s′ = −25.0 cm. Then 1/s = 1/6.00+1/25.0 gives s ≈ 4.84 cm."]],"34.59":[["Närpunktsbilden är virtuell och s′ = −25,0 cm. Med f = +6,00 cm ger linsekvationen s = [1/6,00+1/25,0]⁻¹ ≈ 4,84 cm.","m = −s′/s ≈ +5,17. Med h = 4,50 mm blir h′ ≈ +23,3 mm; bilden är upprätt."],["The near-point image is virtual and s′ = −25.0 cm. With f = +6.00 cm the lens equation gives s = [1/6.00+1/25.0]⁻¹ ≈ 4.84 cm.","m = −s′/s ≈ +5.17. With h = 4.50 mm, h′ ≈ +23.3 mm; the image is upright."]],"34.60":[["När insekten ligger i fokus kommer strålarna ut parallellt och den skenbara vinkeln är ungefär θ ≈ h/f för små vinklar.","f ≈ h/θ = 2,10 mm/0,026 ≈ 80,8 mm. Den exakta tangentrelationen ger praktiskt taget samma värde."],["When the insect is at the focus, rays emerge parallel and the apparent angle is approximately θ ≈ h/f for small angles.","f ≈ h/θ = 2.10 mm/0.026 ≈ 80.8 mm. The exact tangent relation gives practically the same value."]],"34.61":[["För ett teleskop med slutbild i oändligheten är M = −f_obj/f_ok = −95,0/15,0 ≈ −6,33; minustecknet anger inversion.","Byggnadens vinkel är ungefär θ = 60,0/3000 = 0,0200 rad. Objektivets mellanbild får höjden h′ ≈ −f_objθ = −0,950·0,0200 ≈ −0,0190 m.","Slutbildens vinkelstorlek är |M|θ ≈ 6,33·0,0200 ≈ 0,127 rad."],["For a telescope with final image at infinity, M = −f_obj/f_eye = −95.0/15.0 ≈ −6.33; the minus sign indicates inversion.","The building subtends approximately θ = 60.0/3000 = 0.0200 rad. The objective intermediate image height is h′ ≈ −f_objθ = −0.950·0.0200 ≈ −0.0190 m.","The final angular size is |M|θ ≈ 6.33·0.0200 ≈ 0.127 rad."]],"34.62":[["För avlägset föremål och slutbild i oändligheten är linsavståndet f_obj+f_ok.","f_obj = 120−9,00 = 111 cm och M = −f_obj/f_ok = −111/9,00 ≈ −12,3. Bilden är inverterad."],["For a distant object and a final image at infinity, lens separation is f_obj+f_eye.","f_obj = 120−9.00 = 111 cm and M = −f_obj/f_eye = −111/9.00 ≈ −12.3. The image is inverted."]],"34.63":[["Den konkava spegelns brännvidd är f_obj = R/2 = 1,28/2 = 0,640 m.","Den reella mellanbilden ligger 0,640 m framför spegeln. Det reflekterade ljuset fortsätter genom mellanbilden och till okularet; okularet placeras ytterligare f_ok = 0,0160 m bort.","Spegel–okular-avståndet är 0,656 m och vinkelförstoringen M = −f_obj/f_ok = −0,640/0,0160 = −40,0."],["The concave mirror has focal length f_obj = R/2 = 1.28/2 = 0.640 m.","The real intermediate image is 0.640 m in front of the mirror. Reflected light continues through that image to the eyepiece, placed a further f_eye = 0.0160 m away.","Mirror-to-eyepiece distance is 0.656 m and angular magnification M = −f_obj/f_eye = −0.640/0.0160 = −40.0."]],"34.64":[["Föremålsavståndet är s₁ = 14,0+2,0 = 16,0 mm. Linsekvationen ger s₁′ = [1/14,0−1/16,0]⁻¹ = 112 mm.","För slutbild i oändligheten ligger mellanbilden i okularets fokus. Linsavståndet är 112+20,0 = 132 mm.","m₁ = −112/16,0 = −7,00 och M₂ = 250/20,0 = 12,5, så M = −87,5.","Med approximationen s₁ ≈ f₁ fås M ≈ −(112/14,0)(12,5) = −100. Skillnaden relativt det exakta beloppet är (100−87,5)/87,5 ≈ 14,3 %."],["Object distance is s₁ = 14.0+2.0 = 16.0 mm. The lens equation gives s₁′ = [1/14.0−1/16.0]⁻¹ = 112 mm.","For a final image at infinity, the intermediate image lies at the eyepiece focus. Lens separation is 112+20.0 = 132 mm.","m₁ = −112/16.0 = −7.00 and M₂ = 250/20.0 = 12.5, so M = −87.5.","Approximating s₁ ≈ f₁ gives M ≈ −(112/14.0)(12.5) = −100. The difference relative to the exact magnitude is (100−87.5)/87.5 ≈ 14.3%."]],"34.65":[["Okularets vinkelförstoring är M₂ = 250/15,0 = 16,67 och objektivets sidoförstoring m₁ = −178/16,67 = −10,68.","Mellanbilden ligger i okularets fokus, s₁′ = 202−15,0 = 187 mm från objektivet. Därför s₁ = 187/10,68 ≈ 17,5 mm.","Utan att sätta s₁ ≈ f₁ ger linsekvationen f₁ = [1/s₁+1/187]⁻¹ ≈ 16,0 mm."],["The eyepiece angular magnification is M₂ = 250/15.0 = 16.67 and the objective lateral magnification m₁ = −178/16.67 = −10.68.","The intermediate image lies at the eyepiece focus, s₁′ = 202−15.0 = 187 mm from the objective. Hence s₁ = 187/10.68 ≈ 17.5 mm.","Without setting s₁ ≈ f₁, the lens equation gives f₁ = [1/s₁+1/187]⁻¹ ≈ 16.0 mm."]]};for(const e of root.EmberChapter34DraftExercises){const r=reviewed[e.id];if(r){e.sv.steps=r[0];e.en.steps=r[1]}}})(window);

(function(root){'use strict';const reviewed={"34.66":[["En upprätt bild med m = +2,5 uppfyller m = −s′/s, alltså s′ = −2,5s.","Med f = R/2 ger spegelekvationen 1/s−1/(2,5s) = 2/R.","Lös s = 0,300R framför spegeln och s′ = −0,750R, det vill säga en virtuell bild 0,750R bakom spegeln."],["An upright image with m = +2.5 obeys m = −s′/s, so s′ = −2.5s.","With f = R/2 the mirror equation gives 1/s−1/(2.5s) = 2/R.","Solve s = 0.300R in front of the mirror and s′ = −0.750R, a virtual image 0.750R behind it."]],"34.67":[["Skärmbilden är reell och inverterad. |m| = s′/s = 0,230/0,00450 ≈ 51,1.","Med s′ = 5,00 m fås s = 5,00/51,1 ≈ 0,0978 m.","Spegelekvationen ger f = [1/s+1/s′]⁻¹ ≈ 0,0959 m och R = 2f ≈ 0,192 m."],["The screen image is real and inverted. |m| = s′/s = 0.230/0.00450 ≈ 51.1.","With s′ = 5.00 m, s = 5.00/51.1 ≈ 0.0978 m.","The mirror equation gives f = [1/s+1/s′]⁻¹ ≈ 0.0959 m and R = 2f ≈ 0.192 m."]],"34.68":[["Låt s vara avståndet från spegeln till lampan. Väggen ligger 3,00 m bortom lampan, så s′ = s+3,00 m.","Den reella bildens förstoring ger s′/s = 3,50. Därmed s = 1,20 m och spegel–vägg-avståndet s′ = 4,20 m.","f = [1/1,20+1/4,20]⁻¹ ≈ 0,933 m och R = 2f ≈ 1,87 m."],["Let s be the distance from mirror to bulb. The wall is 3.00 m beyond the bulb, so s′ = s+3.00 m.","The real image magnification gives s′/s = 3.50. Thus s = 1.20 m and mirror-to-wall distance s′ = 4.20 m.","f = [1/1.20+1/4.20]⁻¹ ≈ 0.933 m and R = 2f ≈ 1.87 m."]],"34.69":[["För den konvexa spegeln är f = −0,750 m. Sätt b = |s′| = |f|s/(s+|f|).","Derivering ger db/ds = [|f|/(s+|f|)]². Vid s = 2,0 m är faktorn (0,750/2,75)².","Bildens närmandefart 2,5 m/s motsvarar därför lastbilens relativa närmandefart 2,5/(0,750/2,75)² ≈ 33,6 m/s.","Lastbilen närmar sig bilen bakifrån, så dess hastighet längs vägen är 26+33,6 ≈ 60 m/s i bilens färdriktning."],["For the convex mirror f = −0.750 m. Put b = |s′| = |f|s/(s+|f|).","Differentiating gives db/ds = [|f|/(s+|f|)]². At s = 2.0 m the factor is (0.750/2.75)².","The image closing speed 2.5 m/s therefore corresponds to the truck’s relative closing speed 2.5/(0.750/2.75)² ≈ 33.6 m/s.","The truck approaches the car from behind, so its road velocity is 26+33.6 ≈ 60 m/s in the car’s direction."]],"34.70":[["För nära vinkelrät observation från luft bidrar varje skikt med sitt djup dividerat med sitt brytningsindex.","d_sken = 4,40/1,50+6,00/1,33 ≈ 7,44 cm under bensens övre yta."],["For near-normal viewing from air, each layer contributes its depth divided by its refractive index.","d_apparent = 4.40/1.50+6.00/1.33 ≈ 7.44 cm below the upper benzene surface."]],"34.71":[["Den konvexa spegeln har f = −R/2 = −0,0900 m. Med s = 9,00 m ger spegelekvationen s′ ≈ −0,0891 m.","m = −s′/s ≈ +0,00990 och h′ = m(1,5 m) ≈ +0,0149 m = 1,49 cm. Bilden är upprätt och virtuell.","Den förminskade synvinkeln kan ge intrycket att bilen är längre bort än den faktiskt är."],["The convex mirror has f = −R/2 = −0.0900 m. With s = 9.00 m the mirror equation gives s′ ≈ −0.0891 m.","m = −s′/s ≈ +0.00990 and h′ = m(1.5 m) ≈ +0.0149 m = 1.49 cm. The image is upright and virtual.","The reduced angular size can create the impression that the car is farther away than it really is."]],"34.72":[["I figurens skala ligger föremålet 5 rutor = 10,0 cm från linsen. Den givna inkommande strålens bakåtförlängning skär axeln 9 rutor = 18,0 cm framför linsen.","Strålen genom föremålssidans fokus lämnar linsen parallellt med axeln, alltså är linsen samlande med f = +18,0 cm.","En stråle genom linscentrum fortsätter rakt. En parallell stråle bryts genom bildsidans fokus; förläng de utgående strålarna bakåt till deras skärning.","1/s′ = 1/18,0−1/10,0 ger s′ = −22,5 cm och m = −s′/s = +2,25. Den virtuella, upprätta bilden ligger på föremålssidan, i överensstämmelse med konstruktionen."],["In the diagram the object is 5 squares = 10.0 cm from the lens. The given incoming ray’s backward extension crosses the axis 9 squares = 18.0 cm before the lens.","The ray through the object-side focus leaves parallel to the axis, so the lens is converging with f = +18.0 cm.","A ray through the lens center continues straight. A parallel ray refracts through the image-side focus; extend the outgoing rays backward to their intersection.","1/s′ = 1/18.0−1/10.0 gives s′ = −22.5 cm and m = −s′/s = +2.25. The virtual upright image is on the object side, consistent with the construction."]],"34.73":[["En smal stråle från föremålets topp går genom hålet till filmens nedre del; en stråle från botten når den övre delen. Bilden är därför inverterad.","Likformiga trianglar ger m = −s′/s = −0,225/1,4 ≈ −0,161.","För en höna med höjd 20 cm blir h′ = mh ≈ −3,21 cm; höjdbeloppet är cirka 3,2 cm."],["A narrow ray from the top passes through the hole to the lower film; a ray from the bottom reaches the upper film. The image is therefore inverted.","Similar triangles give m = −s′/s = −0.225/1.4 ≈ −0.161.","For a 20 cm tall chicken h′ = mh ≈ −3.21 cm; the height magnitude is about 3.2 cm."]],"34.74":[["För första linsen ger f₁ = +8,40 cm och s₁ = 28,0 cm bildavståndet s₁′ = +12,0 cm och m₁ = −12,0/28,0 = −3/7.","Den första bilden ligger 4,00 cm bortom lins 2 och är därför ett virtuellt föremål för den: s₂ = −4,00 cm.","Total förstoring är m = −5,60/4,00 = −1,40. Därför m₂ = m/m₁ = 49/15 och s₂′ = −m₂s₂ ≈ +13,07 cm.","f₂ = [1/s₂+1/s₂′]⁻¹ ≈ −5,76 cm. Avståndet från ursprungligt föremål till slutbild är 28,0+8,00+13,07 ≈ 49,1 cm."],["For lens 1, f₁ = +8.40 cm and s₁ = 28.0 cm give s₁′ = +12.0 cm and m₁ = −12.0/28.0 = −3/7.","The first image lies 4.00 cm beyond lens 2 and is therefore a virtual object for it: s₂ = −4.00 cm.","Total magnification is m = −5.60/4.00 = −1.40. Thus m₂ = m/m₁ = 49/15 and s₂′ = −m₂s₂ ≈ +13.07 cm.","f₂ = [1/s₂+1/s₂′]⁻¹ ≈ −5.76 cm. The original object-to-final-image separation is 28.0+8.00+13.07 ≈ 49.1 cm."]],"34.75":[["För parallella strålar vid första sfäriska luft–material-ytan är s = ∞ och R positivt.","Ytekvationen ger n/s′ = (n−1)/R. Om fokus ska ligga vid bortre ytan är s′ = 2R.","Då n/2 = n−1, vilket ger n = 2,00 i den paraxiella modellen."],["For parallel rays at the first spherical air-to-material surface, s = ∞ and R is positive.","The surface equation gives n/s′ = (n−1)/R. To focus at the far surface, s′ = 2R.","Then n/2 = n−1, yielding n = 2.00 in the paraxial model."]],"34.76":[["För utgående vatten–luft-brytning är den tecknade ytradien −R. Ytekvationen är n/s+1/s′ = (n−1)/R.","Med m = −ns′/s fås m = n/[n−(n−1)s/R]. För vatten ökar m när myntet förs bakåt i den paraxiella modellen.","Vid bakväggen är s = 2R och m_bak = n/(2−n). Lös n = 2m_bak/(1+m_bak).","För n ≈ 1,33 väntas m_bak ≈ 1,99. Mät m_bak i försöket och använd formeln; verklig glastjocklek och stora strålvinklar påverkar resultatet."],["For outgoing water-to-air refraction the signed surface radius is −R. The surface equation is n/s+1/s′ = (n−1)/R.","Using m = −ns′/s gives m = n/[n−(n−1)s/R]. For water m increases as the coin moves backward in the paraxial model.","At the back wall s = 2R and m_back = n/(2−n). Solve n = 2m_back/(1+m_back).","For n ≈ 1.33, m_back ≈ 1.99 is expected. Measure m_back in the experiment and use the formula; real glass thickness and large ray angles affect the result."]]};for(const e of root.EmberChapter34DraftExercises){const r=reviewed[e.id];if(r){e.sv.steps=r[0];e.en.steps=r[1]}}})(window);
(function(root){'use strict';const plant=root.EmberChapter34DraftExercises.find(x=>x.id==='34.72');plant.figure='assets/physics/chapter34/plant-problem-72.svg';plant.sv.alt='Växten är fem rutor från linsen. Den givna strålen lämnar linsen parallellt med axeln och dess bakåtförlängning skär axeln nio rutor från linsen. Varje ruta motsvarar 2 cm horisontellt.';plant.en.alt='The plant is five squares from the lens. The given ray leaves parallel to the axis and its backward extension crosses the axis nine squares from the lens. Each square represents 2 cm horizontally.';plant.solutionFigure='assets/physics/chapter34/plant-solution-72.svg';plant.sv.solutionAlt='Huvudstrålarnas bakåtförlängningar möts vid en upprätt virtuell bild 22,5 cm till vänster om linsen.';plant.en.solutionAlt='Backward extensions of principal rays meet at an upright virtual image 22.5 cm left of the lens.';const e=root.EmberChapter34DraftExercises.find(x=>x.id==='34.73');e.solutionFigure='assets/physics/chapter34/pinhole-solution-73.svg';e.sv.solutionAlt='Strålar från föremålets topp och botten korsas i kamerahålet och bildar en inverterad bild på filmen.';e.en.solutionAlt='Rays from the top and bottom of the object cross at the aperture and form an inverted image on the film.';})(window);

(function(root){'use strict';const reviewed={"34.77":[["(a) En reell bild är inverterad och har s′ = 2s. Linsekvationen ger s = 3f/2 = 52,5 cm.","(b) En virtuell upprätt bild har s′ = −2s och ger s = f/2 = 17,5 cm.","Båda fallen kräver positiv brännvidd, alltså en samlingslins."],["(a) A real image is inverted and has s′ = 2s. The lens equation gives s = 3f/2 = 52.5 cm.","(b) A virtual upright image has s′ = −2s and gives s = f/2 = 17.5 cm.","Both cases require positive focal length, hence a converging lens."]],"34.78":[["Föremålet och skärmen står intill varandra. Linsen är 22,0 cm från dem och planspegeln ytterligare 38,0 cm bort.","I den vanliga autokollimationslösningen ligger föremålet i linsens fokus. Strålarna går parallellt till spegeln och återvänder genom linsen till skärmen; därför f = 22,0 cm.","I en ideal paraxiell modell finns också ett särskilt matematiskt fall där första bilden ligger exakt på spegeln: 1/f = 1/22,0+1/38,0, alltså f ≈ 13,9 cm. Den lösningen bygger på denna särskilda bildplacering; den vanliga autokollimationen ger f = 22,0 cm."],["The object and screen are side by side. The lens is 22.0 cm from them, with the plane mirror a further 38.0 cm away.","In the standard autocollimation solution the object lies at the focal point. Rays travel parallel to the mirror and return through the lens to the screen; therefore f = 22.0 cm.","In an ideal paraxial model there is also a special mathematical case where the first image lies exactly on the mirror: 1/f = 1/22.0+1/38.0, giving f ≈ 13.9 cm. That solution depends on this special image placement; standard autocollimation gives f = 22.0 cm."]],"34.79":[["En reell bild av ett verkligt föremål kräver en samlingslins och är inverterad. |m| = s′/s = 5/3.","s+s′ = 214 cm ger s = 214·3/8 = 80,25 cm och s′ = 133,75 cm.","f = ss′/(s+s′) ≈ +50,2 cm."],["A real image of a real object requires a converging lens and is inverted. |m| = s′/s = 5/3.","s+s′ = 214 cm gives s = 214·3/8 = 80.25 cm and s′ = 133.75 cm.","f = ss′/(s+s′) ≈ +50.2 cm."]],"34.80":[["Bild och föremål ligger på samma sida: s = +8,00 cm och s′ = −3,00 cm.","1/f = 1/8,00−1/3,00 ger f = −4,80 cm, alltså en spridningslins.","m = −s′/s = +0,375 och h′ = +2,44 mm. Bilden är virtuell och upprätt."],["Image and object are on the same side: s = +8.00 cm and s′ = −3.00 cm.","1/f = 1/8.00−1/3.00 gives f = −4.80 cm, so the lens diverges.","m = −s′/s = +0.375 and h′ = +2.44 mm. The image is virtual and upright."]],"34.81":[["Föremålet är 16,0 cm från linsen och bilden ytterligare 6,00 cm åt vänster: s = +16,0 cm, s′ = −22,0 cm.","f = [1/16,0−1/22,0]⁻¹ ≈ +58,7 cm: linsen är samlande.","m = −s′/s = +1,375 och h′ = 1,375·3,25 mm ≈ +4,47 mm. Bilden är upprätt och virtuell."],["The object is 16.0 cm from the lens and the image a further 6.00 cm left: s = +16.0 cm, s′ = −22.0 cm.","f = [1/16.0−1/22.0]⁻¹ ≈ +58.7 cm: the lens converges.","m = −s′/s = +1.375 and h′ = 1.375·3.25 mm ≈ +4.47 mm. The image is upright and virtual."]],"34.82":[["Genom den plana ytan är skenbart djup d/n = 8,20 cm. Eftersom verkligt djup är 15,0 cm fås n = 15,0/8,20 ≈ 1,829.","För utgående brytning vid den krökta ytan är s = 15,0 cm, n₁ = 1,829, n₂ = 1,00 och R = −10,0 cm.","n₁/s+n₂/s′ = (n₂−n₁)/R ger s′ ≈ −25,6 cm. Föremålet verkar ligga 25,6 cm innanför den krökta ytans topp."],["Through the flat surface apparent depth d/n = 8.20 cm. Since actual depth is 15.0 cm, n = 15.0/8.20 ≈ 1.829.","For outgoing refraction at the curved surface, s = 15.0 cm, n₁ = 1.829, n₂ = 1.00 and R = −10.0 cm.","n₁/s+n₂/s′ = (n₂−n₁)/R gives s′ ≈ −25.6 cm. The object appears 25.6 cm inside the curved vertex."]],"34.83":[["(a) För s = ∞ och s′ = 2,50 cm ger ytekvationen 1,35/2,50 = 0,35/R. Därför R ≈ 0,648 cm = 6,48 mm.","(b) Med samma R och s = 25,0 cm är 1/25,0+1,35/s′ = 0,540 cm⁻¹. Då s′ = 2,70 cm, bakom näthinnan.","(c) Med faktisk radie R = 0,500 cm och s = ∞ fås s′ = 1,35R/0,35 ≈ 1,93 cm, framför näthinnan. Den förenklade hornhinnan ensam ger alltså inte det verkliga ögats fullständiga fokusering."],["(a) For s = ∞ and s′ = 2.50 cm, the surface equation gives 1.35/2.50 = 0.35/R. Thus R ≈ 0.648 cm = 6.48 mm.","(b) With the same R and s = 25.0 cm, 1/25.0+1.35/s′ = 0.540 cm⁻¹. Then s′ = 2.70 cm, behind the retina.","(c) With actual radius R = 0.500 cm and s = ∞, s′ = 1.35R/0.35 ≈ 1.93 cm, in front of the retina. The simplified cornea alone therefore does not reproduce the complete focusing of a real eye."]],"34.84":[["Linsmakarens ekvation ger 1/f = 0,60(1/12,0−1/28,0), alltså f = +35,0 cm.","(a) Med s₁ = 45,0 cm fås s₁′ = +157,5 cm och m₁ = −3,50. Bildhöjden är −17,5 mm.","(b) Vid 315 cm linsavstånd är s₂ = 315−157,5 = 157,5 cm, så s₂′ = +45,0 cm. Slutbilden ligger x = 360 cm från lins 1 och har höjden +5,00 mm, upprätt relativt ursprunget.","(c) Vid 45,0 cm linsavstånd är s₂ = 45,0−157,5 = −112,5 cm: ett virtuellt föremål. Då s₂′ ≈ +26,7 cm, x ≈ 71,7 cm och h′ ≈ −4,15 mm, inverterad relativt ursprunget."],["The lensmaker equation gives 1/f = 0.60(1/12.0−1/28.0), so f = +35.0 cm.","(a) With s₁ = 45.0 cm, s₁′ = +157.5 cm and m₁ = −3.50. Image height is −17.5 mm.","(b) At 315 cm separation, s₂ = 315−157.5 = 157.5 cm, so s₂′ = +45.0 cm. The final image is x = 360 cm from lens 1 and height +5.00 mm, upright relative to the original.","(c) At 45.0 cm separation, s₂ = 45.0−157.5 = −112.5 cm: a virtual object. Then s₂′ ≈ +26.7 cm, x ≈ 71.7 cm and h′ ≈ −4.15 mm, inverted relative to the original."]],"34.85":[["För vätska till luft är R = −2,50 cm. Ytekvationen blir 1,627/s+1/s′ = 0,627/2,50, med längder i cm.","(a) Ändlig reell bild kräver 1/s′ > 0, alltså s > 1,627·2,50/0,627 ≈ 6,487 cm; tubhöjden måste överstiga detta gränsvärde.","(b) s′ = 50,0 respektive 100 cm ger s ≈ 7,049 respektive 6,757 cm. Mittvärdet är s ≈ 6,903 cm.","(c) Vid mittvärdet ger ytekvationen s′ ≈ 66,2 cm.","(d) Amplituden är cirka 0,1464 cm och vid mitten är |ds/dt| = 2π(1,00)(0,1464) cm/s. Derivering ger ds′/dt = −(1,627s′²/s²)ds/dt ≈ +138 cm/s när föremålet rör sig uppåt.","(e) |m| = 1,627s′/s är störst vid s′ = 100 cm och ger bilddiametern ≈ 24,1 cm i paraxialmodellen. Rörelsen kring mittläget behöver en konstant förskjutning i sinusuttrycket."],["For liquid to air R = −2.50 cm. The surface equation becomes 1.627/s+1/s′ = 0.627/2.50, with lengths in cm.","(a) A finite real image requires 1/s′ > 0, so s > 1.627·2.50/0.627 ≈ 6.487 cm; tube height must exceed this limiting value.","(b) s′ = 50.0 and 100 cm give s ≈ 7.049 and 6.757 cm respectively. The midpoint is s ≈ 6.903 cm.","(c) At the midpoint the surface equation gives s′ ≈ 66.2 cm.","(d) The amplitude is approximately 0.1464 cm and at the midpoint |ds/dt| = 2π(1.00)(0.1464) cm/s. Differentiating gives ds′/dt = −(1.627s′²/s²)ds/dt ≈ +138 cm/s when the object moves upward.","(e) |m| = 1.627s′/s is largest at s′ = 100 cm, giving image diameter ≈ 24.1 cm in the paraxial model. Motion about the midpoint needs a constant offset in the sinusoidal expression."]],"34.86":[["s+s′ = 22,0 cm and ss′ = f(s+s′) = 66,0 cm².","Lös s(22,0−s) = 66,0: s = (22,0±√220)/2 ≈ 3,58 eller 18,42 cm från föremålet.","m = −s′/s ger cirka −5,14 för det första läget och −0,195 för det andra. Båda bilderna är inverterade."],["s+s′ = 22.0 cm and ss′ = f(s+s′) = 66.0 cm².","Solve s(22.0−s) = 66.0: s = (22.0±√220)/2 ≈ 3.58 or 18.42 cm from the object.","m = −s′/s gives approximately −5.14 for the first position and −0.195 for the second. Both images are inverted."]],"34.87":[["Med glasögon 0,020 m framför ögat ska bilden ligga s′ = −(0,85−0,02) = −0,83 m från linsen.","1/s = 2,25+1/0,83 ger s ≈ 0,289 m från linsen, alltså 0,309 m från ögat.","För en kontaktlins är s′ = −0,85 m och 1/s = 2,25+1/0,85. Närpunkten blir cirka 0,292 m från ögat."],["With glasses 0.020 m in front of the eye, the image must be s′ = −(0.85−0.02) = −0.83 m from the lens.","1/s = 2.25+1/0.83 gives s ≈ 0.289 m from the lens, or 0.309 m from the eye.","For a contact lens s′ = −0.85 m and 1/s = 2.25+1/0.85. The near point is approximately 0.292 m from the eye."]],"34.88":[["För en reell bild på skärmen är d = s+s′ och linsekvationen ger ss′ = fd.","För givet d gäller ss′ ≤ [(s+s′)/2]² = d²/4, så fd ≤ d²/4 och d ≥ 4f.","Likhet fås när s = s′ = 2f. Därför är minsta avståndet d_min = 4f."],["For a real screen image d = s+s′ and the lens equation gives ss′ = fd.","For fixed d, ss′ ≤ [(s+s′)/2]² = d²/4, so fd ≤ d²/4 and d ≥ 4f.","Equality occurs when s = s′ = 2f. Therefore the minimum separation is d_min = 4f."]]};for(const e of root.EmberChapter34DraftExercises){const r=reviewed[e.id];if(r){e.sv.steps=r[0];e.en.steps=r[1]}}})(window);

(function(root){'use strict';const reviewed={"34.89":[["Spegelfokus är 10,0 cm, så krökningscentrum och ljuset ligger 20,0 cm framför spegeln. Spegeln ger en reell inverterad mellanbild på samma avstånd.","För både direkt ljus och spegelreflekterat ljus är linsens föremålsavstånd 85,0 cm. 1/s′ = 1/32,0−1/85,0 ger s′ ≈ +51,3 cm till höger om linsen.","Linsen inverterar direktbilden: den är reell och inverterad. Spegelns mellanbild inverteras en gång till av linsen, så den andra bilden är reell och upprätt relativt ljuset."],["The mirror focal length is 10.0 cm, so the center of curvature and candle are 20.0 cm in front of the mirror. The mirror forms a real inverted intermediate image at that distance.","For both direct and reflected light the lens object distance is 85.0 cm. 1/s′ = 1/32.0−1/85.0 gives s′ ≈ +51.3 cm to the right of the lens.","The lens inverts the direct image: it is real and inverted. The mirror intermediate image is inverted again by the lens, so the second image is real and upright relative to the candle."]],"34.90":[["(a) För två linser i kontakt är andra linsens föremålsavstånd s₂ = −s₁′. Addition av linsekvationerna tar bort mellanbildens reciprok och ger 1/f_eff = 1/f₁+1/f₂.","(b) Glasmenisken har styrkan P₁ = (1,55−1)(1/4,50−1/9,00) = 0,06111 cm⁻¹.","Vätskan bildar en plankonvex lins med P₂ = (1,46−1)/9,00 = 0,05111 cm⁻¹.","P_tot = 0,11222 cm⁻¹ och f_eff = 1/P_tot ≈ +8,91 cm."],["(a) For two lenses in contact the second object distance is s₂ = −s₁′. Adding the lens equations cancels the intermediate reciprocal and gives 1/f_eff = 1/f₁+1/f₂.","(b) The glass meniscus power is P₁ = (1.55−1)(1/4.50−1/9.00) = 0.06111 cm⁻¹.","The liquid forms a plano-convex lens with P₂ = (1.46−1)/9.00 = 0.05111 cm⁻¹.","P_total = 0.11222 cm⁻¹ and f_eff = 1/P_total ≈ +8.91 cm."]],"34.91":[["Utan den andra linsen skulle bilden ligga 30,0 cm från den första. Andra linsen är vid 15,0 cm, så dess virtuella föremål har s₂ = −15,0 cm.","Den nya skärmpositionen är 30,0+19,2 = 49,2 cm från första linsen, alltså s₂′ = +34,2 cm.","f₂ = [1/s₂+1/s₂′]⁻¹ = [−1/15,0+1/34,2]⁻¹ ≈ −26,7 cm."],["Without the second lens the image would lie 30.0 cm from the first. The second lens is at 15.0 cm, so its virtual object has s₂ = −15.0 cm.","The new screen position is 30.0+19.2 = 49.2 cm from lens 1, hence s₂′ = +34.2 cm.","f₂ = [1/s₂+1/s₂′]⁻¹ = [−1/15.0+1/34.2]⁻¹ ≈ −26.7 cm."]],"34.92":[["(a) Använd brytningsekvationen för varje yta, med vätska på båda sidor om den tunna linsen. Mellanbildens reciproker försvinner när ekvationerna adderas.","Resultatet är 1/f = (n_lins/n_vätska−1)(1/R₁−1/R₂).","(b) Samma geometrifaktor gäller i luft och vätska. f_vätska = 18,0(1,60−1)/(1,60/1,42−1) ≈ +85,2 cm."],["(a) Apply the refraction equation at each surface, with liquid on both sides of the thin lens. The intermediate-image reciprocal terms cancel when the equations are added.","The result is 1/f = (n_lens/n_liquid−1)(1/R₁−1/R₂).","(b) The same geometric factor applies in air and liquid. f_liquid = 18.0(1.60−1)/(1.60/1.42−1) ≈ +85.2 cm."]],"34.93":[["Den konvexa spegeln har f = −24,0 cm. Direkt för s = 10,0 cm ger spegelekvationen s′ ≈ −7,06 cm och m ≈ +0,706.","Direktbildens höjd är h′ ≈ +0,176 cm bakom den konvexa spegeln.","Den plana spegeln ger en upprätt bild 10,0 cm bakom sig, alltså 30,0 cm framför den konvexa spegeln. Använd s = 30,0 cm: s′ ≈ −13,3 cm, m ≈ +0,444 och h′ ≈ +0,111 cm."],["The convex mirror has f = −24.0 cm. For the direct object at s = 10.0 cm, the mirror equation gives s′ ≈ −7.06 cm and m ≈ +0.706.","The direct image height is h′ ≈ +0.176 cm behind the convex mirror.","The plane mirror gives an upright image 10.0 cm behind it, or 30.0 cm in front of the convex mirror. Use s = 30.0 cm: s′ ≈ −13.3 cm, m ≈ +0.444 and h′ ≈ +0.111 cm."]],"34.94":[["Ögonmodellen har |m| = s′/s = 2,50/25,0 = 0,100. En receptorbred bild 5,0 μm kräver därför en föremålsbredd 5,0/0,100 = 50 μm.","Småvinkeln är θ ≈ 50·10⁻⁶/0,25 = 2,0·10⁻⁴ rad. Multiplicerat med 180/π och 60 ger det cirka 0,69 bågminuter, jämförbart med 1 bågminut."],["The eye model has |m| = s′/s = 2.50/25.0 = 0.100. A one-receptor image of width 5.0 μm therefore requires object width 5.0/0.100 = 50 μm.","The small angle is θ ≈ 50×10⁻⁶/0.25 = 2.0×10⁻⁴ rad. Multiplying by 180/π and 60 gives about 0.69 arcminutes, comparable to 1 arcminute."]],"34.95":[["För lins 1 är s₁ = 80,0 cm och f₁ = 40,0 cm, så s₁′ = +80,0 cm.","Denna bild ligger 28,0 cm bortom lins 2: s₂ = −28,0 cm och s₂′ = [1/40,0+1/28,0]⁻¹ ≈ +16,47 cm.","För lins 3 är s₃ = 52,0−16,47 ≈ 35,53 cm. Linsekvationen ger s₃′ ≈ −318 cm.","Slutbilden är virtuell och ligger cirka 318 cm till vänster om tredje linsen."],["For lens 1, s₁ = 80.0 cm and f₁ = 40.0 cm, so s₁′ = +80.0 cm.","This image lies 28.0 cm beyond lens 2: s₂ = −28.0 cm and s₂′ = [1/40.0+1/28.0]⁻¹ ≈ +16.47 cm.","For lens 3, s₃ = 52.0−16.47 ≈ 35.53 cm. The lens equation gives s₃′ ≈ −318 cm.","The final image is virtual, about 318 cm left of the third lens."]],"34.96":[["Använd mm: f = 90 mm, s₁ = 1300 mm och s₂ = 6500 mm.","Linsekvationen ger s₁′ = [1/90−1/1300]⁻¹ ≈ 96,69 mm och s₂′ = [1/90−1/6500]⁻¹ ≈ 91,26 mm.","Avståndet lins–sensor minskar med cirka 5,43 mm; linsen flyttas mot sensorn."],["Use mm: f = 90 mm, s₁ = 1300 mm and s₂ = 6500 mm.","The lens equation gives s₁′ = [1/90−1/1300]⁻¹ ≈ 96.69 mm and s₂′ = [1/90−1/6500]⁻¹ ≈ 91.26 mm.","Lens-to-sensor distance decreases by about 5.43 mm; move the lens toward the sensor."]],"34.97":[["Eftersom ögat utan ackommodation fokuserar parallella strålar ska kontaktlinsen bilda en bild vid oändligheten.","Läsavståndet är då linsens brännvidd: f = +0,24 m och P = 1/f ≈ +4,17 D."],["Because the non-accommodating eye focuses parallel rays, the contact lens must form an image at infinity.","The reading distance is then the lens focal length: f = +0.24 m and P = 1/f ≈ +4.17 D."]],"34.98":[["Använd brytning i hornhinnans sfäriska yta med s = 36,0 cm, R = +0,75 cm, n₁ = 1,00 och n₂ = 1,40.","1/36,0+1,40/s′ = 0,40/0,75 ger s′ ≈ 2,77 cm.","Det är större än 2,60 cm i jämförelsemodellen: detta modellöga är längre framifrån och bakåt. Verklig närsynthet kan ha flera orsaker."],["Use refraction at the spherical corneal surface with s = 36.0 cm, R = +0.75 cm, n₁ = 1.00 and n₂ = 1.40.","1/36.0+1.40/s′ = 0.40/0.75 gives s′ ≈ 2.77 cm.","This exceeds 2.60 cm in the comparison model: this model eye is longer front-to-back. Real nearsightedness can have multiple causes."]],"34.99":[["(a) Vid första linsen konvergerar parallella strålar mot dess fokus. Likformiga trianglar ger r₂ = r₀(f₁−d)/f₁.","(b) För andra linsen är föremålet virtuellt: s₂ = −(f₁−d). Med f₂ = −|f₂| ger linsekvationen s₂′ = |f₂|(f₁−d)/(|f₂|−f₁+d).","(c) Förläng de utgående strålarna bakåt tills knippets radie är r₀. Likformiga trianglar ger f_eff = s₂′r₀/r₂ = f₁|f₂|/(|f₂|−f₁+d).","(d) Med angivna värden är f_eff = 216/(6+d) cm. Största värdet är 36,0 cm vid d = 0, minsta 21,6 cm vid d = 4,0 cm. För f_eff = 30,0 cm fås d = 1,20 cm."],["(a) At lens 1 parallel rays converge toward its focus. Similar triangles give r₂ = r₀(f₁−d)/f₁.","(b) The object for lens 2 is virtual: s₂ = −(f₁−d). With f₂ = −|f₂| the lens equation gives s₂′ = |f₂|(f₁−d)/(|f₂|−f₁+d).","(c) Extend the outgoing rays backward until the bundle radius is r₀. Similar triangles give f_eff = s₂′r₀/r₂ = f₁|f₂|/(|f₂|−f₁+d).","(d) With the stated values f_eff = 216/(6+d) cm. The maximum is 36.0 cm at d = 0, the minimum 21.6 cm at d = 4.0 cm. For f_eff = 30.0 cm, d = 1.20 cm."]],"34.100":[["Med små vinklar ger objektiv och spridningsokular M = −f₁/f₂. Eftersom f₂ < 0 blir M positivt: bilden är upprätt.","Samma förstoringsbelopp som 95,0/15,0 kräver f₂ = −15,0 cm för objektivet f₁ = +95,0 cm.","Galileiskt teleskop: linsavstånd f₁−|f₂| = 80,0 cm. Det astronomiska teleskopet med positivt okular har längden 95,0+15,0 = 110,0 cm."],["For small angles objective and diverging eyepiece give M = −f₁/f₂. Because f₂ < 0, M is positive: the image is upright.","The same magnification magnitude as 95.0/15.0 requires f₂ = −15.0 cm with objective f₁ = +95.0 cm.","Galilean telescope: lens separation f₁−|f₂| = 80.0 cm. The astronomical telescope with a positive eyepiece has length 95.0+15.0 = 110.0 cm."]]};for(const e of root.EmberChapter34DraftExercises){const r=reviewed[e.id];if(r){e.sv.steps=r[0];e.en.steps=r[1]}}})(window);

(function(root){'use strict';const reviewed={"34.101":[["Den första linsens mellanbild ligger vid x = 29,7 cm.","För lins 2 vid x = 20,0 cm är s₂ = −9,7 cm och s₂′ = 42,8−20,0 = +22,8 cm. Linsekvationen ger f₂ ≈ −16,88 cm.","Vid x = 25,0 cm är s₂ = −4,7 cm och s₂′ = 31,6−25,0 = +6,6 cm. Då f₂ ≈ −16,33 cm; medelvärdet är cirka −16,6 cm.","Förstoringsbeloppen för lins 2 är 22,8/9,7 ≈ 2,35 respektive 6,6/4,7 ≈ 1,40. Samma mellanbild ger därför större slutbild i första läget."],["The first lens’s intermediate image lies at x = 29.7 cm.","For lens 2 at x = 20.0 cm, s₂ = −9.7 cm and s₂′ = 42.8−20.0 = +22.8 cm. The lens equation gives f₂ ≈ −16.88 cm.","At x = 25.0 cm, s₂ = −4.7 cm and s₂′ = 31.6−25.0 = +6.6 cm. Then f₂ ≈ −16.33 cm; the mean is approximately −16.6 cm.","Lens-2 magnification magnitudes are 22.8/9.7 ≈ 2.35 and 6.6/4.7 ≈ 1.40. With the same intermediate image, the first position produces the taller final image."]],"34.102":[["Sätt s′ = −ms i spegelekvationen: s = f(1−1/m). Grafens skärning vid 1/m = 0 är alltså f = 25 cm.","En inverterad bild med dubbla höjden har m = −2 och s = 25(1+1/2) = 37,5 cm.","För m = −3 är s = 25(1+1/3) ≈ 33,3 cm. Föremålet flyttas 4,17 cm närmare spegeln.","Vid s = f går bilden mot oändligheten och ingen ändlig skärm kan fånga den. För s < f är bilden virtuell och upprätt bakom spegeln, inte på skärmen."],["Substitute s′ = −ms into the mirror equation: s = f(1−1/m). The intercept at 1/m = 0 is therefore f = 25 cm.","An inverted image twice as tall has m = −2 and s = 25(1+1/2) = 37.5 cm.","For m = −3, s = 25(1+1/3) ≈ 33.3 cm. Move the object 4.17 cm closer to the mirror.","At s = f the image goes to infinity and no finite screen captures it. For s < f the image is virtual and upright behind the mirror, not on the screen."]],"34.103":[["Ytekvationen för luft till glas ger 1/s′ = −(1/n)(1/s)+(n−1)/(nR), en rät linje i reciprokerna.","En linjär minsta-kvadratanpassning av de sex dataparen ger lutning ≈ −0,66662 och skärning ≈ 0,03333 cm⁻¹.","Därmed n = −1/lutning ≈ 1,500 och R = (n−1)/(n·skärning) ≈ 10,0 cm.","Vid s = 15,0 cm ger den anpassade linjen s′ ≈ −90,0 cm: bilden är virtuell på föremålssidan."],["The surface equation for air to glass gives 1/s′ = −(1/n)(1/s)+(n−1)/(nR), a straight line in the reciprocals.","A linear least-squares fit to the six data pairs gives slope ≈ −0.66662 and intercept ≈ 0.03333 cm⁻¹.","Thus n = −1/slope ≈ 1.500 and R = (n−1)/(n·intercept) ≈ 10.0 cm.","At s = 15.0 cm the fitted line gives s′ ≈ −90.0 cm: the image is virtual on the object side."]],"34.104":[["Parabeln y = ax² har lutning dy/dx = 2ax, alltså 2ar vid träffpunkten. Normalens lutning är −1/(2ar).","Normalens vinkel φ mot den vertikala axeln uppfyller tan φ = 2ar. Reflektionslagen ger α = 2φ−π/2 för den visade strålen.","I figurens fall ligger träffpunkten över fokus. Då b = r tan α = −r cot(2φ) = ar²−1/(4a).","Träffpunkten har höjd ar², så fokushöjden är f = ar²−b = 1/(4a), oberoende av r. För mindre r byter den tecknade höjdskillnaden riktning, men samma fokus gäller."],["The parabola y = ax² has slope dy/dx = 2ax, hence 2ar at the hit point. The normal slope is −1/(2ar).","The normal’s angle φ to the vertical axis satisfies tan φ = 2ar. The law of reflection gives α = 2φ−π/2 for the ray as drawn.","In the figure the hit point is above the focus. Then b = r tan α = −r cot(2φ) = ar²−1/(4a).","The hit point is at height ar², so the focal height is f = ar²−b = 1/(4a), independent of r. For smaller r the signed height difference reverses, but the same focus applies."]],"34.105":[["För en reell bild måste s > f. Linsekvationen ger s′ = fs/(s−f) och avståndet D(s) = s+fs/(s−f).","D′(s) = 1−f²/(s−f)² är noll vid s = 2f. Där är D″ > 0 och D_min = 2f+2f = 4f.","Grafen går mot oändligheten när s → f ovanifrån och när s → ∞, med minimum vid (2f, 4f)."],["A real image requires s > f. The lens equation gives s′ = fs/(s−f) and separation D(s) = s+fs/(s−f).","D′(s) = 1−f²/(s−f)² vanishes at s = 2f. There D″ > 0 and D_min = 2f+2f = 4f.","The graph tends to infinity as s → f from above and as s → ∞, with minimum at (2f, 4f)."]],"34.106":[["Använd koordinater (x,y) i cm från linsen, positiva åt höger och uppåt. Halva pennan ger horisontell och vertikal förskjutning 8/√2 cm.","A har s_A = 45+8/√2 och h_A = 15−8/√2; B har s_B = 45−8/√2 och h_B = 15+8/√2.","För varje punkt används s′ = fs/(s−f) och h′ = −s′h/s. Då A′ ≈ (33,05; −6,10), B′ ≈ (40,68; −21,36) och C′ = (36,0; −12,0).","Avståndsformeln ger A′B′ ≈ 17,1 cm. Bilden ligger under axeln och lutar nedåt åt höger."],["Use coordinates (x,y) in cm from the lens, positive rightward and upward. The half-pencil gives horizontal and vertical offsets of 8/√2 cm.","A has s_A = 45+8/√2 and h_A = 15−8/√2; B has s_B = 45−8/√2 and h_B = 15+8/√2.","For each point use s′ = fs/(s−f) and h′ = −s′h/s. Thus A′ ≈ (33.05, −6.10), B′ ≈ (40.68, −21.36) and C′ = (36.0, −12.0).","The distance formula gives A′B′ ≈ 17.1 cm. The image lies below the axis and slopes downward to the right."]],"34.107":[["I luft ger modellen från 34.52 hornhinneradien R = 0,40/[1/40,0+1,40/2,60] ≈ 0,7099 cm.","I vatten är indexskillnaden vid hornhinnan bara 1,40−1,33 = 0,07, så brytkraften minskar. För fokus på näthinnan kräver 1,33/s+1,40/2,60 = 0,07/R att s ≈ −3,024 cm.","Det negativa s betyder att hornhinnan behöver ett infallande knippe som konvergerar mot en virtuell föremålspunkt 3,024 cm bakom hornhinnan. Linsen är 2,00 cm framför hornhinnan, så dess vattenbrännvidd måste vara f_vatten = 2,00+3,024 ≈ +5,024 cm.","Samma ytgeometri ger f_luft = f_vatten(1,62/1,33−1)/(1,62−1) ≈ +1,77 cm."],["In air the model from 34.52 gives corneal radius R = 0.40/[1/40.0+1.40/2.60] ≈ 0.7099 cm.","In water the corneal index difference is only 1.40−1.33 = 0.07, reducing its power. To focus on the retina, 1.33/s+1.40/2.60 = 0.07/R requires s ≈ −3.024 cm.","Negative s means the cornea needs incoming rays converging toward a virtual object point 3.024 cm behind the cornea. The lens is 2.00 cm in front of the cornea, so its focal length in water must be f_water = 2.00+3.024 ≈ +5.024 cm.","For the same surface geometry, f_air = f_water(1.62/1.33−1)/(1.62−1) ≈ +1.77 cm."]],"34.108":[["Med cm som enhet ger första läget f = [1/10+1/0,8]⁻¹ ≈ 0,7407 cm.","Vid ungefär s = 15 cm ger samma f bildavståndet s′ = [1/f−1/15]⁻¹ ≈ 0,7792 cm.","Lins–näthinna-avståndet minskar med cirka 0,8000−0,7792 = 0,0208 cm. Linsen flyttas mot näthinnan: alternativ (a)."],["Using cm, the initial configuration gives f = [1/10+1/0.8]⁻¹ ≈ 0.7407 cm.","At approximately s = 15 cm the same f gives image distance s′ = [1/f−1/15]⁻¹ ≈ 0.7792 cm.","Lens-to-retina distance decreases by about 0.8000−0.7792 = 0.0208 cm. The lens moves toward the retina: choice (a)."]],"34.109":[["En kontaktlins med P = −6,0 D har f = 1/P = −0,167 m. Ett avlägset föremål får en virtuell bild vid denna fokuspunkt.","Grodans okorrigerade fjärrpunkt ligger alltså cirka 0,17 m = 17 cm framför ögat: alternativ (d)."],["A contact lens with P = −6.0 D has f = 1/P = −0.167 m. A distant object forms a virtual image at this focus.","The frog’s uncorrected far point is therefore about 0.17 m = 17 cm in front of the eye: choice (d)."]],"34.110":[["Skillnaden mellan vattnets och ögats brytningsindex är mindre än mellan luftens och ögats. Hornhinnans samlande effekt minskar därför i vatten.","I den förenklade modellen minskar närsyntheten: alternativ (b). Den exakta förändringen beror på hela ögats optik och kan inte bestämmas enbart från detta."],["The difference between water and eye refractive indices is smaller than between air and eye. The cornea’s converging power therefore decreases in water.","In the simplified model nearsightedness decreases: choice (b). The exact change depends on the whole eye’s optics and cannot be determined from this alone."]],"34.111":[["Båda kontaktlinserna är spridande. För samma positiva föremålsavstånd gäller 1/s′ = P−1/s och s′ är negativt.","Styrkan −15 D ger större |1/s′| än −9 D och därmed mindre |s′|. Den virtuella bilden är närmare grodan: alternativ (b)."],["Both contact lenses are diverging. For the same positive object distance, 1/s′ = P−1/s and s′ is negative.","Power −15 D gives a larger |1/s′| than −9 D and hence a smaller |s′|. The virtual image is closer to the frog: choice (b)."]]};for(const e of root.EmberChapter34DraftExercises){const r=reviewed[e.id];if(r){e.sv.steps=r[0];e.en.steps=r[1]}}})(window);
(function(root){'use strict';const choices={
'34.108':[['(a) 0,02 cm mot näthinnan','(b) 0,02 cm från näthinnan','(c) 0,06 cm mot näthinnan','(d) 0,06 cm från näthinnan'],['(a) 0.02 cm toward the retina','(b) 0.02 cm away from the retina','(c) 0.06 cm toward the retina','(d) 0.06 cm away from the retina']],
'34.109':[['(a) 12 m','(b) 6,0 m','(c) 80 cm','(d) 17 cm'],['(a) 12 m','(b) 6.0 m','(c) 80 cm','(d) 17 cm']],
'34.110':[['(a) Mer närsynt: vattnet ökar ögats brytning.','(b) Mindre närsynt: hornhinnan bryter mindre i vatten.','(c) Oförändrat: endast ögats inre delar påverkar fokuseringen.','(d) Näthinnebilden är inte längre inverterad: ögat fungerar som en spridningslins.'],['(a) More nearsighted: water increases the eye’s refraction.','(b) Less nearsighted: the cornea refracts less in water.','(c) Unchanged: only internal eye structures affect focusing.','(d) Retinal images are no longer inverted: the eye acts as a diverging lens.']],
'34.111':[['(a) −9 D: den spridande linsen med längre brännvidd ger närmare bild.','(b) −15 D: den spridande linsen med kortare brännviddsbelopp ger närmare bild.','(c) −9 D: den samlande linsen med längre brännvidd ger en större reell bild.','(d) −15 D: den samlande linsen med kortare brännvidd ger en större reell bild.'],['(a) −9 D: the diverging lens with longer focal length gives a closer image.','(b) −15 D: the diverging lens with shorter focal-length magnitude gives a closer image.','(c) −9 D: the converging lens with longer focal length gives a larger real image.','(d) −15 D: the converging lens with shorter focal length gives a larger real image.']]
};for(const e of root.EmberChapter34DraftExercises){const c=choices[e.id];if(c){e.sv.prompt+=' Svarsalternativ: '+c[0].join(' ');e.en.prompt+=' Choices: '+c[1].join(' ');}}const e=root.EmberChapter34DraftExercises.find(x=>x.id==='34.85');e.sv.prompt+=' Tubens radie är 1,50 cm.';e.en.prompt+=' The tube radius is 1.50 cm.';const f=root.EmberChapter34DraftExercises.find(x=>x.id==='34.90');f.sv.prompt=f.sv.prompt.replace('en vätska med n = 1,46','koltetraklorid med n = 1,46');f.en.prompt=f.en.prompt.replace('liquid of n = 1.46','carbon tetrachloride of n = 1.46');})(window);
(function(root){'use strict';for(const id of ['34.30','34.40','34.41','34.42','34.72','34.73']){const e=root.EmberChapter34DraftExercises.find(x=>x.id===id);if(e.figure)e.figure=e.figure.replace(/^assets\/physics\/chapter34\//,'');if(e.solutionFigure)e.solutionFigure=e.solutionFigure.replace(/^assets\/physics\/chapter34\//,'');if(e.sv.alt||e.en.alt)e.alt={sv:e.sv.alt,en:e.en.alt};if(e.sv.solutionAlt||e.en.solutionAlt)e.solutionAlt={sv:e.sv.solutionAlt,en:e.en.solutionAlt};}})(window);
(function(root){'use strict';const figures=[['34.102','figure','mirror-graph-102.svg','Diagram med s i centimeter mot 1/m; den anpassade linjen skär s-axeln vid 25 cm. Punkterna är rekonstruerade från bokens diagram.','Graph of s in centimeters versus 1/m; the fitted line intercepts the s axis at 25 cm. Points are reconstructed from the textbook graph.'],['34.103','solutionFigure','refraction-fit-103.svg','Sex mätpunkter för 1/s′ mot 1/s och en linjär minsta-kvadratanpassning.','Six measurements of 1/s′ against 1/s and a linear least-squares fit.'],['34.105','solutionFigure','separation-solution-105.svg','Graf över D/f mot s/f. Kurvan har minimum vid s/f = 2 och D/f = 4.','Graph of D/f versus s/f. The curve has its minimum at s/f = 2 and D/f = 4.']];for(const [id,key,file,sv,en] of figures){const e=root.EmberChapter34DraftExercises.find(x=>x.id===id);e[key]=file;e[key==='figure'?'alt':'solutionAlt']={sv,en};}})(window);
