(function(root){'use strict';const e=root.EmberChapter34DraftExercises.find(x=>x.id==='34.81');e.solutionFigure='converging-ray-81.svg';e.solutionAlt={sv:'En samlingslins ger en förstorad upprätt virtuell bild 22 centimeter till vänster när föremålet står 16 centimeter till vänster. Bakåtförlängningarna möts i bilden.',en:'A converging lens gives an enlarged upright virtual image 22 centimeters to the left when the object is 16 centimeters to the left. Backward extensions meet at the image.'};})(window);

(function(root){'use strict';const reviewed={"34.1": [["En plan spegel ger en bildpunkt lika långt bakom ytan som föremålspunkten är framför.", "Ljusets avstånd till spegeln är 39,2 cm.", "Bilden ligger därför 39,2 cm bakom spegeln.", "En plan spegel har lateral förstoring +1.", "Bilden är virtuell, upprätt och 4,85 cm hög."], ["A plane mirror places each image point as far behind the surface as its object point is in front.", "The candle is 39.2 cm from the mirror.", "The image is therefore 39.2 cm behind it.", "A plane mirror has lateral magnification +1.", "The image is virtual, upright and 4.85 cm high."]], "34.2": [["Trädets virtuella bild ligger 20,0 m bakom spegeln.", "Ögat ligger 0,340 m framför spegeln, så avståndet till bilden är 20,34 m.", "Likformiga trianglar ger H/20,34 = 0,0370/0,340.", "Lös H = 20,34·0,0370/0,340 m.", "Trädets uppskattade höjd är cirka 2,21 m i paraxiell geometri."], ["The tree’s virtual image is 20.0 m behind the mirror.", "The eye is 0.340 m in front of the mirror, so image distance from the eye is 20.34 m.", "Similar triangles give H/20.34 = 0.0370/0.340.", "Solve H = 20.34·0.0370/0.340 m.", "The estimated tree height is about 2.21 m in paraxial geometry."]], "34.3": [["Varje bildpunkt ligger lika långt bakom spegeln som motsvarande föremålspunkt framför.", "Spetsens bild ligger därför 12,0 cm bakom spegeln.", "Suddgummits bild ligger 21,0 cm bakom spegeln.", "Bildens längd är 21,0−12,0 = 9,0 cm.", "Spetsens bild ligger närmast spegeln."], ["Each image point lies as far behind the mirror as its object point lies in front.", "The tip image is therefore 12.0 cm behind the mirror.", "The eraser image is 21.0 cm behind the mirror.", "The image length is 21.0−12.0 = 9.0 cm.", "The tip image is closest to the mirror."]], "34.4": [["För en paraxiell sfärisk spegel är brännvidden f = R/2.", "En konkav spegel har positiv brännvidd i den använda teckenkonventionen.", "Med R = 36,0 cm blir f = +18,0 cm.", "Reflektionslagen beror inte på det homogena omgivande mediets brytningsindex.", "Brännvidden är därför +18,0 cm både i luft och i vatten i denna modell."], ["For a paraxial spherical mirror the focal length is f = R/2.", "A concave mirror has positive focal length in the convention used.", "With R = 36.0 cm, f = +18.0 cm.", "The reflection law does not depend on the homogeneous surrounding medium’s refractive index.", "The focal length is therefore +18.0 cm both in air and in water in this model."]], "34.5": [["Den konkava spegeln har f = R/2 = +11,0 cm och föremålsavståndet är s = 16,5 cm.", "Spegelekvationen ger 1/s′ = 1/11,0−1/16,5, alltså s′ = +33,0 cm.", "Förstoringen är m = −s′/s = −2,00 och bildhöjden h′ = mh = −1,20 cm.", "Positivt s′ och negativ höjd betyder en reell, inverterad bild framför spegeln.", "En axelparallell stråle reflekteras genom fokus; en stråle genom fokus reflekteras parallellt med axeln. Deras skärning ger bilden."], ["The concave mirror has f = R/2 = +11.0 cm and object distance s = 16.5 cm.", "The mirror equation gives 1/s′ = 1/11.0−1/16.5, hence s′ = +33.0 cm.", "Magnification is m = −s′/s = −2.00 and image height h′ = mh = −1.20 cm.", "Positive s′ and negative height mean a real inverted image in front of the mirror.", "A ray parallel to the axis reflects through the focus; a ray through the focus reflects parallel to the axis. Their intersection gives the image."]], "34.6": [["Den konvexa spegeln har f = −R/2 = −11,0 cm.", "För s = 16,5 cm ger 1/s′ = 1/f−1/s bildavståndet s′ = −6,60 cm.", "Förstoringen är m = −s′/s = +0,400.", "Bildhöjden är h′ = mh = +0,240 cm; bilden är virtuell, upprätt och förminskad bakom spegeln.", "De reflekterade strålarna divergerar och deras bakåtförlängningar skär varandra i den virtuella bilden."], ["The convex mirror has f = −R/2 = −11.0 cm.", "For s = 16.5 cm, 1/s′ = 1/f−1/s gives s′ = −6.60 cm.", "Magnification is m = −s′/s = +0.400.", "Image height is h′ = mh = +0.240 cm; the image is virtual, upright and reduced behind the mirror.", "The reflected rays diverge and their backward extensions intersect at the virtual image."]], "34.7": [["Mars vinkeldiameter är för små vinklar ungefär θ = D/d.", "Med de angivna avstånden är θ ≈ 6794/(5,58·10⁷) rad.", "Ett mycket avlägset objekt bildas nära spegelns fokus.", "Bilddiametern är därför ungefär fθ.", "Med f = 1,85 m fås cirka 2,25·10⁻⁴ m = 0,225 mm."], ["For small angles Mars’s angular diameter is approximately θ = D/d.", "With the stated distances θ ≈ 6794/(5.58·10⁷) rad.", "A very distant object forms its image near the mirror focus.", "The image diameter is therefore approximately fθ.", "With f = 1.85 m this is about 2.25·10⁻⁴ m = 0.225 mm."]], "34.8": [["Kulans radie är 5,80/2 = 2,90 cm.", "Avståndet från föremålet till närmaste spegelytan är s = 24,1−2,90 = 21,2 cm.", "Den konvexa spegeln har f = −2,90/2 = −1,45 cm.", "Spegelekvationen ger s′ ≈ −1,36 cm.", "Förstoringen m = −s′/s ≈ +0,0640; bilden är virtuell och upprätt bakom ytan."], ["The sphere radius is 5.80/2 = 2.90 cm.", "The object distance from the nearest mirror surface is s = 24.1−2.90 = 21.2 cm.", "The convex mirror has f = −2.90/2 = −1.45 cm.", "The mirror equation gives s′ ≈ −1.36 cm.", "Magnification m = −s′/s ≈ +0.0640; the image is virtual and upright behind the surface."]], "34.9": [["Den konvexa spegeln har f = −17,0/2 = −8,50 cm.", "Bilden bakom spegeln har s′ = −6,50 cm.", "Spegelekvationen ger 1/s = 1/f−1/s′, alltså s ≈ 27,6 cm framför spegeln.", "Förstoringen är m = −s′/s ≈ +0,235.", "Bildhöjden är h′ = mh ≈ +0,353 cm; bilden är virtuell och upprätt."], ["The convex mirror has f = −17.0/2 = −8.50 cm.", "The image behind the mirror has s′ = −6.50 cm.", "The mirror equation gives 1/s = 1/f−1/s′, so s ≈ 27.6 cm in front of the mirror.", "Magnification is m = −s′/s ≈ +0.235.", "Image height is h′ = mh ≈ +0.353 cm; the image is virtual and upright."]], "34.10": [["Den konvexa skålytan har f = −30/2 = −15 cm.", "Med s = 85 cm ger spegelekvationen 1/s′ = 1/f−1/s.", "Det ger s′ = −12,75 cm, alltså en virtuell bild bakom ytan.", "Förstoringen är m = −s′/s = +0,150.", "För en 2,0 cm hög näsa är h′ = +0,30 cm och bilden är upprätt."], ["The convex bowl surface has f = −30/2 = −15 cm.", "With s = 85 cm the mirror equation gives 1/s′ = 1/f−1/s.", "This gives s′ = −12.75 cm, a virtual image behind the surface.", "Magnification is m = −s′/s = +0.150.", "For a 2.0 cm high nose h′ = +0.30 cm and the image is upright."]]};for(const e of root.EmberChapter34DraftExercises){const v=reviewed[e.id];if(v){e.sv.steps=v[0];e.en.steps=v[1]}}})(window);

(function(root){'use strict';const reviewed={"34.11": [["Den konkava spegeln har f = R/2 = +16,05 cm.", "Föremålet står innanför fokus eftersom s = 11,2 cm < f.", "Spegelekvationen ger s′ = [1/f−1/s]⁻¹ ≈ −37,1 cm.", "Förstoringen är m = −s′/s ≈ +3,31.", "Bilden är virtuell, upprätt och förstorad bakom spegeln; de reflekterade strålarnas bakåtförlängningar möts där."], ["The concave mirror has f = R/2 = +16.05 cm.", "The object is inside the focal length because s = 11.2 cm < f.", "The mirror equation gives s′ = [1/f−1/s]⁻¹ ≈ −37.1 cm.", "Magnification is m = −s′/s ≈ +3.31.", "The image is virtual, upright and enlarged behind the mirror; backward extensions of reflected rays meet there."]], "34.12": [["En verklig bild med samma höjdbelopp som ett verkligt föremål är inverterad.", "Därför är m = −1.", "Ur m = −s′/s följer s′ = s.", "Spegelekvationen blir 2/s = 1/f.", "Med f = 18,0 cm fås s = 2f = 36,0 cm framför spegeln."], ["A real image with the same height magnitude as a real object is inverted.", "Therefore m = −1.", "From m = −s′/s, s′ = s.", "The mirror equation becomes 2/s = 1/f.", "With f = 18.0 cm, s = 2f = 36.0 cm in front of the mirror."]], "34.13": [["En upprätt förstorad bild av ett verkligt föremål kräver här en konkav spegel med föremålet innanför fokus.", "Använd m = −s′/s = +2,00 och s = 1,25 cm.", "Då är s′ = −2,50 cm: bilden är virtuell bakom spegeln.", "Spegelekvationen ger 1/f = 1/1,25−1/2,50.", "Alltså f = +2,50 cm och R = 2f = +5,00 cm."], ["An upright enlarged image of a real object here requires a concave mirror with the object inside the focus.", "Use m = −s′/s = +2.00 and s = 1.25 cm.", "Then s′ = −2.50 cm: the image is virtual behind the mirror.", "The mirror equation gives 1/f = 1/1.25−1/2.50.", "Thus f = +2.50 cm and R = 2f = +5.00 cm."]], "34.14": [["En konvex spegel ger en upprätt bild av ett verkligt föremål.", "Bilden är hälften så hög, så m = +1/2.", "Ur m = −s′/s följer s′ = −s/2.", "Insättning i 1/s+1/s′ = 1/f ger −1/s = 1/(−12,0 cm).", "Föremålet ska stå s = 12,0 cm framför spegeln."], ["A convex mirror gives an upright image of a real object.", "The image is half as tall, so m = +1/2.", "From m = −s′/s, s′ = −s/2.", "Substitution into 1/s+1/s′ = 1/f gives −1/s = 1/(−12.0 cm).", "The object should be s = 12.0 cm in front of the mirror."]], "34.15": [["Figurens måttpil anger s = 15,0 cm till spegelns vertex; ordet ”center” kan annars förväxlas med krökningscentrum.", "För konkav sida är f = +6,00 cm och spegelekvationen ger s′ = +10,0 cm.", "Då h′ = −(10,0/15,0)3,30 = −2,20 mm: bilden är reell och inverterad.", "För konvex sida är f = −6,00 cm och s′ ≈ −4,29 cm.", "Då h′ = −(s′/s)h ≈ +0,943 mm: bilden är virtuell och upprätt."], ["The diagram’s dimension gives s = 15.0 cm to the mirror vertex; the word “center” could otherwise be confused with the center of curvature.", "For the concave side f = +6.00 cm and the mirror equation gives s′ = +10.0 cm.", "Then h′ = −(10.0/15.0)3.30 = −2.20 mm: the image is real and inverted.", "For the convex side f = −6.00 cm and s′ ≈ −4.29 cm.", "Then h′ = −(s′/s)h ≈ +0.943 mm: the image is virtual and upright."]], "34.16": [["Den inverterade bilden har h′ = −2,50 cm och föremålet h = +0,600 cm.", "Förstoringen är m = h′/h = −2,50/0,600.", "Eftersom m = −s′/s och s = 24,0 cm fås s′ = 100 cm.", "Spegelekvationen ger 1/f = 1/24,0+1/100 och f ≈ 19,35 cm.", "Krökningsradien är R = 2f ≈ 38,7 cm."], ["The inverted image has h′ = −2.50 cm and the object h = +0.600 cm.", "Magnification is m = h′/h = −2.50/0.600.", "Since m = −s′/s and s = 24.0 cm, s′ = 100 cm.", "The mirror equation gives 1/f = 1/24.0+1/100 and f ≈ 19.35 cm.", "The radius of curvature is R = 2f ≈ 38.7 cm."]], "34.17": [["Resultatet beror på skedens form och observationsavstånd.", "En vanlig konkav skedsida kan vid 25 cm ge en inverterad reell bild om ansiktet ligger utanför fokus; kontrollera den verkliga bilden.", "Den konvexa sidan ger en upprätt virtuell bild.", "Som exempel ger uppskattade höjder 20 cm och −2 cm förstoringen m ≈ −0,10 och med s ≈ 25 cm bildavståndet s′ ≈ 2,5 cm.", "Spegelekvationen ger f ≈ 2,27 cm och R = 2f ≈ 4,5 cm; använd egna mätningar för din sked."], ["The result depends on the spoon’s shape and observation distance.", "An ordinary concave side may give an inverted real image at 25 cm if the face is outside focus; check the actual image.", "The convex side gives an upright virtual image.", "For example, estimated heights 20 cm and −2 cm give m ≈ −0.10 and with s ≈ 25 cm the image distance s′ ≈ 2.5 cm.", "The mirror equation gives f ≈ 2.27 cm and R = 2f ≈ 4.5 cm; use your own measurements for your spoon."]], "34.18": [["För nästan normalt seende från luft är fiskens skenbara djup ungefär d/n.", "Det ger 7,5/1,333 ≈ 5,6 cm under vattenytan.", "Den plana bottenspegeln ger en virtuell fiskbild lika långt bakom spegeln som fisken är framför.", "Bildens geometriska djup under vattenytan är 2(20,2)−7,5 = 32,9 cm.", "Brytningen vid ytan ger spegelbildens skenbara djup 32,9/1,333 ≈ 24,7 cm."], ["For near-normal viewing from air the fish’s apparent depth is approximately d/n.", "This gives 7.5/1.333 ≈ 5.6 cm below the water surface.", "The plane bottom mirror produces a virtual fish image as far behind the mirror as the fish is in front.", "The image’s geometric depth below the water surface is 2(20.2)−7.5 = 32.9 cm.", "Refraction at the surface gives apparent depth 32.9/1.333 ≈ 24.7 cm for the mirror image."]], "34.19": [["För nära normalt seende från luft genom en plan yta är det skenbara djupet ungefär d/n.", "Det verkliga djupet är 3,90 cm och isens brytningsindex 1,309.", "Sätt in d_skenbar = 3,90/1,309 cm.", "Det ger cirka 2,98 cm.", "Partikeln ser alltså ut att ligga 2,98 cm under isytan i approximationen."], ["For near-normal viewing from air through a plane interface, apparent depth is approximately d/n.", "The actual depth is 3.90 cm and the ice refractive index is 1.309.", "Substitute d_apparent = 3.90/1.309 cm.", "This gives about 2.98 cm.", "The particle therefore appears 2.98 cm below the ice surface in this approximation."]], "34.20": [["Välj positivt R när krökningscentrum ligger på den utgående sidan.", "Den konkava ändens centrum ligger på luftsidan, så R = −15,0 cm.", "Inkommande strålar är parallella och 1/s = 0.", "Brytningsytans ekvation n₁/s+n₂/s′ = (n₂−n₁)/R ger 1,50/s′ = 0,50/(−15,0).", "Alltså s′ = −45,0 cm: bilden är virtuell och ligger på luftsidan om vertex."], ["Take R positive when the center of curvature lies on the outgoing side.", "The concave end’s center lies on the air side, so R = −15.0 cm.", "Incident rays are parallel and 1/s = 0.", "The refracting-surface equation n₁/s+n₂/s′ = (n₂−n₁)/R gives 1.50/s′ = 0.50/(−15.0).", "Thus s′ = −45.0 cm: the image is virtual and lies on the air side of the vertex."]]};for(const e of root.EmberChapter34DraftExercises){const v=reviewed[e.id];if(v){e.sv.steps=v[0];e.en.steps=v[1]}}})(window);

(function(root){'use strict';const reviewed={"34.21": [["Simmaren är 1,00 m under ytan och ser bilden 4,00 m ovanför sig.", "Bildens skenbara höjd över ytan är därför 4,00−1,00 = 3,00 m.", "För nästan normalt seende från vatten mot ett objekt i luft gäller h_skenbar = (n_vatten/n_luft)h_verklig.", "Med n_luft ≈ 1 fås h_verklig = 3,00/1,333.", "Den verkliga höjden är cirka 2,25 m över ytan."], ["The swimmer is 1.00 m below the surface and sees the image 4.00 m above.", "The apparent image height above the surface is therefore 4.00−1.00 = 3.00 m.", "For near-normal viewing from water toward an object in air, h_apparent = (n_water/n_air)h_actual.", "With n_air ≈ 1, solve h_actual = 3.00/1.333.", "The actual height is about 2.25 m above the surface."]], "34.22": [["Observatören är 3,00 m ovanför ytan och det totala skenbara avståndet är 7,00 m.", "Myntets skenbara djup under ytan är därför 7,00−3,00 = 4,00 m.", "Vid nära normalt seende från luft är d_skenbar ≈ d_verklig/n.", "Lös d_verklig ≈ n d_skenbar.", "Med n = 1,333 är vattendjupet cirka 5,33 m."], ["The observer is 3.00 m above the surface and total apparent distance is 7.00 m.", "The coin’s apparent depth below the surface is therefore 7.00−3.00 = 4.00 m.", "For near-normal viewing from air, d_apparent ≈ d_actual/n.", "Solve d_actual ≈ n d_apparent.", "With n = 1.333 the water depth is about 5.33 m."]], "34.23": [["För den utgående vatten–luft-ytan är s = 14,0 cm, R = −14,0 cm, n₁ = 1,333 och n₂ = 1,00.", "Ytekvationen ger s′ = −14,0 cm: bildpunkten ligger i centrum.", "Tvärförstoringen är m = −n₁s′/(n₂s) ≈ +1,333.", "För parallella solstrålar ger första ytan en mellanbild cirka 56,0 cm från första vertex, cirka 28,0 cm bortom andra ytan.", "Mellanbilden är ett virtuellt föremål för andra ytan, som ger ett paraxiellt fokus cirka 14,0 cm utanför skålen; fokus ligger inte inuti vattnet."], ["For the outgoing water–air surface s = 14.0 cm, R = −14.0 cm, n₁ = 1.333 and n₂ = 1.00.", "The surface equation gives s′ = −14.0 cm: the image point is at the center.", "Transverse magnification is m = −n₁s′/(n₂s) ≈ +1.333.", "For parallel sunlight the first surface gives an intermediate image about 56.0 cm from the first vertex, about 28.0 cm beyond the second surface.", "That is a virtual object for the second surface, which gives a paraxial focus about 14.0 cm outside the bowl; the focus is not inside the water."]], "34.24": [["För den konvexa luft–glas-ytan är n₁ = 1,00, n₂ = 1,60 och R = +3,00 cm.", "Ytekvationen blir 1/s+1,60/s′ = 0,60/3,00.", "För s = ∞ fås s′ = +8,00 cm.", "För s = 12,0 cm fås s′ ≈ +13,7 cm; båda dessa bilder är reella i glaset.", "För s = 2,00 cm fås s′ ≈ −5,33 cm, en virtuell bild på luftsidan."], ["For the convex air–glass surface n₁ = 1.00, n₂ = 1.60 and R = +3.00 cm.", "The surface equation becomes 1/s+1.60/s′ = 0.60/3.00.", "For s = ∞, s′ = +8.00 cm.", "For s = 12.0 cm, s′ ≈ +13.7 cm; both images are real in the glass.", "For s = 2.00 cm, s′ ≈ −5.33 cm, a virtual image on the air side."]], "34.25": [["Använd centimeter: R = +3,00 cm och s′ = +1,20 m = 120 cm.", "Det inkommande mediet har n₁ = 1,45 och glaset n₂ = 1,60.", "Ytekvationen ger 1,45/s+1,60/120 = (1,60−1,45)/3,00.", "Lös s = 1,45/[0,0500−1,60/120].", "Föremålet ska placeras cirka 39,5 cm framför vertex i oljan."], ["Use centimeters: R = +3.00 cm and s′ = +1.20 m = 120 cm.", "The incoming medium has n₁ = 1.45 and the glass n₂ = 1.60.", "The surface equation gives 1.45/s+1.60/120 = (1.60−1.45)/3.00.", "Solve s = 1.45/[0.0500−1.60/120].", "The object should be about 39.5 cm in front of the vertex in oil."]], "34.26": [["För den konvexa luft–glas-ytan är R = +4,00 cm, n₁ = 1,00 och n₂ = 1,60.", "Ytekvationen är 1/24,0+1,60/s′ = 0,60/4,00.", "Därmed s′ ≈ +14,8 cm i glaset.", "Tvärförstoringen är m = −n₁s′/(n₂s) ≈ −0,385.", "Med h = 1,50 mm är h′ ≈ −0,577 mm; bilden är reell och inverterad."], ["For the convex air–glass surface R = +4.00 cm, n₁ = 1.00 and n₂ = 1.60.", "The surface equation is 1/24.0+1.60/s′ = 0.60/4.00.", "Thus s′ ≈ +14.8 cm in the glass.", "Transverse magnification is m = −n₁s′/(n₂s) ≈ −0.385.", "With h = 1.50 mm, h′ ≈ −0.577 mm; the image is real and inverted."]], "34.27": [["En reell bild har s′ = +60,0 cm och s = 20,0 cm.", "Spegelekvationen ger f = +15,0 cm och R = +30,0 cm.", "Förstoringen m = −3,00 ger h′ = −9,60 mm, en inverterad bild.", "För en virtuell bild är s′ = −60,0 cm; då fås f = +30,0 cm och R = +60,0 cm.", "Nu är m = +3,00 och h′ = +9,60 mm: bilden är upprätt."], ["A real image has s′ = +60.0 cm and s = 20.0 cm.", "The mirror equation gives f = +15.0 cm and R = +30.0 cm.", "Magnification m = −3.00 gives h′ = −9.60 mm, an inverted image.", "For a virtual image s′ = −60.0 cm; then f = +30.0 cm and R = +60.0 cm.", "Now m = +3.00 and h′ = +9.60 mm: the image is upright."]], "34.28": [["För en reell bild av ett verkligt föremål är m = −s′/s.", "Linsekvationen ger s′ = fs/(s−f), och därmed |h′| = hf/(s−f).", "Invertera: 1/|h′| = s/(hf)−1/h.", "Grafens lutning är alltså 1/(hf); h = 4,00 mm = 0,400 cm.", "Med lutningen 0,208 cm⁻² fås f = 1/(0,400·0,208) ≈ 12,0 cm. Positiv lutning förutsätter bildhöjdens belopp."], ["For a real image of a real object m = −s′/s.", "The lens equation gives s′ = fs/(s−f), so |h′| = hf/(s−f).", "Invert: 1/|h′| = s/(hf)−1/h.", "The graph slope is therefore 1/(hf); h = 4.00 mm = 0.400 cm.", "With slope 0.208 cm⁻², f = 1/(0.400·0.208) ≈ 12.0 cm. Positive slope assumes image-height magnitude."]], "34.29": [["Linsmakarens formel för den tunna plankonvexa linsen ger f = R/(n−1) = 12,9/0,70 ≈ 18,43 cm.", "Linsekvationen ger s′ = [1/f−1/25,0]⁻¹ ≈ +70,1 cm.", "Förstoringen är m = −s′/s ≈ −2,80.", "Bildhöjden är h′ = mh ≈ −10,5 mm: bilden är reell och inverterad.", "Om linsen vänds i samma medium är den tunna linsens brännvidd oförändrad, så samma bildläge och höjd gäller."], ["The lensmaker equation for the thin plano-convex lens gives f = R/(n−1) = 12.9/0.70 ≈ 18.43 cm.", "The lens equation gives s′ = [1/f−1/25.0]⁻¹ ≈ +70.1 cm.", "Magnification is m = −s′/s ≈ −2.80.", "Image height is h′ = mh ≈ −10.5 mm: the image is real and inverted.", "Reversing the thin lens in the same medium leaves its focal length unchanged, so the same image position and height apply."]], "34.30": [["Bilden ligger på föremålssidan: s = +16,0 cm och s′ = −12,0 cm.", "Linsekvationen ger 1/f = 1/16,0−1/12,0 = −1/48,0 cm⁻¹.", "Alltså f = −48,0 cm och linsen är spridande.", "Förstoringen är m = −s′/s = +0,750 och h′ = +6,38 mm: bilden är virtuell och upprätt.", "En parallell stråle bryts ut som om den kom från fokus; dess bakåtförlängning och centralstrålen möts vid bilden."], ["The image is on the object side: s = +16.0 cm and s′ = −12.0 cm.", "The lens equation gives 1/f = 1/16.0−1/12.0 = −1/48.0 cm⁻¹.", "Thus f = −48.0 cm and the lens is diverging.", "Magnification is m = −s′/s = +0.750 and h′ = +6.38 mm: the image is virtual and upright.", "A parallel ray emerges as if from the focus; its backward extension and the central ray meet at the image."]]};for(const e of root.EmberChapter34DraftExercises){const v=reviewed[e.id];if(v){e.sv.steps=v[0];e.en.steps=v[1]}}})(window);

(function(root){'use strict';const reviewed={"34.31": [["Menisklinsen är samlande; använd skillnaden mellan yteffekternas belopp i linsmakarens formel.", "1/f = (1,52−1)(1/4,00−1/7,00) cm⁻¹ ger f ≈ +17,95 cm.", "Med s = 24,0 cm ger linsekvationen s′ = [1/f−1/s]⁻¹ ≈ +71,2 cm.", "Förstoringen är m = −s′/s ≈ −2,97.", "Bilden är reell och inverterad."], ["The meniscus lens is converging; use the difference of the surface-power magnitudes in the lensmaker equation.", "1/f = (1.52−1)(1/4.00−1/7.00) cm⁻¹ gives f ≈ +17.95 cm.", "With s = 24.0 cm the lens equation gives s′ = [1/f−1/s]⁻¹ ≈ +71.2 cm.", "Magnification is m = −s′/s ≈ −2.97.", "The image is real and inverted."]], "34.32": [["Den inverterade bildens förstoring är m = −4,50/3,20 = −1,40625.", "Eftersom m = −s′/s är s′ = 1,40625s.", "Insättning i 1/f = 1/s+1/s′ ger s = f(1+1/1,40625).", "Med f = 70,0 cm fås s ≈ 120 cm.", "Bildavståndet är s′ ≈ +168 cm på andra sidan linsen; bilden är reell."], ["The inverted image magnification is m = −4.50/3.20 = −1.40625.", "Since m = −s′/s, s′ = 1.40625s.", "Substitution into 1/f = 1/s+1/s′ gives s = f(1+1/1.40625).", "With f = 70.0 cm, s ≈ 120 cm.", "The image distance is s′ ≈ +168 cm on the other side of the lens; the image is real."]], "34.33": [["Föremålshöjden 7,50 mm är 0,750 cm.", "Den upprätta bilden ger m = +3,30/0,750 = +4,40.", "Bilden är på föremålssidan, så s′ = −12,5 cm och m = −s′/s ger s ≈ 2,84 cm.", "Linsekvationen ger f = [1/2,84−1/12,5]⁻¹ ≈ +3,68 cm.", "Bilden är virtuell och linsen är samlande."], ["The object height 7.50 mm is 0.750 cm.", "The upright image gives m = +3.30/0.750 = +4.40.", "The image is on the object side, so s′ = −12.5 cm and m = −s′/s gives s ≈ 2.84 cm.", "The lens equation gives f = [1/2.84−1/12.5]⁻¹ ≈ +3.68 cm.", "The image is virtual and the lens converging."]], "34.34": [["En reell bild på väggen ger s+s′ = 610 cm.", "Förstoringens belopp ger s′/s = 75,0.", "Därför s = 610/76,0 ≈ 8,03 cm och s′ ≈ 602 cm.", "Tecknad förstoring m = −75,0 innebär en inverterad bild.", "Brännvidden är f = ss′/(s+s′) ≈ +7,92 cm; linsen är samlande."], ["A real image on the wall gives s+s′ = 610 cm.", "The magnification magnitude gives s′/s = 75.0.", "Therefore s = 610/76.0 ≈ 8.03 cm and s′ ≈ 602 cm.", "Signed magnification m = −75.0 means the image is inverted.", "The focal length is f = ss′/(s+s′) ≈ +7.92 cm; the lens is converging."]], "34.35": [["För ett mycket avlägset träd är bildavståndet ungefär brännvidden f ≈ 1,89 cm.", "För en tunn dubbelkonvex lins med lika radier gäller 1/f = 2(n−1)/R.", "Lös n = 1+R/(2f).", "Använd R = 3,00 cm och f = 1,89 cm.", "Det ger n ≈ 1,79."], ["For a very distant tree the image distance is approximately focal length f ≈ 1.89 cm.", "For a thin biconvex lens with equal radii 1/f = 2(n−1)/R.", "Solve n = 1+R/(2f).", "Use R = 3.00 cm and f = 1.89 cm.", "This gives n ≈ 1.79."]], "34.36": [["Omvandla bildhöjden 1,70 cm till 17,0 mm.", "Den upprätta bilden har m = +17,0/3,20 = +5,3125.", "Ur m = −s′/s följer s′ = −ms.", "Linsekvationen ger s = f(1−1/m) ≈ 5,68 cm.", "Därmed s′ ≈ −30,2 cm; bilden är virtuell och ligger på föremålssidan."], ["Convert image height 1.70 cm to 17.0 mm.", "The upright image has m = +17.0/3.20 = +5.3125.", "From m = −s′/s, s′ = −ms.", "The lens equation gives s = f(1−1/m) ≈ 5.68 cm.", "Thus s′ ≈ −30.2 cm; the image is virtual and on the object side."]], "34.37": [["Linsmakarens formel ger f = R/(n−1) = 20,0/0,50 = +40,0 cm.", "Med s = 20,0 cm ger linsekvationen s′ = [1/40,0−1/20,0]⁻¹.", "Bildavståndet är s′ = −40,0 cm.", "Förstoringen är m = −s′/s = +2,00.", "Bildhöjden är h′ = mh = +12,0 mm; bilden är virtuell och upprätt."], ["The lensmaker equation gives f = R/(n−1) = 20.0/0.50 = +40.0 cm.", "With s = 20.0 cm the lens equation gives s′ = [1/40.0−1/20.0]⁻¹.", "The image distance is s′ = −40.0 cm.", "Magnification is m = −s′/s = +2.00.", "Image height is h′ = mh = +12.0 mm; the image is virtual and upright."]], "34.38": [["För en tunn dubbelkonvex lins i luft med lika radier gäller 1/f = 2(n−1)/R.", "Brytningsindex är n = 1,55 och brännvidden f = 20,0 cm.", "Lös R = 2(n−1)f.", "Insättning ger R = 2(0,55)(20,0 cm).", "Radiernas gemensamma belopp är 22,0 cm."], ["For a thin biconvex lens in air with equal radii 1/f = 2(n−1)/R.", "The refractive index is n = 1.55 and focal length f = 20.0 cm.", "Solve R = 2(n−1)f.", "Substitution gives R = 2(0.55)(20.0 cm).", "The common radius magnitude is 22.0 cm."]], "34.39": [["Föremålet är reellt och bilden på samma sida är virtuell: s = +12,0 cm och s′ = −8,00 cm.", "Linsekvationen ger f = [1/12,0−1/8,00]⁻¹ = −24,0 cm.", "För en tunn plankonkav lins i luft är |f| = R/(n−1).", "Därmed R = (n−1)|f| = 0,50·24,0 cm.", "Radiebeloppet är 12,0 cm."], ["The object is real and the image on the same side is virtual: s = +12.0 cm and s′ = −8.00 cm.", "The lens equation gives f = [1/12.0−1/8.00]⁻¹ = −24.0 cm.", "For a thin plano-concave lens in air |f| = R/(n−1).", "Thus R = (n−1)|f| = 0.50·24.0 cm.", "The radius magnitude is 12.0 cm."]], "34.40": [["Den virtuella bilden ligger på samma sida som det verkliga föremålet; ljuset går här från höger till vänster och s′ = −17,0 cm.", "Med f = +12,0 cm ger linsekvationen 1/s = 1/f−1/s′ = 1/12,0+1/17,0.", "Det ger s ≈ 7,03 cm till höger om linsen.", "Förstoringen är m = −s′/s ≈ +2,42, så föremålets höjd är 8,00/2,42 ≈ 3,31 mm.", "Bilden är upprätt och virtuell; brutna strålars bakåtförlängningar möts vid bildpunkten."], ["The virtual image is on the same side as the real object; light here travels from right to left and s′ = −17.0 cm.", "With f = +12.0 cm the lens equation gives 1/s = 1/f−1/s′ = 1/12.0+1/17.0.", "This gives s ≈ 7.03 cm to the right of the lens.", "Magnification is m = −s′/s ≈ +2.42, so object height is 8.00/2.42 ≈ 3.31 mm.", "The image is upright and virtual; backward extensions of refracted rays meet at the image point."]]};for(const e of root.EmberChapter34DraftExercises){const v=reviewed[e.id];if(v){e.sv.steps=v[0];e.en.steps=v[1]}}})(window);
(function(root){'use strict';const e=root.EmberChapter34DraftExercises.find(x=>x.id==='34.49');e.sv.steps=['Använd mm: f = 85 mm och s = 3900 mm. Linsekvationen ger s′ = [1/85−1/3900]⁻¹ ≈ 86,9 mm.','Bildhöjdens belopp är |h′| = (s′/s)h = (86,9/3900)(1750 mm) ≈ 39,0 mm.','Med personen parallell med en av sensorns sidor ryms höjden inte: det största sidmåttet är 36 mm.','Sensorns diagonal är √(24²+36²) ≈ 43,3 mm. En snett orienterad mycket smal bild kan därför rymma en sträcka på 39,0 mm.','Om hela den faktiska personen ryms vid sned orientering beror även på personens bredd och inramningen; de uppgifterna anges inte.'];e.en.steps=['Use mm: f = 85 mm and s = 3900 mm. The lens equation gives s′ = [1/85−1/3900]⁻¹ ≈ 86.9 mm.','The image-height magnitude is |h′| = (s′/s)h = (86.9/3900)(1750 mm) ≈ 39.0 mm.','With the person aligned with a sensor side, the height does not fit: the largest side is 36 mm.','The sensor diagonal is √(24²+36²) ≈ 43.3 mm. A very narrow tilted image can therefore fit a 39.0 mm segment.','Whether the entire actual person fits when tilted also depends on the person’s width and framing, which are not given.'];})(window);

(function(root){'use strict';const reviewed={"34.41": [["Använd samma ljusriktning från höger och det virtuella bildavståndet s′ = −17,0 cm.", "Nu är linsen spridande med f = −48,0 cm.", "Linsekvationen ger 1/s = −1/48,0+1/17,0 och s ≈ 26,3 cm till höger.", "Förstoringen är m = −s′/s ≈ +0,646; föremålets höjd blir 8,00/0,646 ≈ 12,4 mm.", "Bilden är upprätt och virtuell; strålarnas bakåtförlängningar möts på föremålets sida."], ["Use the same right-to-left light direction and virtual image distance s′ = −17.0 cm.", "The lens is now diverging with f = −48.0 cm.", "The lens equation gives 1/s = −1/48.0+1/17.0 and s ≈ 26.3 cm to the right.", "Magnification is m = −s′/s ≈ +0.646, so object height is 8.00/0.646 ≈ 12.4 mm.", "The image is upright and virtual; backward ray extensions meet on the object side."]], "34.42": [["Föremålet är reellt med s = +16,0 cm och bilden reell med s′ = +36,0 cm.", "Linsekvationen ger f = [1/16,0+1/36,0]⁻¹ ≈ +11,1 cm.", "Positiv brännvidd visar att linsen är samlande.", "Förstoringen är m = −36,0/16,0 = −2,25 och h′ = mh = −18,0 mm.", "Bilden är inverterad; en parallell stråle bryts genom fokus och möter centralstrålen vid bilden."], ["The object is real with s = +16.0 cm and the image real with s′ = +36.0 cm.", "The lens equation gives f = [1/16.0+1/36.0]⁻¹ ≈ +11.1 cm.", "Positive focal length identifies a converging lens.", "Magnification is m = −36.0/16.0 = −2.25 and h′ = mh = −18.0 mm.", "The image is inverted; a parallel ray refracts through the focus and meets the central ray at the image."]], "34.43": [["För första linsen ger s₁ = 50,0 cm och f₁ = 40,0 cm s₁′ = +200 cm.", "Förstoringen är m₁ = −200/50,0 = −4,00 och mellanbildens höjd h₁′ = −4,80 cm.", "Lins 2 ligger 300 cm från lins 1, så mellanbilden ligger 100 cm framför lins 2.", "Med s₂ = +100 cm och f₂ = +60,0 cm fås s₂′ = +150 cm och m₂ = −1,50.", "Slutbilden ligger 450 cm till höger om första linsen och h₂′ = (−1,50)(−4,80) = +7,20 cm."], ["For lens 1, s₁ = 50.0 cm and f₁ = 40.0 cm give s₁′ = +200 cm.", "Magnification is m₁ = −200/50.0 = −4.00 and intermediate height h₁′ = −4.80 cm.", "Lens 2 is 300 cm from lens 1, so the intermediate image is 100 cm in front of lens 2.", "With s₂ = +100 cm and f₂ = +60.0 cm, s₂′ = +150 cm and m₂ = −1.50.", "The final image lies 450 cm right of lens 1 and h₂′ = (−1.50)(−4.80) = +7.20 cm."]], "34.44": [["Mät x från första linsen åt höger och använd s₂ = 300−x₁ för varje fall.", "(a) f₁ = +40,0 cm ger x₁ = +200 cm och h₁′ = −4,80 cm.", "Med f₂ = −60,0 cm och s₂ = 100 cm fås s₂′ = −37,5 cm, x₂ = 262,5 cm och h₂′ = −1,80 cm.", "(b) f₁ = −40,0 cm ger x₁ = −22,2 cm och h₁′ = +0,533 cm; med f₂ = +60,0 cm fås x₂ ≈ 373,7 cm och h₂′ ≈ −0,122 cm.", "(c) Med samma mellanbild men f₂ = −60,0 cm fås s₂′ ≈ −50,6 cm, x₂ ≈ 249,4 cm och h₂′ ≈ +0,0837 cm."], ["Measure x rightward from lens 1 and use s₂ = 300−x₁ in each case.", "(a) f₁ = +40.0 cm gives x₁ = +200 cm and h₁′ = −4.80 cm.", "With f₂ = −60.0 cm and s₂ = 100 cm, s₂′ = −37.5 cm, x₂ = 262.5 cm and h₂′ = −1.80 cm.", "(b) f₁ = −40.0 cm gives x₁ = −22.2 cm and h₁′ = +0.533 cm; with f₂ = +60.0 cm, x₂ ≈ 373.7 cm and h₂′ ≈ −0.122 cm.", "(c) With the same intermediate image but f₂ = −60.0 cm, s₂′ ≈ −50.6 cm, x₂ ≈ 249.4 cm and h₂′ ≈ +0.0837 cm."]], "34.45": [["För lins 1 ger f₁ = −12,0 cm och s₁ = 20,0 cm mellanbilden s₁′ = −7,50 cm.", "Förstoringen i lins 1 är m₁ = +0,375.", "Mellanbilden ligger 9,00+7,50 = 16,5 cm framför lins 2.", "Med f₂ = +12,0 cm fås s₂′ = +44,0 cm och m₂ = −44,0/16,5.", "Slutbilden ligger 53,0 cm till höger om lins 1 och h′ = m₁m₂h = −2,50 mm; den är reell och inverterad."], ["For lens 1, f₁ = −12.0 cm and s₁ = 20.0 cm give intermediate image s₁′ = −7.50 cm.", "Lens 1 magnification is m₁ = +0.375.", "The intermediate image is 9.00+7.50 = 16.5 cm in front of lens 2.", "With f₂ = +12.0 cm, s₂′ = +44.0 cm and m₂ = −44.0/16.5.", "The final image is 53.0 cm right of lens 1 and h′ = m₁m₂h = −2.50 mm; it is real and inverted."]], "34.46": [["En spridningslins med verkligt föremål ger en virtuell bild på föremålssidan.", "Därför f = −25,0 cm och s′ = −18,0 cm.", "Linsekvationen ger 1/s = 1/f−1/s′.", "Det ger s ≈ 64,3 cm till vänster om linsen.", "m = −s′/s ≈ +0,280: bilden är upprätt och mindre än föremålet."], ["A diverging lens with a real object gives a virtual image on the object side.", "Therefore f = −25.0 cm and s′ = −18.0 cm.", "The lens equation gives 1/s = 1/f−1/s′.", "This gives s ≈ 64.3 cm to the left of the lens.", "m = −s′/s ≈ +0.280: the image is upright and smaller than the object."]], "34.47": [["Föremålsavståndet är s = 2f/3.", "Linsekvationen ger 1/s′ = 1/f−3/(2f) = −1/(2f).", "Alltså s′ = −2f och bilden är virtuell på föremålssidan.", "Förstoringen är m = −s′/s = +3.", "Bildhöjden är h′ = +3h: bilden är upprätt och tre gånger så hög."], ["The object distance is s = 2f/3.", "The lens equation gives 1/s′ = 1/f−3/(2f) = −1/(2f).", "Thus s′ = −2f and the image is virtual on the object side.", "Magnification is m = −s′/s = +3.", "Image height is h′ = +3h: the image is upright and three times as tall."]], "34.48": [["En reell skärmbild från ett verkligt föremål är inverterad.", "Förstoringsbeloppet ger s′/s = 2,50.", "Avståndet mellan föremål och skärm ger s+s′ = 2,60 m.", "Därför s = 2,60/3,50 ≈ 0,743 m och s′ ≈ 1,86 m.", "Brännvidden är f = ss′/(s+s′) ≈ +0,531 m; linsen är samlande."], ["A real screen image of a real object is inverted.", "The magnification magnitude gives s′/s = 2.50.", "Object–screen separation gives s+s′ = 2.60 m.", "Therefore s = 2.60/3.50 ≈ 0.743 m and s′ ≈ 1.86 m.", "The focal length is f = ss′/(s+s′) ≈ +0.531 m; the lens is converging."]], "34.50": [["Använd s = 0,150 m och s′ = 9,00 m.", "Linsekvationen ger f = [1/0,150+1/9,00]⁻¹ ≈ 0,1475 m = 14,8 cm.", "Förstoringsbeloppet är |m| = s′/s = 60,0.", "Bildens mått är 60,0·24 mm × 60,0·36 mm = 1,44 m × 2,16 m.", "Detta är de minsta skärmmåtten för bilden; bilden är inverterad."], ["Use s = 0.150 m and s′ = 9.00 m.", "The lens equation gives f = [1/0.150+1/9.00]⁻¹ ≈ 0.1475 m = 14.8 cm.", "The magnification magnitude is |m| = s′/s = 60.0.", "The image dimensions are 60.0·24 mm × 60.0·36 mm = 1.44 m × 2.16 m.", "These are the minimum screen dimensions for the image; the image is inverted."]]};for(const e of root.EmberChapter34DraftExercises){const v=reviewed[e.id];if(v){e.sv.steps=v[0];e.en.steps=v[1]}}})(window);

(function(root){'use strict';const reviewed={"34.51": [["För ett avlägset föremål skulle lins 1 ensam bilda en bild 12 cm till höger om sig.", "Vid linsavstånd 4 cm ligger punkten 8 cm bortom lins 2 och är ett virtuellt föremål: s₂ = −8 cm.", "Med f₂ = −12 cm ger linsekvationen s₂′ = +24 cm; slutbilden ligger x = 4+24 = 28 cm från lins 1.", "Vid linsavstånd 8 cm är i stället s₂ = −4 cm.", "Då s₂′ = +6 cm och slutbilden ligger x = 8+6 = 14 cm från lins 1."], ["For a distant object lens 1 alone would form an image 12 cm to its right.", "At lens separation 4 cm this point is 8 cm beyond lens 2 and is a virtual object: s₂ = −8 cm.", "With f₂ = −12 cm the lens equation gives s₂′ = +24 cm; the final image lies x = 4+24 = 28 cm from lens 1.", "At separation 8 cm, instead s₂ = −4 cm.", "Then s₂′ = +6 cm and the final image is x = 8+6 = 14 cm from lens 1."]], "34.52": [["Brytning vid en sfärisk yta uppfyller n₁/s+n₂/s′ = (n₂−n₁)/R.", "Här är n₁ = 1,00 och n₂ = 1,40.", "Föremålsavståndet är s = 40,0 cm och näthinnans bildavstånd s′ = 2,60 cm.", "Lös R = 0,40/[1/40,0+1,40/2,60] ≈ +0,710 cm.", "Positivt R betyder att krökningscentrum ligger inne i ögat."], ["Refraction at a spherical surface satisfies n₁/s+n₂/s′ = (n₂−n₁)/R.", "Here n₁ = 1.00 and n₂ = 1.40.", "Object distance is s = 40.0 cm and retinal image distance s′ = 2.60 cm.", "Solve R = 0.40/[1/40.0+1.40/2.60] ≈ +0.710 cm.", "Positive R means the center of curvature lies inside the eye."]], "34.53": [["För kontaktlinsen +2,95 D ska ett föremål vid 0,250 m ge en virtuell bild vid ögats okorrigerade närpunkt N.", "Med meter ger linsekvationen P = 1/0,250−1/N.", "Därför N = 1/(4,00−2,95) ≈ 0,952 m.", "För −1,60 D och ett avlägset föremål är bildavståndet s′ = f = 1/P = −0,625 m.", "Fjärrpunkten ligger därför 0,625 m framför ögat."], ["For the +2.95 D contact lens an object at 0.250 m must form a virtual image at the uncorrected near point N.", "Using meters the lens equation gives P = 1/0.250−1/N.", "Therefore N = 1/(4.00−2.95) ≈ 0.952 m.", "For −1.60 D and a distant object, image distance s′ = f = 1/P = −0.625 m.", "The far point is therefore 0.625 m in front of the eye."]], "34.54": [["En närpunkt längre bort än normalt medan avlägsna föremål syns tydligt motsvarar översynthet i modellen.", "Kontaktlinsen ska avbilda ett föremål vid s = +0,250 m virtuellt vid s′ = −0,450 m.", "Styrkan är P = 1/s+1/s′ = 4,00−2,22 ≈ +1,78 D.", "Brännvidden är f = 1/P ≈ +0,563 m.", "Positiv styrka betyder att en samlingslins behövs."], ["A near point farther away than normal while distant objects are seen clearly corresponds to farsightedness in the model.", "The contact lens must image an object at s = +0.250 m virtually at s′ = −0.450 m.", "Power is P = 1/s+1/s′ = 4.00−2.22 ≈ +1.78 D.", "Focal length is f = 1/P ≈ +0.563 m.", "Positive power means a converging lens is needed."]], "34.55": [["Glasögonen sitter 0,020 m framför ögat.", "Föremålet 0,250 m från ögat ligger därför s = +0,230 m från linsen.", "Den virtuella bilden ska ligga i närpunkten 0,450 m från ögat, alltså s′ = −0,430 m från linsen.", "Styrkan är P = 1/0,230−1/0,430 ≈ +2,02 D.", "Brännvidden är f = 1/P ≈ +0,495 m."], ["The glasses are 0.020 m in front of the eye.", "The object 0.250 m from the eye is therefore s = +0.230 m from the lens.", "The virtual image must lie at the near point 0.450 m from the eye, so s′ = −0.430 m from the lens.", "Power is P = 1/0.230−1/0.430 ≈ +2.02 D.", "Focal length is f = 1/P ≈ +0.495 m."]], "34.56": [["Personen är närsynt eftersom fjärrpunkten är 0,750 m.", "En kontaktlins ska avbilda ett avlägset föremål virtuellt vid fjärrpunkten.", "För ett föremål i oändligheten är s′ = f = −0,750 m.", "Styrkan blir P = 1/f ≈ −1,33 D.", "Negativ styrka innebär en spridningslins."], ["The person is nearsighted because the far point is 0.750 m.", "A contact lens must image a distant object virtually at that far point.", "For an object at infinity s′ = f = −0.750 m.", "The power is P = 1/f ≈ −1.33 D.", "Negative power indicates a diverging lens."]], "34.57": [["Överdelens styrka −0,500 D ger f = −2,00 m.", "Ett avlägset föremål avbildas därmed i ögats fjärrpunkt: 2,00+0,020 = 2,02 m framför ögat.", "För underdelen är s = 0,250−0,020 = 0,230 m och 1/s′ = 2,00−1/0,230, vilket ger s′ ≈ −0,426 m.", "Närpunkten är 0,426+0,020 ≈ 0,446 m framför ögat.", "Genom överdelen ska närmaste skarpa föremål ge samma virtuella bild: 1/s = −0,500+1/0,426, så avståndet är cirka 0,541 m från linsen eller 0,561 m från ögat."], ["The upper section power −0.500 D gives f = −2.00 m.", "A distant object is imaged at the eye’s far point: 2.00+0.020 = 2.02 m in front of the eye.", "For the lower section s = 0.250−0.020 = 0.230 m and 1/s′ = 2.00−1/0.230, giving s′ ≈ −0.426 m.", "The near point is 0.426+0.020 ≈ 0.446 m in front of the eye.", "Through the upper section the nearest clear object must give the same virtual image: 1/s = −0.500+1/0.426, so the distance is about 0.541 m from the lens or 0.561 m from the eye."]], "34.58": [["När föremålet ligger i fokus är slutbilden vid oändligheten.", "Med luppen nära ögat ger småvinkelmodellen M = N/f.", "Med N = 25,0 cm och f = 6,00 cm är M ≈ 4,17.", "För bild i närpunkten är s′ = −25,0 cm och linsekvationen ger 1/s = 1/6,00+1/25,0.", "Minsta föremålsavståndet blir s ≈ 4,84 cm."], ["When the object is at the focus, the final image is at infinity.", "With the magnifier close to the eye, the small-angle model gives M = N/f.", "With N = 25.0 cm and f = 6.00 cm, M ≈ 4.17.", "For the image at the near point s′ = −25.0 cm and the lens equation gives 1/s = 1/6.00+1/25.0.", "The minimum object distance is s ≈ 4.84 cm."]], "34.59": [["Närpunktsbilden är virtuell med s′ = −25,0 cm.", "Med f = +6,00 cm ger linsekvationen s = [1/6,00+1/25,0]⁻¹ ≈ 4,84 cm.", "Förstoringen är m = −s′/s ≈ +5,17.", "Med h = 4,50 mm fås h′ = mh ≈ +23,3 mm.", "Positiv bildhöjd betyder en upprätt bild."], ["The near-point image is virtual with s′ = −25.0 cm.", "With f = +6.00 cm the lens equation gives s = [1/6.00+1/25.0]⁻¹ ≈ 4.84 cm.", "Magnification is m = −s′/s ≈ +5.17.", "With h = 4.50 mm, h′ = mh ≈ +23.3 mm.", "Positive image height means an upright image."]], "34.60": [["När insekten ligger i luppens fokus lämnar strålarna linsen parallellt.", "För små vinklar är den skenbara vinkelstorleken θ ≈ h/f.", "Lös f ≈ h/θ.", "Med h = 2,10 mm och θ = 0,026 rad fås f ≈ 80,8 mm.", "Den exakta tangentrelationen ger praktiskt taget samma värde vid denna lilla vinkel."], ["When the insect is at the magnifier focus, rays leave the lens parallel.", "For small angles apparent angular size is θ ≈ h/f.", "Solve f ≈ h/θ.", "With h = 2.10 mm and θ = 0.026 rad, f ≈ 80.8 mm.", "The exact tangent relation gives practically the same value at this small angle."]]};for(const e of root.EmberChapter34DraftExercises){const v=reviewed[e.id];if(v){e.sv.steps=v[0];e.en.steps=v[1]}}})(window);

(function(root){'use strict';const reviewed={"34.61": [["För teleskop med slutbild i oändligheten är M = −f_obj/f_ok = −95,0/15,0 ≈ −6,33.", "Minustecknet anger inversion.", "Byggnadens vinkel är ungefär θ = 60,0/3000 = 0,0200 rad.", "Objektivets mellanbild har höjden h′ ≈ −f_objθ = −0,950·0,0200 ≈ −0,0190 m.", "Slutbildens vinkelstorlek är |M|θ ≈ 6,33·0,0200 ≈ 0,127 rad."], ["For a telescope with final image at infinity M = −f_obj/f_eye = −95.0/15.0 ≈ −6.33.", "The minus sign indicates inversion.", "The building’s angular size is approximately θ = 60.0/3000 = 0.0200 rad.", "The objective’s intermediate image height is h′ ≈ −f_objθ = −0.950·0.0200 ≈ −0.0190 m.", "The final image angular size is |M|θ ≈ 6.33·0.0200 ≈ 0.127 rad."]], "34.62": [["För avlägset föremål och slutbild i oändligheten är linsavståndet f_obj+f_ok.", "Linsavståndet är 1,20 m = 120 cm och okularets brännvidd 9,00 cm.", "Därför f_obj = 120−9,00 = 111 cm.", "Vinkelförstoringen är M = −f_obj/f_ok = −111/9,00 ≈ −12,3.", "Minustecknet anger en inverterad bild."], ["For a distant object and final image at infinity the lens separation is f_obj+f_eye.", "The separation is 1.20 m = 120 cm and eyepiece focal length 9.00 cm.", "Therefore f_obj = 120−9.00 = 111 cm.", "Angular magnification is M = −f_obj/f_eye = −111/9.00 ≈ −12.3.", "The minus sign indicates an inverted image."]], "34.63": [["Den konkava spegelns brännvidd är f_obj = R/2 = 0,640 m.", "Den reella mellanbilden av det avlägsna föremålet ligger 0,640 m framför spegeln.", "Det reflekterade ljuset fortsätter genom mellanbilden till okularet, som placeras ytterligare f_ok = 0,0160 m bort.", "Spegel–okular-avståndet är därför 0,656 m.", "Vinkelförstoringen är M = −f_obj/f_ok = −0,640/0,0160 = −40,0."], ["The concave mirror focal length is f_obj = R/2 = 0.640 m.", "The real intermediate image of the distant object lies 0.640 m in front of the mirror.", "Reflected light continues through the intermediate image to the eyepiece, placed another f_eye = 0.0160 m away.", "The mirror–eyepiece separation is therefore 0.656 m.", "Angular magnification is M = −f_obj/f_eye = −0.640/0.0160 = −40.0."]], "34.64": [["Föremålsavståndet är s₁ = 14,0+2,0 = 16,0 mm.", "Linsekvationen ger s₁′ = [1/14,0−1/16,0]⁻¹ = 112 mm.", "För slutbild i oändligheten ligger mellanbilden i okularets fokus, så linsavståndet är 112+20,0 = 132 mm.", "m₁ = −112/16,0 = −7,00 och M₂ = 250/20,0 = 12,5, så M = −87,5.", "Med approximationen s₁ ≈ f₁ fås M ≈ −100; skillnaden relativt det exakta beloppet är cirka 14,3 %."], ["The object distance is s₁ = 14.0+2.0 = 16.0 mm.", "The lens equation gives s₁′ = [1/14.0−1/16.0]⁻¹ = 112 mm.", "For a final image at infinity the intermediate image is at the eyepiece focus, so lens separation is 112+20.0 = 132 mm.", "m₁ = −112/16.0 = −7.00 and M₂ = 250/20.0 = 12.5, so M = −87.5.", "With approximation s₁ ≈ f₁, M ≈ −100; the difference relative to the exact magnitude is about 14.3%."]], "34.65": [["Okularets vinkelförstoring är M₂ = 250/15,0 ≈ 16,67.", "Objektivets sidoförstoring är m₁ = −178/16,67 = −10,68.", "Mellanbilden ligger i okularets fokus, så s₁′ = 202−15,0 = 187 mm från objektivet.", "Ur m₁ = −s₁′/s₁ fås s₁ = 187/10,68 ≈ 17,5 mm.", "Linsekvationen ger utan approximationen s₁ ≈ f₁ att f₁ = [1/s₁+1/187]⁻¹ ≈ 16,0 mm."], ["The eyepiece angular magnification is M₂ = 250/15.0 ≈ 16.67.", "The objective lateral magnification is m₁ = −178/16.67 = −10.68.", "The intermediate image lies at the eyepiece focus, so s₁′ = 202−15.0 = 187 mm from the objective.", "From m₁ = −s₁′/s₁, s₁ = 187/10.68 ≈ 17.5 mm.", "Without approximating s₁ ≈ f₁, the lens equation gives f₁ = [1/s₁+1/187]⁻¹ ≈ 16.0 mm."]], "34.66": [["En upprätt bild med m = +2,5 uppfyller m = −s′/s.", "Därför är s′ = −2,5s.", "För konkav spegel är f = R/2.", "Spegelekvationen ger 1/s−1/(2,5s) = 2/R och därmed s = 0,300R.", "Bildavståndet är s′ = −0,750R: bilden är virtuell 0,750R bakom spegeln."], ["An upright image with m = +2.5 satisfies m = −s′/s.", "Therefore s′ = −2.5s.", "For a concave mirror f = R/2.", "The mirror equation gives 1/s−1/(2.5s) = 2/R and thus s = 0.300R.", "The image distance is s′ = −0.750R: the image is virtual 0.750R behind the mirror."]], "34.67": [["Skärmbilden är reell och inverterad.", "Förstoringsbeloppet är |m| = s′/s = 0,230/0,00450 ≈ 51,1.", "Med s′ = 5,00 m fås s = 5,00/51,1 ≈ 0,0978 m.", "Spegelekvationen ger f = [1/s+1/s′]⁻¹ ≈ 0,0959 m.", "Krökningsradien är R = 2f ≈ 0,192 m."], ["The screen image is real and inverted.", "The magnification magnitude is |m| = s′/s = 0.230/0.00450 ≈ 51.1.", "With s′ = 5.00 m, s = 5.00/51.1 ≈ 0.0978 m.", "The mirror equation gives f = [1/s+1/s′]⁻¹ ≈ 0.0959 m.", "The radius of curvature is R = 2f ≈ 0.192 m."]], "34.68": [["Låt s vara avståndet från spegeln till lampan.", "Väggen ligger 3,00 m bortom lampan, så s′ = s+3,00 m.", "Den reella bildens förstoringsbelopp ger s′/s = 3,50.", "Därmed s = 1,20 m och spegel–vägg-avståndet s′ = 4,20 m.", "Spegelekvationen ger f ≈ 0,933 m och R = 2f ≈ 1,87 m."], ["Let s be the distance from mirror to lamp.", "The wall is 3.00 m beyond the lamp, so s′ = s+3.00 m.", "The real image’s magnification magnitude gives s′/s = 3.50.", "Thus s = 1.20 m and mirror–wall distance s′ = 4.20 m.", "The mirror equation gives f ≈ 0.933 m and R = 2f ≈ 1.87 m."]], "34.69": [["För den konvexa spegeln är f = −0,750 m.", "Sätt b = |s′| = |f|s/(s+|f|).", "Derivering ger db/ds = [|f|/(s+|f|)]²; vid s = 2,0 m är faktorn (0,750/2,75)².", "Bildens närmandefart 2,5 m/s ger relativ närmandefart 2,5/(0,750/2,75)² ≈ 33,6 m/s.", "Lastbilen närmar sig bakifrån, så dess fart längs vägen är 26+33,6 ≈ 60 m/s i bilens färdriktning."], ["For the convex mirror f = −0.750 m.", "Set b = |s′| = |f|s/(s+|f|).", "Differentiation gives db/ds = [|f|/(s+|f|)]²; at s = 2.0 m the factor is (0.750/2.75)².", "The image approach speed 2.5 m/s gives relative approach speed 2.5/(0.750/2.75)² ≈ 33.6 m/s.", "The truck approaches from behind, so its road speed is 26+33.6 ≈ 60 m/s in the car’s direction."]], "34.70": [["Vid nära vinkelrät observation från luft bidrar varje skikt med sitt verkliga djup dividerat med sitt brytningsindex.", "Bensenlagrets skenbara bidrag är 4,40/1,50 cm.", "Vattenlagrets bidrag är 6,00/1,33 cm.", "Summera bidragen: d_sken = 4,40/1,50+6,00/1,33.", "Botten ser ut att ligga cirka 7,44 cm under bensens övre yta."], ["For near-normal viewing from air each layer contributes its actual depth divided by its refractive index.", "The benzene layer’s apparent contribution is 4.40/1.50 cm.", "The water layer contributes 6.00/1.33 cm.", "Add the contributions: d_apparent = 4.40/1.50+6.00/1.33.", "The bottom appears about 7.44 cm below the top of the benzene."]]};for(const e of root.EmberChapter34DraftExercises){const v=reviewed[e.id];if(v){e.sv.steps=v[0];e.en.steps=v[1]}}})(window);

(function(root){'use strict';const reviewed={"34.71": [["Den konvexa spegeln har f = −R/2 = −0,0900 m.", "Med s = 9,00 m ger spegelekvationen s′ ≈ −0,0891 m.", "Förstoringen är m = −s′/s ≈ +0,00990.", "Bildhöjden är h′ = m(1,5 m) ≈ +0,0149 m = 1,49 cm; bilden är upprätt och virtuell.", "Den förminskade synvinkeln kan ge intrycket att bilen är längre bort än den faktiskt är."], ["The convex mirror has f = −R/2 = −0.0900 m.", "With s = 9.00 m the mirror equation gives s′ ≈ −0.0891 m.", "Magnification is m = −s′/s ≈ +0.00990.", "Image height is h′ = m(1.5 m) ≈ +0.0149 m = 1.49 cm; the image is upright and virtual.", "The reduced apparent angular size can make the car seem farther away than it is."]], "34.72": [["I figurens skala ligger föremålet 5 rutor = 10,0 cm från linsen.", "Den givna inkommande strålens bakåtförlängning skär axeln 9 rutor = 18,0 cm framför linsen.", "Strålen genom föremålssidans fokus lämnar linsen parallellt med axeln, så linsen är samlande med f = +18,0 cm.", "En centralstråle fortsätter rakt och en parallell stråle bryts genom bildsidans fokus; deras bakåtförlängningar ger bildpunkten.", "Linsekvationen ger s′ = −22,5 cm och m = +2,25: bilden är virtuell och upprätt."], ["In the figure’s scale the object lies 5 squares = 10.0 cm from the lens.", "The given incoming ray’s backward extension meets the axis 9 squares = 18.0 cm in front of the lens.", "The ray through the object-side focus leaves parallel to the axis, so the lens is converging with f = +18.0 cm.", "A central ray continues straight and a parallel ray refracts through the image-side focus; their backward extensions locate the image.", "The lens equation gives s′ = −22.5 cm and m = +2.25: the image is virtual and upright."]], "34.73": [["En stråle från föremålets topp går genom hålet till filmens nedre del.", "En stråle från botten når den övre delen, så bilden är inverterad.", "Likformiga trianglar ger m = −s′/s = −0,225/1,4 ≈ −0,161.", "För föremålshöjden 20 cm är h′ = mh ≈ −3,21 cm.", "Bildens höjdbelopp är cirka 3,2 cm."], ["A ray from the object top passes through the hole to the lower part of the film.", "A ray from the bottom reaches the upper part, so the image is inverted.", "Similar triangles give m = −s′/s = −0.225/1.4 ≈ −0.161.", "For object height 20 cm, h′ = mh ≈ −3.21 cm.", "The image height magnitude is about 3.2 cm."]], "34.74": [["För lins 1 ger f₁ = +8,40 cm och s₁ = 28,0 cm bildavståndet s₁′ = +12,0 cm och m₁ = −3/7.", "Den första bilden ligger 4,00 cm bortom lins 2 och är ett virtuellt föremål för den: s₂ = −4,00 cm.", "Total förstoring är m = −5,60/4,00 = −1,40, så m₂ = m/m₁ = 49/15.", "Därför s₂′ = −m₂s₂ ≈ +13,07 cm och f₂ = [1/s₂+1/s₂′]⁻¹ ≈ −5,76 cm.", "Avståndet från ursprungligt föremål till slutbild är 28,0+8,00+13,07 ≈ 49,1 cm."], ["For lens 1, f₁ = +8.40 cm and s₁ = 28.0 cm give s₁′ = +12.0 cm and m₁ = −3/7.", "The first image lies 4.00 cm beyond lens 2 and is its virtual object: s₂ = −4.00 cm.", "Total magnification is m = −5.60/4.00 = −1.40, so m₂ = m/m₁ = 49/15.", "Therefore s₂′ = −m₂s₂ ≈ +13.07 cm and f₂ = [1/s₂+1/s₂′]⁻¹ ≈ −5.76 cm.", "The original-object to final-image distance is 28.0+8.00+13.07 ≈ 49.1 cm."]], "34.75": [["För parallella strålar vid första sfäriska luft–material-ytan är s = ∞ och R positivt.", "Ytekvationen ger n/s′ = (n−1)/R.", "För fokus vid bortre ytan ska s′ = 2R.", "Insättning ger n/2 = n−1.", "Lösningen är n = 2,00 i den paraxiella modellen."], ["For parallel rays at the first spherical air–material surface, s = ∞ and R is positive.", "The surface equation gives n/s′ = (n−1)/R.", "For focus at the far surface, s′ = 2R.", "Substitution gives n/2 = n−1.", "The solution is n = 2.00 in the paraxial model."]], "34.76": [["Myntet är nedsänkt i vattnet. För utgående vatten–luft-brytning är ytradien −R.", "Ytekvationen blir n/s+1/s′ = (n−1)/R.", "Med m = −ns′/s fås m = n/[n−(n−1)s/R].", "Vid bakväggen är s = 2R och m_bak = n/(2−n), så n = 2m_bak/(1+m_bak).", "För n ≈ 1,33 väntas m_bak ≈ 1,99. Mät förstoringen och använd formeln; verklig glastjocklek och stora strålvinklar påverkar resultatet."], ["The coin is submerged in water. For outgoing water–air refraction the signed surface radius is −R.", "The surface equation is n/s+1/s′ = (n−1)/R.", "With m = −ns′/s, m = n/[n−(n−1)s/R].", "At the back wall s = 2R and m_back = n/(2−n), so n = 2m_back/(1+m_back).", "For n ≈ 1.33, m_back ≈ 1.99. Measure the magnification and use the formula; real glass thickness and large ray angles affect the result."]], "34.77": [["En reell bild med dubbelt höjdbelopp är inverterad, så s′ = 2s.", "Linsekvationen ger då s = 3f/2 = 52,5 cm.", "En virtuell upprätt bild med m = +2 har s′ = −2s.", "Linsekvationen ger då s = f/2 = 17,5 cm.", "Båda fallen kräver positiv brännvidd, alltså en samlingslins."], ["A real image with twice the height magnitude is inverted, so s′ = 2s.", "The lens equation then gives s = 3f/2 = 52.5 cm.", "A virtual upright image with m = +2 has s′ = −2s.", "The lens equation then gives s = f/2 = 17.5 cm.", "Both cases require positive focal length, hence a converging lens."]], "34.78": [["Föremålet och skärmen står intill varandra och linsen är 22,0 cm från dem.", "Den plana spegeln ligger ytterligare 38,0 cm bort.", "I vanlig autokollimation ligger föremålet i fokus: strålarna går parallellt till spegeln och återvänder genom linsen till skärmen.", "Denna lösning ger f = 22,0 cm.", "I en ideal paraxiell modell finns även ett särskilt fall där första bilden ligger precis på spegeln: 1/f = 1/22,0+1/38,0 ger f ≈ 13,9 cm."], ["The object and screen are adjacent and the lens is 22.0 cm from them.", "The plane mirror lies another 38.0 cm away.", "In ordinary autocollimation the object is at the focus: rays travel parallel to the mirror and return through the lens to the screen.", "This solution gives f = 22.0 cm.", "In an ideal paraxial model there is also a special case where the first image lies exactly on the mirror: 1/f = 1/22.0+1/38.0 gives f ≈ 13.9 cm."]], "34.79": [["En reell bild av ett verkligt föremål kräver en samlingslins och är inverterad.", "Förstoringsbeloppet ger s′/s = 1⅔ = 5/3.", "Avståndet mellan föremål och bild ger s+s′ = 214 cm.", "Därför s = 214·3/8 = 80,25 cm och s′ = 133,75 cm.", "Brännvidden blir f = ss′/(s+s′) ≈ +50,2 cm."], ["A real image of a real object requires a converging lens and is inverted.", "The magnification magnitude gives s′/s = 1⅔ = 5/3.", "Object–image separation gives s+s′ = 214 cm.", "Therefore s = 214·3/8 = 80.25 cm and s′ = 133.75 cm.", "The focal length is f = ss′/(s+s′) ≈ +50.2 cm."]], "34.80": [["Bild och föremål ligger på samma sida: s = +8,00 cm och s′ = −3,00 cm.", "Linsekvationen ger 1/f = 1/8,00−1/3,00.", "Därmed f = −4,80 cm och linsen är spridande.", "Förstoringen är m = −s′/s = +0,375 och h′ = +2,44 mm.", "Bilden är virtuell och upprätt; bakåtförlängningarna av de brutna strålarna möts i bilden."], ["Object and image lie on the same side: s = +8.00 cm and s′ = −3.00 cm.", "The lens equation gives 1/f = 1/8.00−1/3.00.", "Thus f = −4.80 cm and the lens is diverging.", "Magnification is m = −s′/s = +0.375 and h′ = +2.44 mm.", "The image is virtual and upright; backward extensions of the refracted rays meet at the image."]]};for(const e of root.EmberChapter34DraftExercises){const v=reviewed[e.id];if(v){e.sv.steps=v[0];e.en.steps=v[1]}}})(window);

(function(root){'use strict';const reviewed={"34.81": [["Föremålet är 16,0 cm från linsen och bilden ytterligare 6,00 cm åt vänster.", "Därför s = +16,0 cm och s′ = −22,0 cm.", "Linsekvationen ger f = [1/16,0−1/22,0]⁻¹ ≈ +58,7 cm: linsen är samlande.", "Förstoringen är m = −s′/s = +1,375 och h′ ≈ +4,47 mm.", "Bilden är upprätt och virtuell; bakåtförlängningarna möts i bilden."], ["The object is 16.0 cm from the lens and the image another 6.00 cm to the left.", "Therefore s = +16.0 cm and s′ = −22.0 cm.", "The lens equation gives f = [1/16.0−1/22.0]⁻¹ ≈ +58.7 cm: the lens is converging.", "Magnification is m = −s′/s = +1.375 and h′ ≈ +4.47 mm.", "The image is upright and virtual; backward extensions meet at the image."]], "34.82": [["Genom den plana ytan är skenbart djup d/n = 8,20 cm.", "Eftersom verkligt djup är 15,0 cm fås n = 15,0/8,20 ≈ 1,829.", "För brytning ut genom den krökta ytan är s = 15,0 cm, n₁ = 1,829, n₂ = 1,00 och R = −10,0 cm.", "Ytekvationen n₁/s+n₂/s′ = (n₂−n₁)/R ger s′ ≈ −25,6 cm.", "Föremålet verkar ligga 25,6 cm innanför den krökta ytans topp."], ["Through the plane surface the apparent depth is d/n = 8.20 cm.", "Since actual depth is 15.0 cm, n = 15.0/8.20 ≈ 1.829.", "For refraction out through the curved surface s = 15.0 cm, n₁ = 1.829, n₂ = 1.00 and R = −10.0 cm.", "The surface equation n₁/s+n₂/s′ = (n₂−n₁)/R gives s′ ≈ −25.6 cm.", "The object appears 25.6 cm inside the curved surface’s vertex."]], "34.83": [["För s = ∞ och s′ = 2,50 cm ger ytekvationen 1,35/2,50 = 0,35/R.", "Därför R ≈ 0,648 cm = 6,48 mm.", "Med samma R och s = 25,0 cm är 1/25,0+1,35/s′ = 0,540 cm⁻¹.", "Då s′ = 2,70 cm, bakom näthinnan.", "Med R = 0,500 cm och s = ∞ fås s′ = 1,35R/0,35 ≈ 1,93 cm, framför näthinnan; hornhinnan ensam är en förenklad ögonmodell."], ["For s = ∞ and s′ = 2.50 cm the surface equation gives 1.35/2.50 = 0.35/R.", "Therefore R ≈ 0.648 cm = 6.48 mm.", "With the same R and s = 25.0 cm, 1/25.0+1.35/s′ = 0.540 cm⁻¹.", "Then s′ = 2.70 cm, behind the retina.", "With R = 0.500 cm and s = ∞, s′ = 1.35R/0.35 ≈ 1.93 cm, in front of the retina; the cornea alone is a simplified eye model."]], "34.84": [["Linsmakarens ekvation ger 1/f = 0,60(1/12,0−1/28,0), alltså f = +35,0 cm.", "Med s₁ = 45,0 cm fås s₁′ = +157,5 cm, m₁ = −3,50 och h₁′ = −17,5 mm.", "Vid 315 cm linsavstånd är s₂ = +157,5 cm och s₂′ = +45,0 cm.", "Slutbilden ligger då x = 360 cm från lins 1 och är +5,00 mm hög.", "Vid 45,0 cm linsavstånd är s₂ = −112,5 cm; då s₂′ ≈ +26,7 cm, x ≈ 71,7 cm och h′ ≈ −4,15 mm."], ["The lensmaker equation gives 1/f = 0.60(1/12.0−1/28.0), so f = +35.0 cm.", "With s₁ = 45.0 cm, s₁′ = +157.5 cm, m₁ = −3.50 and h₁′ = −17.5 mm.", "At 315 cm lens separation, s₂ = +157.5 cm and s₂′ = +45.0 cm.", "The final image is then x = 360 cm from lens 1 and +5.00 mm high.", "At 45.0 cm separation, s₂ = −112.5 cm; then s₂′ ≈ +26.7 cm, x ≈ 71.7 cm and h′ ≈ −4.15 mm."]], "34.86": [["Föremål och skärm ger s+s′ = 22,0 cm.", "Linsekvationen ger ss′ = f(s+s′) = 66,0 cm².", "Sätt s′ = 22,0−s och lös s(22,0−s) = 66,0.", "Då s = (22,0±√220)/2 ≈ 3,58 eller 18,42 cm från föremålet.", "Förstoringen m = −s′/s är cirka −5,14 respektive −0,195; båda bilderna är inverterade."], ["Object and screen give s+s′ = 22.0 cm.", "The lens equation gives ss′ = f(s+s′) = 66.0 cm².", "Set s′ = 22.0−s and solve s(22.0−s) = 66.0.", "Then s = (22.0±√220)/2 ≈ 3.58 or 18.42 cm from the object.", "Magnification m = −s′/s is about −5.14 and −0.195 respectively; both images are inverted."]], "34.87": [["Glasögonen sitter 0,020 m framför ögat och ska ge en virtuell bild vid den okorrigerade närpunkten.", "Bildavståndet från glasögonen är s′ = −(0,85−0,02) = −0,83 m.", "Med P = +2,25 D är 1/s = 2,25+1/0,83, så s ≈ 0,289 m från linsen.", "Närpunkten med glasögon är därför 0,309 m från ögat.", "För kontaktlins är s′ = −0,85 m och 1/s = 2,25+1/0,85, vilket ger cirka 0,292 m från ögat."], ["The glasses sit 0.020 m in front of the eye and must produce a virtual image at the uncorrected near point.", "The image distance from the glasses is s′ = −(0.85−0.02) = −0.83 m.", "With P = +2.25 D, 1/s = 2.25+1/0.83, giving s ≈ 0.289 m from the lens.", "The near point with glasses is therefore 0.309 m from the eye.", "For a contact lens s′ = −0.85 m and 1/s = 2.25+1/0.85, giving about 0.292 m from the eye."]], "34.88": [["För en reell bild på skärmen är d = s+s′.", "Linsekvationen ger ss′ = fd.", "För givet d gäller ss′ ≤ [(s+s′)/2]² = d²/4.", "Alltså fd ≤ d²/4 och d ≥ 4f för positivt d.", "Likhet fås när s = s′ = 2f; minsta avståndet är d_min = 4f."], ["For a real image on the screen d = s+s′.", "The lens equation gives ss′ = fd.", "For fixed d, ss′ ≤ [(s+s′)/2]² = d²/4.", "Thus fd ≤ d²/4 and d ≥ 4f for positive d.", "Equality occurs at s = s′ = 2f; the minimum separation is d_min = 4f."]], "34.89": [["Spegelfokus är 10,0 cm, så krökningscentrum och ljuset ligger 20,0 cm framför spegeln.", "Spegeln ger en reell inverterad mellanbild på samma avstånd.", "För både direkt ljus och spegelreflekterat ljus är linsens föremålsavstånd 85,0 cm.", "Linsekvationen 1/s′ = 1/32,0−1/85,0 ger s′ ≈ +51,3 cm till höger om linsen.", "Linsen inverterar direktbilden. Spegelns mellanbild inverteras en gång till av linsen, så den andra bilden är reell och upprätt relativt ljuset."], ["The mirror focal length is 10.0 cm, so the center of curvature and candle are 20.0 cm in front of the mirror.", "The mirror forms a real inverted intermediate image at the same distance.", "For both direct and mirror-reflected light the lens object distance is 85.0 cm.", "The lens equation 1/s′ = 1/32.0−1/85.0 gives s′ ≈ +51.3 cm right of the lens.", "The lens inverts the direct image. The mirror’s intermediate image is inverted once more by the lens, so the second image is real and upright relative to the candle."]], "34.90": [["För två tunna linser i kontakt är andra linsens föremålsavstånd s₂ = −s₁′.", "Addition av linsekvationerna tar bort mellanbildens reciprok och ger 1/f_eff = 1/f₁+1/f₂.", "Glasmenisken har styrkan P₁ = (1,55−1)(1/4,50−1/9,00) = 0,06111 cm⁻¹.", "Vätskan bildar en plankonvex lins med P₂ = (1,46−1)/9,00 = 0,05111 cm⁻¹.", "P_tot = 0,11222 cm⁻¹ och f_eff = 1/P_tot ≈ +8,91 cm."], ["For two thin lenses in contact the second lens object distance is s₂ = −s₁′.", "Adding the lens equations removes the intermediate-image reciprocals and gives 1/f_eff = 1/f₁+1/f₂.", "The glass meniscus has power P₁ = (1.55−1)(1/4.50−1/9.00) = 0.06111 cm⁻¹.", "The liquid forms a plano-convex lens with P₂ = (1.46−1)/9.00 = 0.05111 cm⁻¹.", "P_tot = 0.11222 cm⁻¹ and f_eff = 1/P_tot ≈ +8.91 cm."]]};for(const e of root.EmberChapter34DraftExercises){const v=reviewed[e.id];if(v){e.sv.steps=v[0];e.en.steps=v[1]}}})(window);

(function(root){'use strict';const reviewed={"34.91": [["Utan lins 2 skulle bilden ligga 30,0 cm från lins 1.", "Lins 2 ligger vid 15,0 cm, så mellanbilden är dess virtuella föremål med s₂ = −15,0 cm.", "Nya skärmen ligger vid 30,0+19,2 = 49,2 cm från första linsen.", "Bildavståndet för lins 2 är därför s₂′ = +34,2 cm.", "Linsekvationen ger f₂ = [−1/15,0+1/34,2]⁻¹ ≈ −26,7 cm."], ["Without lens 2 the image would lie 30.0 cm from lens 1.", "Lens 2 is at 15.0 cm, so the intermediate image is its virtual object with s₂ = −15.0 cm.", "The new screen is at 30.0+19.2 = 49.2 cm from lens 1.", "The image distance for lens 2 is therefore s₂′ = +34.2 cm.", "The lens equation gives f₂ = [−1/15.0+1/34.2]⁻¹ ≈ −26.7 cm."]], "34.92": [["Brytningsekvationen används för varje yta, med samma vätska på båda sidor om den tunna linsen.", "När ekvationerna adderas försvinner mellanbildens reciproker.", "Resultatet är 1/f = (n_lins/n_vätska−1)(1/R₁−1/R₂).", "Samma geometrifaktor gäller före och efter nedsänkning.", "Därför f_vätska = 18,0(1,60−1)/(1,60/1,42−1) ≈ +85,2 cm."], ["Use the refraction equation for each surface, with the same liquid on both sides of the thin lens.", "Adding the equations cancels the intermediate-image reciprocals.", "The result is 1/f = (n_lens/n_liquid−1)(1/R₁−1/R₂).", "The same geometry factor applies before and after immersion.", "Therefore f_liquid = 18.0(1.60−1)/(1.60/1.42−1) ≈ +85.2 cm."]], "34.93": [["Den konvexa spegeln har f = −24,0 cm och föremålet står 10,0 cm framför den.", "Spegelekvationen ger direktbilden s′ ≈ −7,06 cm och m ≈ +0,706.", "Direktbildens höjd är h′ ≈ +0,176 cm bakom den konvexa spegeln.", "Planspegeln ger en upprätt bild 10,0 cm bakom sig, alltså 30,0 cm framför den konvexa spegeln.", "Med s = 30,0 cm fås för den andra bilden s′ ≈ −13,3 cm, m ≈ +0,444 och h′ ≈ +0,111 cm."], ["The convex mirror has f = −24.0 cm and the object is 10.0 cm in front of it.", "The mirror equation gives the direct image s′ ≈ −7.06 cm and m ≈ +0.706.", "The direct image height is h′ ≈ +0.176 cm behind the convex mirror.", "The plane mirror gives an upright image 10.0 cm behind it, or 30.0 cm in front of the convex mirror.", "With s = 30.0 cm, the second image has s′ ≈ −13.3 cm, m ≈ +0.444 and h′ ≈ +0.111 cm."]], "34.94": [["Ögonmodellen har bildavstånd s′ = 2,50 cm och föremålsavstånd s = 25,0 cm.", "Förstoringsbeloppet är |m| = s′/s = 0,100.", "En receptorbred bild på 5,0 μm kräver en föremålsbredd 5,0/0,100 = 50 μm.", "Småvinkeln är θ ≈ 50·10⁻⁶/0,25 = 2,0·10⁻⁴ rad.", "Omräkning till bågminuter ger cirka 0,69, jämförbart med 1 bågminut."], ["The eye model has image distance s′ = 2.50 cm and object distance s = 25.0 cm.", "Magnification magnitude is |m| = s′/s = 0.100.", "A receptor-wide image of 5.0 μm requires object width 5.0/0.100 = 50 μm.", "The small angle is θ ≈ 50·10⁻⁶/0.25 = 2.0·10⁻⁴ rad.", "Conversion to arcminutes gives about 0.69, comparable with 1 arcminute."]], "34.95": [["För lins 1 är s₁ = 80,0 cm och f₁ = 40,0 cm, vilket ger s₁′ = +80,0 cm.", "Denna bild ligger 28,0 cm bortom lins 2 och är dess virtuella föremål: s₂ = −28,0 cm.", "Lins 2 ger s₂′ = [1/40,0+1/28,0]⁻¹ ≈ +16,47 cm.", "För lins 3 är s₃ = 52,0−16,47 ≈ 35,53 cm.", "Linsekvationen ger s₃′ ≈ −318 cm: slutbilden är virtuell cirka 318 cm till vänster om tredje linsen."], ["For lens 1, s₁ = 80.0 cm and f₁ = 40.0 cm give s₁′ = +80.0 cm.", "This image is 28.0 cm beyond lens 2 and is its virtual object: s₂ = −28.0 cm.", "Lens 2 gives s₂′ = [1/40.0+1/28.0]⁻¹ ≈ +16.47 cm.", "For lens 3, s₃ = 52.0−16.47 ≈ 35.53 cm.", "The lens equation gives s₃′ ≈ −318 cm: the final image is virtual about 318 cm to the left of lens 3."]], "34.96": [["Använd mm: f = 90 mm, s₁ = 1300 mm och s₂ = 6500 mm.", "För första läget ger linsekvationen s₁′ = [1/90−1/1300]⁻¹ ≈ 96,69 mm.", "För andra läget fås s₂′ = [1/90−1/6500]⁻¹ ≈ 91,26 mm.", "Lins–sensor-avståndet minskar med 96,69−91,26 ≈ 5,43 mm.", "Linsen ska alltså flyttas mot sensorn."], ["Use mm: f = 90 mm, s₁ = 1300 mm and s₂ = 6500 mm.", "For the first position the lens equation gives s₁′ = [1/90−1/1300]⁻¹ ≈ 96.69 mm.", "For the second position s₂′ = [1/90−1/6500]⁻¹ ≈ 91.26 mm.", "The lens–sensor separation decreases by 96.69−91.26 ≈ 5.43 mm.", "The lens must therefore move toward the sensor."]], "34.97": [["Ögat antas fokusera parallella strålar men inte kunna ackommodera.", "Kontaktlinsen ska därför ge en bild vid oändligheten.", "Föremålet måste då ligga i kontaktlinsens främre fokus.", "Läsavståndet är f = +0,24 m.", "Styrkan är P = 1/f ≈ +4,17 D."], ["The eye is assumed to focus parallel rays but unable to accommodate.", "The contact lens must therefore produce an image at infinity.", "The object must then lie at the contact lens’s front focus.", "The reading distance gives f = +0.24 m.", "Power is P = 1/f ≈ +4.17 D."]], "34.98": [["Använd sfärisk brytning med s = 36,0 cm och R = +0,75 cm.", "Index är n₁ = 1,00 och n₂ = 1,40.", "Ytekvationen ger 1/36,0+1,40/s′ = 0,40/0,75.", "Lös s′ ≈ 2,77 cm.", "Det överstiger jämförelsemodellens 2,60 cm; detta modellöga är längre framifrån och bakåt, men verklig närsynthet kan ha flera orsaker."], ["Use spherical refraction with s = 36.0 cm and R = +0.75 cm.", "The indices are n₁ = 1.00 and n₂ = 1.40.", "The surface equation gives 1/36.0+1.40/s′ = 0.40/0.75.", "Solving gives s′ ≈ 2.77 cm.", "This exceeds the comparison model’s 2.60 cm; this model eye is longer front to back, though real nearsightedness can have multiple causes."]], "34.99": [["Första linsen fokuserar parallella strålar; likformiga trianglar ger r₂ = r₀(f₁−d)/f₁.", "För lins 2 är föremålet virtuellt: s₂ = −(f₁−d).", "Med f₂ = −|f₂| ger linsekvationen s₂′ = |f₂|(f₁−d)/(|f₂|−f₁+d).", "Bakåtförlängning av utgående strålar till radien r₀ ger f_eff = s₂′r₀/r₂ = f₁|f₂|/(|f₂|−f₁+d).", "För givna värden är f_eff = 216/(6+d) cm: största 36,0 cm vid d = 0, minsta 21,6 cm vid d = 4,0 cm och d = 1,20 cm när f_eff = 30,0 cm."], ["The first lens focuses parallel rays; similar triangles give r₂ = r₀(f₁−d)/f₁.", "For lens 2 the object is virtual: s₂ = −(f₁−d).", "With f₂ = −|f₂| the lens equation gives s₂′ = |f₂|(f₁−d)/(|f₂|−f₁+d).", "Backward extension of outgoing rays to radius r₀ gives f_eff = s₂′r₀/r₂ = f₁|f₂|/(|f₂|−f₁+d).", "For the given values f_eff = 216/(6+d) cm: maximum 36.0 cm at d = 0, minimum 21.6 cm at d = 4.0 cm and d = 1.20 cm when f_eff = 30.0 cm."]], "34.100": [["Med små vinklar ger objektiv och spridande okular M = −f₁/f₂.", "Eftersom f₂ < 0 blir M positivt: bilden är upprätt.", "Samma förstoringsbelopp som 95,0/15,0 kräver f₂ = −15,0 cm för objektivet f₁ = +95,0 cm.", "Det galileiska teleskopets linsavstånd är f₁−|f₂| = 80,0 cm.", "Ett astronomiskt teleskop med positivt okular har i stället längden 95,0+15,0 = 110,0 cm."], ["With small angles, objective and diverging eyepiece give M = −f₁/f₂.", "Since f₂ < 0, M is positive: the image is upright.", "The same magnification magnitude as 95.0/15.0 requires f₂ = −15.0 cm for objective f₁ = +95.0 cm.", "The Galilean telescope lens separation is f₁−|f₂| = 80.0 cm.", "An astronomical telescope with positive eyepiece instead has length 95.0+15.0 = 110.0 cm."]]};for(const e of root.EmberChapter34DraftExercises){const v=reviewed[e.id];if(v){e.sv.steps=v[0];e.en.steps=v[1]}}})(window);

(function(root){'use strict';const reviewed={"34.101": [["Mellanbilden från första linsen ligger vid x = 29,7 cm.", "För lins 2 vid x = 20,0 cm är mellanbilden ett virtuellt föremål med s₂ = −9,7 cm och s₂′ = 42,8−20,0 = 22,8 cm.", "Linsekvationen ger f₂ = [1/(−9,7)+1/22,8]⁻¹ ≈ −16,88 cm.", "Vid x = 25,0 cm är s₂ = −4,7 cm och s₂′ = 6,6 cm, vilket ger f₂ ≈ −16,33 cm och medelvärdet −16,6 cm.", "Förstoringsbeloppen är 22,8/9,7 ≈ 2,35 respektive 6,6/4,7 ≈ 1,40; första läget ger högre slutbild."], ["The first lens forms an intermediate image at x = 29.7 cm.", "For lens 2 at x = 20.0 cm the intermediate image is a virtual object with s₂ = −9.7 cm and s₂′ = 42.8−20.0 = 22.8 cm.", "The lens equation gives f₂ = [1/(−9.7)+1/22.8]⁻¹ ≈ −16.88 cm.", "At x = 25.0 cm, s₂ = −4.7 cm and s₂′ = 6.6 cm, giving f₂ ≈ −16.33 cm and mean −16.6 cm.", "The magnification magnitudes are 22.8/9.7 ≈ 2.35 and 6.6/4.7 ≈ 1.40; the first position yields the taller final image."]], "34.102": [["Spegelekvationen är 1/s+1/s′ = 1/f och m = −s′/s.", "Sätt in s′ = −ms: s = f(1−1/m).", "Grafens skärning vid 1/m = 0 ger f = 25 cm.", "För m = −2 fås s = 37,5 cm; för m = −3 fås s ≈ 33,3 cm, alltså en flyttning 4,17 cm mot spegeln.", "Vid s = f går bilden mot oändligheten; innanför fokus blir bilden virtuell och upprätt bakom spegeln och kan inte fångas på en skärm."], ["The mirror equation is 1/s+1/s′ = 1/f and m = −s′/s.", "Insert s′ = −ms to obtain s = f(1−1/m).", "The graph intercept at 1/m = 0 gives f = 25 cm.", "For m = −2, s = 37.5 cm; for m = −3, s ≈ 33.3 cm, so move 4.17 cm toward the mirror.", "At s = f the image goes to infinity; inside the focus the image is virtual and upright behind the mirror and cannot be captured on a screen."]], "34.103": [["Brytningsytans ekvation i luft och glas ger 1/s′ = −(1/n)(1/s)+(n−1)/(nR).", "Därför är en graf av 1/s′ mot 1/s linjär.", "Minsta-kvadratanpassning av de sex mätparen ger lutning ≈ −0,66662 och intercept ≈ 0,03333 cm⁻¹.", "Då n = −1/lutningen ≈ 1,500 och R = (n−1)/(n·intercept) ≈ 10,0 cm.", "Vid s = 15,0 cm ger linjen s′ ≈ −90,0 cm: en virtuell bild på föremålssidan."], ["The refracting-surface equation in air and glass gives 1/s′ = −(1/n)(1/s)+(n−1)/(nR).", "Thus a graph of 1/s′ against 1/s is linear.", "A least-squares fit to the six measurement pairs gives slope ≈ −0.66662 and intercept ≈ 0.03333 cm⁻¹.", "Then n = −1/slope ≈ 1.500 and R = (n−1)/(n·intercept) ≈ 10.0 cm.", "At s = 15.0 cm the line gives s′ ≈ −90.0 cm: a virtual image on the object side."]], "34.104": [["Parabeln y = ax² har lutning dy/dx = 2ax, alltså 2ar vid träffpunkten x = r.", "Normalens lutning är −1/(2ar), och dess vinkel φ mot den vertikala axeln uppfyller tan φ = 2ar.", "Reflektionslagen ger α = 2φ−π/2 för strålen i figurens orientering.", "När träffpunkten ligger över fokus är höjdskillnaden b = r tan α = −r cot(2φ) = ar²−1/(4a).", "Fokushöjden är ar²−b = 1/(4a), oberoende av r. För mindre r byter den tecknade höjdskillnaden tecken, men fokus är samma."], ["The parabola y = ax² has slope dy/dx = 2ax, or 2ar at x = r.", "The normal slope is −1/(2ar), and its angle φ to the vertical axis satisfies tan φ = 2ar.", "The law of reflection gives α = 2φ−π/2 for the ray in the figure’s orientation.", "When the hit point is above focus the height difference is b = r tan α = −r cot(2φ) = ar²−1/(4a).", "The focal height is ar²−b = 1/(4a), independent of r. For smaller r the signed height difference reverses, but the focus is unchanged."]], "34.105": [["En reell bild av ett reellt föremål kräver s > f.", "Linsekvationen ger s′ = fs/(s−f) och avståndet D(s) = s+fs/(s−f).", "Derivatan D′(s) = 1−f²/(s−f)² är noll vid s = 2f.", "Där är D″ > 0 och D_min = 2f+2f = 4f.", "Grafen går mot oändligheten då s närmar sig f ovanifrån och då s → ∞, med minimum i (2f, 4f)."], ["A real image of a real object requires s > f.", "The lens equation gives s′ = fs/(s−f) and separation D(s) = s+fs/(s−f).", "The derivative D′(s) = 1−f²/(s−f)² vanishes at s = 2f.", "There D″ > 0 and D_min = 2f+2f = 4f.", "The graph tends to infinity as s approaches f from above and as s → ∞, with minimum at (2f, 4f)."]], "34.106": [["Använd koordinater i cm från linsen, med positiv riktning åt höger och uppåt.", "Halva pennan ger horisontella och vertikala avstånd 8/√2 cm: s_A = 45+8/√2, h_A = 15−8/√2, s_B = 45−8/√2, h_B = 15+8/√2.", "För varje punkt ger s′ = fs/(s−f) och h′ = −s′h/s bilderna A′ ≈ (33,05; −6,10), B′ ≈ (40,68; −21,36) och C′ = (36,0; −12,0).", "Avståndsformeln ger A′B′ ≈ 17,1 cm.", "Bilden ligger under axeln och lutar nedåt åt höger; bildpunkten C′ behöver inte vara mittpunkten på A′B′."], ["Use coordinates in cm from the lens, positive rightward and upward.", "The half-pencil gives horizontal and vertical offsets 8/√2 cm: s_A = 45+8/√2, h_A = 15−8/√2, s_B = 45−8/√2, h_B = 15+8/√2.", "For each point, s′ = fs/(s−f) and h′ = −s′h/s give A′ ≈ (33.05, −6.10), B′ ≈ (40.68, −21.36), and C′ = (36.0, −12.0).", "The distance formula gives A′B′ ≈ 17.1 cm.", "The image is below the axis and slopes downward to the right; C′ need not be the midpoint of A′B′."]], "34.107": [["I luft ger modellen från 34.52 hornhinneradien R = 0,40/[1/40,0+1,40/2,60] ≈ 0,7099 cm.", "I vatten minskar hornhinnans brytning eftersom indexskillnaden bara är 1,40−1,33 = 0,07.", "För fokus på näthinnan kräver 1,33/s+1,40/2,60 = 0,07/R att s ≈ −3,024 cm.", "Det negativa föremålsavståndet betyder att strålarna ska konvergera mot en virtuell föremålspunkt 3,024 cm bakom hornhinnan. Linsen ligger 2,00 cm framför den, så f_vatten ≈ +5,024 cm.", "Med oförändrad linsgeometri ger indexförhållandet f_luft = f_vatten(1,62/1,33−1)/(1,62−1) ≈ +1,77 cm."], ["In air the model of 34.52 gives corneal radius R = 0.40/[1/40.0+1.40/2.60] ≈ 0.7099 cm.", "In water corneal refraction decreases because the index difference is only 1.40−1.33 = 0.07.", "To focus on the retina, 1.33/s+1.40/2.60 = 0.07/R requires s ≈ −3.024 cm.", "The negative object distance means rays must converge toward a virtual object point 3.024 cm behind the cornea. The lens is 2.00 cm in front, so f_water ≈ +5.024 cm.", "For unchanged lens geometry the index ratio gives f_air = f_water(1.62/1.33−1)/(1.62−1) ≈ +1.77 cm."]], "34.108": [["Använd centimeter: initialt s = 10 cm och s′ = 0,8 cm.", "Linsekvationen ger f = [1/10+1/0,8]⁻¹ ≈ 0,7407 cm.", "Vid ungefär s = 15 cm ger samma brännvidd s′ = [1/f−1/15]⁻¹ ≈ 0,7792 cm.", "Lins–näthinneavståndet minskar med 0,8000−0,7792 ≈ 0,0208 cm.", "Linsen flyttas mot näthinnan: alternativ (a). Den lilla ändringen i föremålsavstånd från linsrörelsen påverkar inte avrundningen."], ["Use centimeters: initially s = 10 cm and s′ = 0.8 cm.", "The lens equation gives f = [1/10+1/0.8]⁻¹ ≈ 0.7407 cm.", "At approximately s = 15 cm, the same focal length gives s′ = [1/f−1/15]⁻¹ ≈ 0.7792 cm.", "The lens–retina distance decreases by 0.8000−0.7792 ≈ 0.0208 cm.", "The lens moves toward the retina: choice (a). The small object-distance change from lens movement does not affect the rounded result."]], "34.109": [["En kontaktlins med styrka P = −6,0 D är spridande.", "Brännvidden är f = 1/P = −0,167 m.", "Ett mycket avlägset föremål ger en virtuell bild vid linsens fokus.", "Bilden ska ligga vid grodans okorrigerade fjärrpunkt.", "Fjärrpunkten ligger alltså cirka 0,17 m = 17 cm framför ögat: alternativ (d)."], ["A contact lens of power P = −6.0 D is diverging.", "Its focal length is f = 1/P = −0.167 m.", "A very distant object forms a virtual image at the lens focus.", "That image must lie at the frog’s uncorrected far point.", "The far point is therefore about 0.17 m = 17 cm in front of the eye: choice (d)."]], "34.110": [["Hornhinnans brytning beror på skillnaden mellan brytningsindex på dess båda sidor.", "Skillnaden mellan vatten och öga är mindre än mellan luft och öga.", "Hornhinnans samlande styrka minskar därför i vatten.", "I den förenklade modellen minskar närsyntheten: alternativ (b).", "Den exakta förändringen beror på hela ögats optik och kan inte bestämmas utifrån uppgifterna ensamma."], ["Corneal refraction depends on the difference between the refractive indices on its two sides.", "The difference between water and eye is smaller than between air and eye.", "The cornea’s converging power therefore decreases in water.", "In the simplified model nearsightedness decreases: choice (b).", "The exact change depends on the optics of the whole eye and cannot be determined from the given information alone."]], "34.111": [["Båda linsstyrkorna är negativa, så båda linserna är spridande.", "För samma positiva föremålsavstånd gäller 1/s′ = P−1/s.", "Bildavståndet s′ är negativt: bilden är virtuell.", "P = −15 D ger större |1/s′| än −9 D och därmed mindre |s′|.", "Bilden från −15 D-linsen ligger närmare grodan: alternativ (b)."], ["Both powers are negative, so both lenses are diverging.", "For the same positive object distance, 1/s′ = P−1/s.", "The image distance s′ is negative: the image is virtual.", "P = −15 D gives a larger |1/s′| than −9 D and hence a smaller |s′|.", "The image from the −15 D lens lies closer to the frog: choice (b)."]]};for(const e of root.EmberChapter34DraftExercises){const v=reviewed[e.id];if(v){e.sv.steps=v[0];e.en.steps=v[1]}}})(window);
(function(root){'use strict';const e=root.EmberChapter34DraftExercises.find(x=>x.id==='34.78');e.figure='autocollimation-78.svg';e.alt={sv:'Objekt O och skärm S ligger bredvid varandra, 22,0 cm från en samlingslins. En svagt vinklad plan spegel M är ytterligare 38,0 cm bort. Två strålar går parallellt efter linsen och fokuseras vid återkomsten på skärmen.',en:'Object O and screen S are adjacent, 22.0 cm from a converging lens. A slightly tilted plane mirror M is another 38.0 cm away. Two rays are parallel after the lens and refocus on the screen after reflection.'};
e.sv.prompt='Ett objekt står bredvid en skärm. En plan spegel är 60,0 cm till höger om objektet och lutar något. En samlingslins placeras mellan dem så att ljuset passerar linsen, reflekteras i spegeln och efter en andra linspassage fokuseras på skärmen. Linsen är 22,0 cm från objektet. (a) Rita objekt, skärm, lins och spegel. (b) Bestäm linsens brännvidd.';
e.en.prompt='An object stands beside a screen. A plane mirror is 60.0 cm to the right of the object and is tilted slightly. A converging lens between them sends light to the mirror and, on the return pass, focuses it onto the screen. The lens is 22.0 cm from the object. (a) Sketch the object, screen, lens and mirror. (b) Find the lens focal length.';
e.sv.steps=['(a) Se skissen: objektet och skärmen ligger intill varandra, linsen är 22,0 cm från objektet och den plana spegeln är ytterligare 38,0 cm bort. Spegelns svaga lutning skiljer returstrålarna från objektet.','(b) Vid autokollimation ligger objektet i linsens främre fokalplan. Strålar från en objektpunkt blir då parallella efter första linspassagen.','Spegeln reflekterar en parallell strålknippe tillbaka mot linsen. Den andra passagen fokuserar knippet i det ursprungliga fokalplanet, på skärmen intill objektet.','Objektavståndet är fokalavståndet: f = 22,0 cm för samlingslinsen.','En ideal koaxiell modell ger också den matematiska grenen f = (22,0·38,0)/(22,0+38,0) ≈ 13,9 cm, där första bilden ligger i spegelplanet. I den idealiserade grenen kommer returstrålarna tillbaka till objektpunkten, inte till en separat skärm bredvid den; den är därför inte den vanliga autokollimationslösningen.'];
e.en.steps=['(a) In the sketch the object and screen are adjacent, the lens is 22.0 cm from the object and the plane mirror is another 38.0 cm away. The small mirror tilt separates the returning rays from the object.','(b) In autocollimation the object lies in the front focal plane of the lens. Rays from a point on the object emerge parallel after the first pass.','The mirror reflects a parallel bundle back to the lens. The second pass focuses it in the original focal plane on the adjacent screen.','The object distance is the focal distance: f = 22.0 cm for the converging lens.','An ideal coaxial model also has the mathematical branch f = (22.0·38.0)/(22.0+38.0) ≈ 13.9 cm, where the first image lies in the mirror plane. In this idealized branch the rays return to the object point, not to a separate screen beside it; it is therefore not the ordinary autocollimation solution.'];
})(window);

(function(root){'use strict';const e=root.EmberChapter34DraftExercises.find(x=>x.id==='34.13');e.solutionFigure='concave-solution-13.svg';e.solutionAlt={sv:'Tanden ligger halvvägs mellan en konkav spegels yta och fokus. Reflekterade strålars streckade förlängningar möts i en dubbelt så hög virtuell bild bakom spegeln.',en:'The tooth is halfway between a concave mirror and its focus. Dashed extensions of reflected rays meet in a virtual image twice as tall behind the mirror.'};})(window);

(function(root){'use strict';const e=root.EmberChapter34DraftExercises.find(x=>x.id==='34.89');e.solutionFigure='solution-89-two-paths.svg';e.solutionAlt={sv:'Två strålkonstruktioner: den direkta bilden är inverterad och den spegelreflekterade bilden upprätt. Båda hamnar lika långt till höger om linsen.',en:'Two ray constructions: the direct image is inverted and the mirror-reflected image upright. Both lie the same distance to the right of the lens.'};})(window);

(function(root){'use strict';const e=root.EmberChapter34DraftExercises.find(x=>x.id==='34.106');e.solutionFigure='solution-106-pencil.svg';e.solutionAlt={sv:'Pennan lutar uppåt åt höger framför linsen; den reella bilden ligger under axeln och lutar nedåt åt höger. Punkterna A, B och C motsvarar A′, B′ och C′.',en:'The pencil slopes upward to the right before the lens; the real image is below the axis and slopes downward to the right. Points A, B and C map to A′, B′ and C′.'};})(window);
